    // ---- embedded__2 ----
    embedded__2: `
  /* ===========================
     Media / Market Intelligence
  ============================ */
  .mi-head{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap: 14px;
    margin-bottom: 10px;
  }
  .mi-subtabs-row{
    display:flex;
    align-items:center;
    gap: 12px;
    flex-wrap: wrap;
    color: rgba(255,255,255,.70);
    font-size: 13px;
    letter-spacing: .2px;
  }
  .mi-pill{
    padding: 7px 12px;
    border-radius: 12px;
    background: rgba(255,255,255,.06);
    border: 1px solid rgba(255,255,255,.10);
    color: rgba(255,255,255,.86);
    font-weight: 650;
    cursor: pointer;
  }
  .mi-layout{
    display:grid;
    grid-template-columns: 360px 1fr;
    gap: 18px;
    align-items: start;
  }
  .mi-left{
    background: rgba(255,255,255,.02);
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 16px;
    overflow: hidden;
    min-width: 0;
  }
  .mi-left-scroll{
    max-height: calc(100vh - 300px);
    overflow:auto;
    padding: 12px;
    scrollbar-color: rgba(255,255,255,.25) rgba(0,0,0,.10);
    -webkit-overflow-scrolling: touch;
  }
  .mi-comp{
    background: rgba(0,0,0,.12);
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 14px;
    padding: 12px 12px 10px;
    box-shadow: 0 10px 26px rgba(0,0,0,.22);
    margin-bottom: 12px;
  }
  .mi-comp:last-child{ margin-bottom: 0; }

  .mi-comp-head{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap: 10px;
    margin-bottom: 8px;
  }
  .mi-comp-left{
    display:flex;
    align-items:center;
    gap: 10px;
    min-width: 0;
  }
  .mi-ic{
    width: 34px; height: 34px;
    border-radius: 10px;
    background: rgba(70,120,255,.22);
    border: 1px solid rgba(70,120,255,.38);
    display:grid;
    place-items:center;
    color: rgba(255,255,255,.92);
    font-weight: 850;
    flex: 0 0 auto;
  }
  .mi-ic svg{ width: 20px; height: 20px; display:block; opacity:.95; }
  .mi-ic img{ width: 28px; height: 28px; display:block; object-fit: contain; border-radius: 6px; }
  .mi-ic--group{ background: rgba(90,160,255,.22); border-color: rgba(90,160,255,.40); }
  .mi-ic--a{ background: rgba(120,210,255,.18); border-color: rgba(120,210,255,.38); }
  .mi-ic--b{ background: rgba(150,230,180,.16); border-color: rgba(150,230,180,.34); }
  .mi-ic--c{ background: rgba(255,220,120,.14); border-color: rgba(255,220,120,.32); }
  .mi-ic--d{ background: rgba(210,170,255,.14); border-color: rgba(210,170,255,.32); }
  .mi-comp-title{font-weight: 850;letter-spacing: .2px;color: rgba(255,255,255,.94);white-space: nowrap;overflow:hidden;text-overflow: ellipsis;}
  .mi-comp-meta{margin-top: 2px;font-size: 12px;color: rgba(255,255,255,.62);}
  .mi-comp-rank{font-size: 12px;color: rgba(255,255,255,.72);white-space: nowrap;}
  .mi-mini{height: 74px;width: 100%;}

  /* Hover tooltip hotspots over MI mini charts (uses existing global hover tooltip system) */
  .mi-mini-wrap{ position: relative; }
  .mi-mini-overlay{ position:absolute; inset:0; z-index: 6; pointer-events: none; }
  .mi-mini-hotspot{
    position:absolute;
    left:0; right:0;
    background: transparent;
    pointer-events: auto;
    cursor: help;
  }

.mi-right{display:flex;flex-direction: column;gap: 14px;min-width: 0;}
  .mi-right .mi-card{background: rgba(255,255,255,.02);border: 1px solid rgba(255,255,255,.08);border-radius: 16px;padding: 14px 16px;box-shadow: 0 10px 26px rgba(0,0,0,.22);min-width: 0;position: relative;}
  .mi-card h3{margin: 0 0 8px;font-size: 18px;letter-spacing: .2px;color: rgba(255,255,255,.92);}
  .mi-card ul{margin: 0;padding-left: 18px;color: rgba(255,255,255,.80);line-height: 1.55;font-size: 14px;}
  .mi-card li{ margin: 10px 0; }
  .mi-card li::marker{ color: rgba(255, 253, 93, .95); }
  .mi-grid-2{display:grid;grid-template-columns: 1fr 1fr;gap: 14px;}
  .mi-selected-header{display: flex;align-items: center;width: 100%;}
.mi-selected-left{display:flex;align-items:center;gap: 12px;}
.mi-selected-header .panel-info-btn{margin-left: auto; /* pushes icon flush right */}
.mi-selected-logo {width: 28px;height: 28px;object-fit: contain;border-radius: 6px;}
.mi-selected-logo-badge {
  width: 36px;
  height: 36px;
  border-radius: 10px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.06),
    rgba(255, 255, 255, 0.02)
  );

  border: 1px solid rgba(255, 255, 255, 0.12);

  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.04),
    0 4px 10px rgba(0, 0, 0, 0.35);}
.mi-selected-logo {width: 28px;height: 28px;object-fit: contain;border-radius: 4px;}

.competitor-group-info{
  margin-left: auto;        /* pushes it to the far right of THIS ROW */
  position: static;!important;  /* cancel panel absolute positioning */
  flex-shrink: 0;
}

  /* Responsive */
  @media (max-width: 1100px){
    .mi-layout{ grid-template-columns: 1fr; }
    .mi-left-scroll{ max-height: none; }
    .mi-grid-2{ grid-template-columns: 1fr; }
  }
`,
