function miFillSelect(sel, items, placeholder){
  if (!sel) return;
  sel.innerHTML = "";
  if (placeholder) {
    const ph = document.createElement("option");
    ph.value = "";
    ph.textContent = placeholder;
    ph.disabled = true;
    ph.selected = true;
    sel.appendChild(ph);
  }
  (items || []).forEach((t) => {
    const opt = document.createElement("option");
    opt.value = t;
    opt.textContent = t;
    sel.appendChild(opt);
  });
}

function miWireTwoTier(groupSel, itemSel, dataObj, groupPlaceholder, itemPlaceholder){
  if (!groupSel || !itemSel) return;
  const groups = Object.keys(dataObj || {});
  miFillSelect(groupSel, groups, groupPlaceholder);
  miFillSelect(itemSel, [], itemPlaceholder);
  itemSel.disabled = true;

  groupSel.addEventListener("change", () => {
    const g = groupSel.value;
    const items = (dataObj && dataObj[g]) ? dataObj[g] : [];
    miFillSelect(itemSel, items, itemPlaceholder);
    itemSel.disabled = !items.length;
  });
}


function miRenderAnglesVariableOptions(dlg, objectiveValue){
  if(!dlg) return;
  const list = dlg.querySelector('#miAnglesVariableList');
  if(!list) return;

  const items = (MI_ANGLES_VARIABLE_OPTIONS && MI_ANGLES_VARIABLE_OPTIONS[objectiveValue])
    ? MI_ANGLES_VARIABLE_OPTIONS[objectiveValue]
    : [];

  list.innerHTML = items.map((label, idx) => `
    <label class="mi-angle-radio"><input type="radio" name="miAnglesVariable" value="${escapeHtml(label)}" ${idx === 0 ? 'checked' : ''}><span>${escapeHtml(label)}</span></label>
  `).join('');
}

function miInitAnglesModal(dlg){
  if(!dlg || dlg.dataset.miAnglesInit === "1") return;
  dlg.dataset.miAnglesInit = "1";

  const syncVariables = () => {
    const checked = dlg.querySelector('input[name="miAnglesObjective"]:checked');
    miRenderAnglesVariableOptions(dlg, checked ? checked.value : 'Audience');
  };

  dlg.addEventListener('change', (ev) => {
    const target = ev.target;
    if(target && target.matches && target.matches('input[name="miAnglesObjective"]')){
      syncVariables();
    }
  });

  syncVariables();
}

function miSyncScriptLengthOtherState(dlg){
  if(!dlg) return;
  const otherRadio = dlg.querySelector('input[name="miScriptLength"][value="Other"]');
  const otherInput = dlg.querySelector('#miScriptLengthOther');
  if(!otherInput) return;

  const isOther = !!(otherRadio && otherRadio.checked);
  otherInput.disabled = !isOther;
  otherInput.setAttribute('aria-disabled', isOther ? 'false' : 'true');

  if(isOther){
    otherInput.focus();
  }else{
    otherInput.value = '';
  }
}

function getMiSelectedFormat(dlg){
  if(!dlg) return 'Story';
  const checked = dlg.querySelector('input[name="miMessageFormat"]:checked');
  return checked ? checked.value : 'Story';
}

function getMiSelectedVenues(dlg){
  if(!dlg) return [];
  const map = dlg.__miVenueSelections;
  if(!(map instanceof Map)) return [];
  const all = [];
  map.forEach((set) => {
    if(!(set instanceof Set)) return;
    set.forEach((value) => all.push(value));
  });
  return all;
}

