function miSetAnglesGenerated(value){
  window.__miAnglesGenerated = !!value;
  try{ localStorage.setItem('miAnglesGenerated', value ? '1' : '0'); }catch(e){}
  miRefreshAngleDisplays();
}

function miGetAnglesGenerated(){
  if(window.__miAnglesGenerated === true) return true;
  try{ return localStorage.getItem('miAnglesGenerated') === '1'; }catch(e){ return false; }
}

function miRenderAngleRowsForDetail(){
  const rows = [MI_ZOEY_PARENT_MESSAGE].concat(MI_ZOEY_ANGLES);
  return rows.map((a, idx) => `
    <tr data-mi-angle-id="${escapeHtml(a.id)}" class="${idx === 0 ? 'is-selected' : ''}">
      <td><a href="#" data-mi-angle-select="${escapeHtml(a.id)}">${escapeHtml(a.name)}</a></td>
      <td>${escapeHtml(a.parent)}</td>
      <td>${escapeHtml(a.start)}</td>
      <td>${escapeHtml(a.end)}</td>
    </tr>
  `).join('');
}

function miRefreshAngleDisplays(){
  const hasAngles = miGetAnglesGenerated();
  const table = document.querySelector('#brandMessageIntelligencePanel table.mi-table');
  if(table){
    table.querySelectorAll('.mi-angle-row').forEach(row => { row.hidden = true; });
    table.querySelectorAll('.mi-parent-toggle').forEach(btn => {
      btn.disabled = !hasAngles;
      btn.style.opacity = hasAngles ? '' : '.45';
      btn.setAttribute('aria-label', hasAngles ? 'Toggle message angles' : 'No angles generated yet');
      if(!hasAngles){ btn.setAttribute('aria-expanded','false'); }
    });
    table.querySelectorAll('.mi-parent-badge').forEach(b => { b.textContent = hasAngles ? '3 Angles' : 'Parent'; });
  }
  const angleBlock = document.querySelector('#miMessageDetailModal [data-mi-angle-table-block]');
  if(angleBlock){ angleBlock.hidden = !hasAngles; }
  const empty = document.querySelector('#miMessageDetailModal [data-mi-angle-empty]');
  if(empty){ empty.hidden = hasAngles; }
}

function miApplyAngleToDetail(angleId){
  if(angleId === 'parent'){ miResetDetailToParent(); return; }
  const angle = MI_ZOEY_ANGLES.find(a => a.id === angleId) || MI_ZOEY_ANGLES[0];
  const modal = document.getElementById('miMessageDetailModal');
  if(!modal || !angle) return;
  const hero = modal.querySelector('[data-mi-detail-title]');
  const sub = modal.querySelector('[data-mi-detail-subtitle]');
  const body = modal.querySelector('[data-mi-detail-body]');
  const script = modal.querySelector('[data-mi-detail-script]');
  const status = modal.querySelector('[data-mi-detail-status]');
  const venue = modal.querySelector('[data-mi-detail-venue]');
  if(hero) hero.textContent = angle.name;
  if(sub) sub.textContent = `Parent Message: ${angle.parent}`;
  if(body) body.textContent = angle.body;
  if(script) script.textContent = `${angle.version} • Parent: Zoey Cam • Status: ${angle.status || 'Testing'}`;
  if(status) status.textContent = `Status: ${angle.status || 'Testing'}`;
  if(venue) venue.textContent = `Venue: ${angle.venue || 'YouTube'}`;
  modal.querySelectorAll('[data-mi-angle-id]').forEach(row => row.classList.toggle('is-selected', row.getAttribute('data-mi-angle-id') === angle.id));
}

function miResetDetailToParent(){
  const modal = document.getElementById('miMessageDetailModal');
  if(!modal) return;
  const hero = modal.querySelector('[data-mi-detail-title]');
  const sub = modal.querySelector('[data-mi-detail-subtitle]');
  const body = modal.querySelector('[data-mi-detail-body]');
  const script = modal.querySelector('[data-mi-detail-script]');
  const status = modal.querySelector('[data-mi-detail-status]');
  const venue = modal.querySelector('[data-mi-detail-venue]');
  if(hero) hero.textContent = MI_ZOEY_PARENT_MESSAGE.name;
  if(sub) sub.textContent = 'Parent Message: Zoey Cam';
  if(body) body.textContent = MI_ZOEY_PARENT_MESSAGE.body;
  if(script) script.textContent = miGetAnglesGenerated() ? 'Parent Message (active) • 3 generated angles available below' : 'Parent Message (active) • Generate a persuasion test to create angles';
  if(status) status.textContent = 'Status: Active';
  if(venue) venue.textContent = 'Venue: YouTube';
  modal.querySelectorAll('[data-mi-angle-id]').forEach(row => row.classList.toggle('is-selected', row.getAttribute('data-mi-angle-id') === 'parent'));
}

