function miSyncBrandIntelligenceFilters(root){
  const dlg = document.getElementById('miBrandIntelligenceModal');
  if(!dlg) return;
  const typeSel = root ? root.querySelector('#miFilterType') : null;
  const venueSel = root ? root.querySelector('#miFilterVenue') : null;
  const monthSel = root ? root.querySelector('#miFilterMonth') : null;
  const val = (sel, fallback) => sel ? (sel.options[sel.selectedIndex]?.textContent || sel.value || fallback) : fallback;
  const filters = [
    ['Type', val(typeSel, 'Short-Form Video')],
    ['Venues', val(venueSel, 'All')],
    ['Post Month', val(monthSel, 'All')]
  ];
  const target = dlg.querySelector('[data-mi-brand-filter-summary]');
  if(target){
    target.innerHTML = filters.map(([label, value]) => `<span class="mi-bi-filter-chip"><b>${escapeHtml(label)}:</b> ${escapeHtml(value)}</span>`).join('');
  }
}

