function miInitCreateMessagingV3(dlg){
  if(!dlg || dlg.dataset.cmV3Bound === '1') return;
  dlg.dataset.cmV3Bound = '1';
  dlg.__cmState = { step:'scope', selectedDirection: null, saved:false, channelReady:{} };
  miRenderCreateDirections(dlg);
  miRenderCreateChannels(dlg);
  miSetCreateMessagingStep(dlg, 'scope');
  miUpdateCreateTermSidebar(dlg);

  dlg.addEventListener('click', (ev) => {
    const multiBtn = ev.target.closest('.mi-cm-multi-btn');
    if(multiBtn){ ev.preventDefault(); multiBtn.closest('[data-mi-cm-multi]')?.classList.toggle('is-open'); return; }
    if(!ev.target.closest('[data-mi-cm-multi]')) dlg.querySelectorAll('[data-mi-cm-multi].is-open').forEach(el => el.classList.remove('is-open'));

    const jump = ev.target.closest('[data-mi-cm-jump]');
    if(jump){ ev.preventDefault(); miSetCreateMessagingStep(dlg, jump.getAttribute('data-mi-cm-jump')); return; }
    if(ev.target.closest('[data-mi-cm-next]')){ ev.preventDefault(); miCreateMessagingNext(dlg); return; }
    if(ev.target.closest('[data-mi-cm-back]')){ ev.preventDefault(); miCreateMessagingBack(dlg); return; }
    if(ev.target.closest('[data-mi-cm-regenerate]')){ ev.preventDefault(); miRenderCreateDirections(dlg, true); return; }
    if(ev.target.closest('[data-mi-cm-apply-all]')){ ev.preventDefault(); miSaveCreateMessagingPrototype(dlg); return; }

    const useDir = ev.target.closest('[data-mi-cm-use-direction]');
    if(useDir){ ev.preventDefault(); miUseDirection(dlg, Number(useDir.getAttribute('data-mi-cm-use-direction'))); return; }
    const details = ev.target.closest('[data-mi-cm-view-details]');
    if(details){ ev.preventDefault(); miOpenDirectionDetails(dlg, Number(details.getAttribute('data-mi-cm-view-details'))); return; }
    const previewEdit = ev.target.closest('[data-mi-cm-preview-edit-channel]');
    if(previewEdit){ ev.preventDefault(); miOpenChannelPreviewEdit(dlg, previewEdit.getAttribute('data-mi-cm-preview-edit-channel')); return; }
    const preview = ev.target.closest('[data-mi-cm-preview-channel]');
    if(preview){ ev.preventDefault(); miOpenChannelPreviewEdit(dlg, preview.getAttribute('data-mi-cm-preview-channel')); return; }
    const edit = ev.target.closest('[data-mi-cm-edit-channel]');
    if(edit){ ev.preventDefault(); miOpenChannelPreviewEdit(dlg, edit.getAttribute('data-mi-cm-edit-channel')); return; }
    if(ev.target.closest('[data-mi-cm-close-overlay]')){ ev.preventDefault(); miCloseCreateMessagingOverlays(dlg); return; }
    if(ev.target.closest('[data-mi-cm-save-channel]')){ ev.preventDefault(); miSaveChannelEdit(dlg); return; }
    if(ev.target.closest('[data-mi-cm-save-message]')){ ev.preventDefault(); miSaveCreateMessagingPrototype(dlg); return; }
  });

  dlg.addEventListener('change', (ev) => {
    const target = ev.target;
    if(target.matches('[data-mi-cm-required], .mi-cm-multi-menu input')) miUpdateCreateRequiredRows(dlg);
    if(target.matches('[data-mi-cm-term-source]')) miUpdateCreateTermSidebar(dlg);
    if(target.matches('[data-mi-cm-followup]')) miRenderCreateFollowup(dlg, target);
    if(target.matches('.mi-cm-multi-menu input')) miUpdatePlatformSummary(dlg);
  });
  dlg.addEventListener('input', (ev) => { if(ev.target.matches('[data-mi-cm-required], textarea')) miUpdateCreateRequiredRows(dlg); });
}

function miCreateDirectionsData(variant){
  const base = [
    {title:'Urgency + Bonus', quote:'20% off ends Sunday. Don\'t miss the bonus.', tone:'Urgent + Direct', cta:'Shop before it\'s gone', impact:92, best:'Limited-time offer'},
    {title:'Value Stack', quote:'Save 20% - and get the tool everyone forgets.', tone:'Helpful + Practical', cta:'Get the full bundle', impact:88, best:'Bundle promotion'},
    {title:'Problem + Solution', quote:'Still missing the right tool? Fix it this weekend.', tone:'Relatable + Solution-Focused', cta:'Upgrade now', impact:81, best:'Need-aware audience'}
  ];
  const alt = [
    {title:'Social Proof Push', quote:'The weekend upgrade thousands are using right now.', tone:'Confident + Popular', cta:'Join them today', impact:89, best:'Warm audience'},
    {title:'Outcome First', quote:'Finish the job faster and save 20% this weekend.', tone:'Practical + Benefit-led', cta:'Get the weekend deal', impact:86, best:'Outcome-focused shoppers'},
    {title:'Simple Choice', quote:'One bundle. One weekend. Everything you need.', tone:'Clear + Minimal', cta:'Claim the bundle', impact:83, best:'Fast decision audiences'}
  ];
  return variant ? alt : base;
}

function miRenderCreateDirections(dlg, variant){
  const list = dlg.querySelector('[data-mi-cm-directions]');
  if(!list) return;
  const data = miCreateDirectionsData(variant);
  dlg.__cmDirections = data;
  list.innerHTML = data.map((d, i) => `<article class="mi-cm-direction" data-mi-cm-direction-card="${i}"><div class="mi-cm-direction-index">${i+1}</div><div class="mi-cm-direction-main"><div class="mi-cm-direction-title">${escapeHtml(d.title)}</div><div class="mi-cm-direction-quote">“${escapeHtml(d.quote)}”</div><div class="mi-cm-meta-row"><span class="mi-cm-meta">Tone <strong>${escapeHtml(d.tone)}</strong></span><span class="mi-cm-meta">CTA <strong>${escapeHtml(d.cta)}</strong></span><span class="mi-cm-meta">Best for <strong>${escapeHtml(d.best)}</strong></span></div></div><div class="mi-cm-actions-inline"><button class="mi-cm-btn" type="button" data-mi-cm-use-direction="${i}">Use This Direction</button><button class="mi-cm-btn secondary" type="button" data-mi-cm-view-details="${i}">View Details</button></div><div class="mi-cm-impact"><strong>${d.impact}%</strong><span>Predicted Impact</span></div></article>`).join('');
}

function miUseDirection(dlg, idx){
  const d = (dlg.__cmDirections || [])[idx];
  if(!d) return;
  miCloseCreateMessagingOverlays(dlg);
  dlg.__cmState.selectedDirection = d;
  dlg.querySelectorAll('[data-mi-cm-direction-card]').forEach(card => card.classList.toggle('is-selected', Number(card.getAttribute('data-mi-cm-direction-card')) === idx));
  const title = dlg.querySelector('[data-mi-cm-applying-title]');
  const quote = dlg.querySelector('[data-mi-cm-applying-quote]');
  const sum = dlg.querySelector('[data-mi-cm-summary-direction]');
  if(title) title.textContent = d.title;
  if(quote) quote.textContent = `“${d.quote}”`;
  if(sum) sum.textContent = `Direction: ${d.title}`;
  miRenderCreateChannels(dlg);
  miSetCreateMessagingStep(dlg, 'channels');
}

