function miSaveChannelEdit(dlg){
  const txt = dlg.querySelector('[data-mi-cm-channel-edit-text]')?.value || '';
  const saveBtn = dlg.querySelector('[data-mi-cm-save-channel]');
  const channelId = saveBtn ? saveBtn.getAttribute('data-channel') : '';
  const readyCb = dlg.querySelector('[data-mi-cm-ready-publish]');
  dlg.__cmState = dlg.__cmState || {};
  dlg.__cmState.channelReady = dlg.__cmState.channelReady || {};
  if(channelId) dlg.__cmState.channelReady[channelId] = !!(readyCb && readyCb.checked);
  const main = dlg.querySelector('[data-mi-cm-main-edit]'); if(main) main.value = txt;
  const final = dlg.querySelector('[data-mi-cm-final-copy]'); if(final) final.value = txt;
  miCloseCreateMessagingOverlays(dlg);
  miRenderCreateChannels(dlg);
  miSetCreateMessagingStep(dlg, 'channels');
}

