function miRenderCreateFollowup(dlg, select){
  const key = select.getAttribute('data-mi-cm-followup');
  const panel = dlg.querySelector(`[data-mi-cm-followup-panel="${key}"]`);
  if(!panel) return;
  const data = (MI_CM_FOLLOWUPS[key] && MI_CM_FOLLOWUPS[key][select.value]) || null;
  if(!data){ panel.classList.remove('is-visible'); panel.innerHTML = ''; return; }
  panel.innerHTML = `<div class="mi-cm-followup-title">More Details</div><div class="mi-cm-follow-grid">${Object.keys(data).map(label => `<div><label class="mi-muted" style="display:block; margin-bottom:5px; font-weight:800;">${escapeHtml(label)}</label><select class="mi-cm-select"><option value="">Select...</option>${miOptionsHTML(data[label])}</select></div>`).join('')}</div>`;
  panel.classList.add('is-visible');
}

function miUpdatePlatformSummary(dlg){
  const checked = Array.from(dlg.querySelectorAll('.mi-cm-multi-menu input:checked')).map(cb => cb.value);
  const btn = dlg.querySelector('#cmPlatformSummary');
  if(btn){ btn.dataset.value = checked.join(', '); btn.childNodes[0].nodeValue = checked.length ? checked.join(', ') + ' ' : 'Select platforms to align... '; }
  const sum = dlg.querySelector('[data-mi-cm-summary-platforms]');
  if(sum) sum.textContent = checked.length ? `Platforms: ${checked.join(', ')}` : 'Platforms: Instagram, TikTok, Email, Website';
  miUpdateCreateRequiredRows(dlg);
}

function miSaveCreateMessagingPrototype(dlg){
  const tbody = document.querySelector('#brandMessageIntelligencePanel table.mi-table tbody');
  if(tbody && !dlg.__cmState.saved){
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>Short-Form Video</td><td class="mi-venue">Instagram</td><td><a class="mi-a" href="#" data-mi-message="generic">Weekend Offer - Urgency + Bonus</a></td><td>ULU signalOS</td><td>May 21, 2026</td><td>June 21, 2026</td>`;
    tbody.insertBefore(tr, tbody.firstChild);
    dlg.__cmState.saved = true;
  }
  const btn = dlg.querySelector('[data-mi-cm-next]');
  if(btn){ const old = btn.textContent; btn.textContent = 'Saved'; btn.classList.add('is-dormant'); setTimeout(() => { btn.textContent = old; btn.classList.remove('is-dormant'); }, 1200); }
  if(typeof dlg.close === 'function') setTimeout(() => dlg.close(), 500); else setTimeout(() => dlg.removeAttribute('open'), 500);
}


function setMiStep(dlg, step){
  dlg.dataset.miStep = step;
  dlg.querySelectorAll(".mi-step").forEach(sec => {
    const on = sec.getAttribute("data-mi-step") === step;
    sec.style.display = on ? "" : "none";
  });

  // Update footer buttons per step
const toObj = dlg.querySelector('[data-mi-action="to-objective"]');
const toDraft = dlg.querySelector('[data-mi-action="to-draft"]');
const saveBtn = dlg.querySelector('[data-mi-action="save-draft"]');

const show = (el) => { if(!el) return; el.style.display = ""; el.style.visibility = ""; el.style.pointerEvents = ""; };
const hide = (el) => { if(!el) return; el.style.display = "none"; el.style.visibility = "hidden"; el.style.pointerEvents = "none"; };

// details = Step 4 button, objective = Generate Draft, draft = Save
if(step === "details"){
  show(toObj); hide(toDraft); hide(saveBtn);
}else if(step === "objective"){
  hide(toObj); show(toDraft); hide(saveBtn);
}else if(step === "draft"){
  hide(toObj); hide(toDraft); show(saveBtn);
}else if(step === "narrative"){
  hide(toObj); hide(toDraft); hide(saveBtn);
}
}

function openMiDialog(id, step){
  ensureMessageIntelligenceModals();
  const dlg = document.getElementById(id);
  if(!dlg) return;

  if(id === "miNewMessageModal"){
    miEnsureCreateMessagingV3Styles();
    miInitCreateMessagingV3(dlg);
    miSetCreateMessagingStep(dlg, step || "scope");
  }
  if(id === "miNewAnglesModal"){
  miInitAnglesModal(dlg);
  miInitHypothesisDropdown(dlg);
}

  if(id === "miNewMessageModal"){
    dlg.style.top = `${Math.max(24, window.scrollY + 24)}px`;
    dlg.setAttribute("open", "open");

    let backdrop = document.getElementById("miCreateMsgV3Backdrop");
    if(!backdrop){
      backdrop = document.createElement("div");
      backdrop.id = "miCreateMsgV3Backdrop";
      backdrop.className = "mi-create-msg-v3-backdrop";
      document.body.appendChild(backdrop);
      backdrop.addEventListener("click", () => {
        if(typeof dlg.close === "function") dlg.close();
        else dlg.removeAttribute("open");
      });
    }
    if(dlg.dataset.browserScrollCloseBound !== "1"){
      dlg.dataset.browserScrollCloseBound = "1";
      dlg.addEventListener("close", () => {
        const bd = document.getElementById("miCreateMsgV3Backdrop");
        if(bd) bd.remove();
        dlg.style.top = "";
      });
    }
  }else if(typeof dlg.showModal === "function") dlg.showModal();
  else dlg.setAttribute("open", "open");

  // Init gauges after open so sizing works
  requestAnimationFrame(() => requestAnimationFrame(() => {
    if(id === "miMessageDetailModal"){
      initMiGauge("miGaugeDetail", 87);
      try{
        const el = document.getElementById("miGaugeDetail");
        const inst = window.echarts && el ? window.echarts.getInstanceByDom(el) : null;
        if(inst) inst.resize();
      }catch(e){}
    }
  }));
}

function miInitHypothesisDropdown(dlg){
  if(!dlg || dlg.dataset.miHypothesisInit === "1") return;
  dlg.dataset.miHypothesisInit = "1";

  const wrap = dlg.querySelector("#miAnglesHypothesisWrap");
  const btn = dlg.querySelector("#miAnglesHypothesisBtn");
  const menu = dlg.querySelector("#miAnglesHypothesisMenu");
  const text = dlg.querySelector("#miAnglesHypothesisText");
  const input = dlg.querySelector("#miAnglesHypothesis");

  if(!wrap || !btn || !menu || !text || !input) return;

  const opts = Array.from(menu.querySelectorAll(".mi-hypothesis-opt"));

  function closeMenu(){
    wrap.classList.remove("is-open");
    btn.setAttribute("aria-expanded", "false");
    menu.hidden = true;
  }

  function openMenu(){
    wrap.classList.add("is-open");
    btn.setAttribute("aria-expanded", "true");
    menu.hidden = false;
  }

  function setValue(value){
    text.textContent = value;
    input.value = value;

    opts.forEach((opt) => {
      const selected = opt.dataset.value === value;
      opt.classList.toggle("is-selected", selected);
      opt.setAttribute("aria-selected", selected ? "true" : "false");
    });

    closeMenu();
  }

  btn.addEventListener("click", (ev) => {
    ev.preventDefault();
    ev.stopPropagation();

    if(wrap.classList.contains("is-open")) closeMenu();
    else openMenu();
  });

  opts.forEach((opt) => {
    opt.addEventListener("click", (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      setValue(opt.dataset.value || opt.textContent.trim());
    });
  });

  dlg.addEventListener("click", (ev) => {
    if(!wrap.contains(ev.target)) closeMenu();
  });

  dlg.addEventListener("keydown", (ev) => {
    if(ev.key === "Escape") closeMenu();
  });
}

function initMiGauge(elId, value){
  try{
    if(!window.echarts) return;
    const el = document.getElementById(elId);
    if(!el) return;

    // If already initialized, just update value
    let chart = window.echarts.getInstanceByDom(el);
    if(!chart) chart = window.echarts.init(el);

    const v = Math.max(0, Math.min(100, Number(value ?? 0)));

    const option = {
      backgroundColor: "transparent",
      series: [{
        type: "gauge",
        startAngle: 200,
        endAngle: -20,
        min: 0,
        max: 100,
        splitNumber: 5,
        center: ["50%","60%"],
        radius: "95%",
        axisLine: {
          lineStyle: {
            width: 18,
            color: [
              [0.35, "rgba(255, 90, 90, .85)"],
              [0.70, "rgba(255, 196, 90, .90)"],
              [1.00, "rgba(120, 255, 185, .88)"]
            ]
          }
        },
        pointer: { length: "58%", width: 5 },
        axisTick: { distance: -18, length: 6, lineStyle: { color: "rgba(255,255,255,.30)", width: 1 } },
        splitLine: { distance: -18, length: 12, lineStyle: { color: "rgba(255,255,255,.35)", width: 2 } },
        axisLabel: { color: "rgba(255,255,255,.55)", fontSize: 10, distance: -32 },
        detail: {
          valueAnimation: true,
          formatter: "{value}",
          color: "rgba(255,255,255,.95)",
          fontSize: 30,
          fontWeight: 900,
          offsetCenter: [0, "18%"]
        },
        title: {
          show: true,
          offsetCenter: [0, "46%"],
          color: "rgba(255,255,255,.60)",
          fontSize: 12,
          fontWeight: 700
        },
        data: [{ value: v, name: "Signal Score" }]
      }]
    };

    chart.setOption(option, true);
  }catch(e){
    console.warn("[signalOS] initMiGauge error", e);
  }
}

function escapeHtml(str){
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function activatePanel(mainKey = state.main, subName = state.sub) {
  const nextKey = getPanelKey(mainKey, subName);

  // Stash previous panel DOM before switching
  if (state.activePanelKey && state.activePanelKey !== nextKey) stashActivePanel();

  // Clear the live content area (we just stashed the previous)
  while (elContent.firstChild) elContent.removeChild(elContent.firstChild);
  elContent.classList.toggle("signals-content-row", nextKey === "signals/Dashboard");

  // Mount next panel DOM (either cached or freshly built)
  const { initialized } = mountPanel(nextKey);

  state.activePanelKey = nextKey;
  // Update the shared top-right info icon content/visibility
  updateTopRightInfo(mainKey, subName);
// Initialize charts only once per panel (never re-render on revisit)
  if (!initialized && window.signalCharts && typeof window.signalCharts.initForPanel === "function") {
    window.signalCharts.initForPanel(nextKey);
    localInitForPanel(nextKey);

    const entry = panelCache.get(nextKey);
    if (entry) entry.initialized = true;
  }

  // Ensure charts compute correct size after the panel is visible
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      if (window.signalCharts && typeof window.signalCharts.resizeVisible === "function") {
        window.signalCharts.resizeVisible();
      }
    });
  });
}

