// Ensure the two required organization filters are always present in the
// shared filter row. This intentionally does not rebuild the row or touch the
// dashboard content, so it cannot interfere with panel mounting.
function ensureDivisionAndBrandFiltersVisible(){
  if(!elGlobalFilters) return;

  function addRequiredFilter(filterKey){
    if(elGlobalFilters.querySelector(`.gf-dd[data-filter="${filterKey}"], .ulu-gf-control[data-filter="${filterKey}"]`)) return;
    const cfg=GLOBAL_FILTERS[filterKey];
    if(!cfg) return;

    const wrap=document.createElement('div');
    wrap.className='gf-dd';
    wrap.dataset.filter=filterKey;
    wrap.dataset.label=cfg.label;
    wrap.dataset.value=cfg.defaultValue;

    const btn=document.createElement('button');
    btn.className='gf-dd-btn';
    btn.type='button';
    btn.setAttribute('aria-haspopup','listbox');
    btn.setAttribute('aria-expanded','false');
    btn.innerHTML=`<span class="gf-dd-text">${cfg.label}: ${cfg.defaultValue}</span><span class="gf-caret" aria-hidden="true"></span>`;

    const menu=document.createElement('div');
    menu.className='gf-menu';
    menu.setAttribute('role','listbox');
    menu.hidden=true;

    cfg.options.forEach((value)=>{
      const item=document.createElement('button');
      item.type='button';
      item.className='gf-item';
      item.dataset.value=value;
      item.textContent=value;
      item.setAttribute('role','option');
      item.setAttribute('aria-selected',String(value===cfg.defaultValue));
      item.addEventListener('click',(event)=>{
        event.preventDefault();
        wrap.dataset.value=value;
        const text=wrap.querySelector('.gf-dd-text');
        if(text) text.textContent=`${cfg.label}: ${value}`;
        menu.querySelectorAll('.gf-item').forEach((option)=>{
          option.setAttribute('aria-selected',String(option===item));
        });
        wrap.classList.remove('is-open');
        btn.setAttribute('aria-expanded','false');
        menu.hidden=true;
      });
      menu.appendChild(item);
    });

    btn.addEventListener('click',(event)=>{
      event.preventDefault();
      event.stopPropagation();
      const opening=menu.hidden;
      elGlobalFilters.querySelectorAll('.gf-dd').forEach((other)=>{
        if(other===wrap) return;
        other.classList.remove('is-open');
        const otherBtn=other.querySelector('.gf-dd-btn');
        const otherMenu=other.querySelector('.gf-menu');
        if(otherBtn) otherBtn.setAttribute('aria-expanded','false');
        if(otherMenu) otherMenu.hidden=true;
      });
      wrap.classList.toggle('is-open',opening);
      btn.setAttribute('aria-expanded',String(opening));
      menu.hidden=!opening;
    });

    wrap.append(btn,menu);

    // Required order: Campaign, Division, Brand, Country, State/District.
    const controls=elGlobalFilters.querySelector('.gf-controls') || elGlobalFilters;
    const country=controls.querySelector('.gf-dd[data-filter="country"]');
    if(country && country.parentNode===controls) controls.insertBefore(wrap,country);
    else controls.appendChild(wrap);
  }

  addRequiredFilter('division');
  addRequiredFilter('brand');
}

function closeAllGlobalFilterMenus(exceptWrap){
  if (!elGlobalFilters) return;
  elGlobalFilters.querySelectorAll(".gf-dd").forEach(wrap => {
    if (exceptWrap && wrap === exceptWrap) return;
    wrap.classList.remove("is-open");
    const btn = wrap.querySelector(".gf-dd-btn");
    const menu = wrap.querySelector(".gf-menu");
    if (btn) btn.setAttribute("aria-expanded", "false");
    if (menu) menu.hidden = true;
  });
}

function setGlobalFilterValue(filterKey, value){
  if (!elGlobalFilters) return;
  const wrap = elGlobalFilters.querySelector(`.gf-dd[data-filter="${filterKey}"]`);
  if (!wrap) return;

  const label = wrap.dataset.label || (GLOBAL_FILTERS[filterKey] && GLOBAL_FILTERS[filterKey].label) || filterKey;
  wrap.dataset.value = value;

  const textEl = wrap.querySelector(".gf-dd-text");
  if (textEl) textEl.textContent = filterKey === 'timeRange' ? value : `${label}: ${value}`;

  // Update selected styles
  const menu = wrap.querySelector(".gf-menu");
  if (menu){
    menu.querySelectorAll(".gf-item").forEach(btn => {
      btn.setAttribute("aria-selected", String(btn.dataset.value === value));
    });
  }
}

