// ------------------------------------------------------------
// Generic tooltip system (Option A) — unlimited tooltips via
// data-tooltip-title + data-tooltip-body attributes.
// ------------------------------------------------------------
const tooltip = document.createElement("div");
tooltip.className = "tooltip-float";
tooltip.hidden = true;
tooltip.innerHTML = `
  <div class="tooltip-header">
    <span class="tooltip-title"></span>
    <button class="tooltip-close" type="button" aria-label="Close">×</button>
  </div>
  <div class="tooltip-divider"></div>
  <div class="tooltip-body"></div>
`;
function mountTooltipForTarget(targetEl){
  // A modal <dialog> is rendered in the browser's top layer. Any tooltip left
  // under <body> remains below that top layer and is therefore dimmed/blurred
  // by the dialog backdrop. Mount the tooltip inside the active dialog when
  // its trigger belongs to that dialog; otherwise use <body>.
  const owningDialog = targetEl && targetEl.closest
    ? targetEl.closest("dialog[open]")
    : null;
  const mountRoot = owningDialog || document.body;

  if (tooltip.parentNode !== mountRoot) mountRoot.appendChild(tooltip);

  // Keep the tooltip above every card, footer, and scrolling region inside
  // the dialog. The fixed positioning is still calculated from viewport
  // coordinates by positionTooltipNear().
  tooltip.style.zIndex = "2147483647";
  tooltip.style.pointerEvents = "auto";
  tooltip.style.filter = "none";
  tooltip.style.opacity = "1";
}

const ttTitle = tooltip.querySelector(".tooltip-title");
const ttBody  = tooltip.querySelector(".tooltip-body");
const ttClose = tooltip.querySelector(".tooltip-close");

let activeTipTarget = null;
let lastTooltipOpenAt = 0;
let lastTouchTooltipAt = 0;

function positionTooltipNear(targetEl){
  const r = targetEl.getBoundingClientRect();

  // Make tooltip measurable without flashing
  tooltip.style.visibility = "hidden";
  tooltip.hidden = false;

  const vw = document.documentElement.clientWidth;
  const vh = window.innerHeight || document.documentElement.clientHeight;
  const isMobileTooltip = vw <= 760;
  const pad = isMobileTooltip ? 16 : 10;

  // Mobile Safari can fail to display small fixed popovers near the tapped
  // target when the viewport is being resized by the browser chrome. On
  // mobile, use a centered fixed popover so the info bubble always appears.
  if (isMobileTooltip) {
    tooltip.style.position = "fixed";
    tooltip.style.width = `calc(100vw - ${pad * 2}px)`;
    tooltip.style.maxWidth = `calc(100vw - ${pad * 2}px)`;
    tooltip.style.maxHeight = `${Math.max(180, vh - pad * 2)}px`;
    tooltip.style.overflowY = "auto";

    const th = tooltip.offsetHeight;
    tooltip.style.left = `${pad}px`;
    tooltip.style.top = `${Math.max(pad, Math.round((vh - th) / 2))}px`;
    tooltip.style.transform = "none";
    tooltip.style.visibility = "";
    return;
  }

  tooltip.style.position = "fixed";
  tooltip.style.transform = "none";
  tooltip.style.width = "";
  tooltip.style.maxWidth = "";

  // Constrain tooltip to viewport height so it never forces a flip.
  // Long tooltips scroll internally instead of overflowing off-screen.
  tooltip.style.maxHeight = `${Math.max(160, vh - pad * 2)}px`;
  tooltip.style.overflowY = "auto";

  // Measure after constraints
  let tw = tooltip.offsetWidth;
  let th = tooltip.offsetHeight;

  // Default: align right edge to target right edge
  let left = r.right - tw;

  // Clamp horizontally inside viewport
  left = Math.max(pad, Math.min(left, vw - tw - pad));

  const gap = 12;
  const spaceBelow = vh - r.bottom;
  const spaceAbove = r.top;
  const placeBelow = spaceBelow >= Math.min(220, th) || spaceBelow >= spaceAbove;

  let top;
  if (placeBelow) {
    top = r.bottom + gap;
  } else {
    top = r.top - th - gap;
  }

  // Clamp vertically inside viewport
  const minTop = pad;
  const maxTop = vh - th - pad;
  top = Math.max(minTop, Math.min(top, maxTop));

  tooltip.style.left = `${left}px`;
  tooltip.style.top = `${top}px`;
  tooltip.style.visibility = "";
}

function sanitizeTooltipHTML(html){
  const tpl = document.createElement("template");
  tpl.innerHTML = html;

  const ALLOWED = new Set([
    "B","STRONG","I","EM","U","BR","P","DIV","SPAN",
    "UL","OL","LI",
    "TABLE","THEAD","TBODY","TR","TH","TD","HR"
  ]);

  // Remove dangerous nodes entirely
  tpl.content.querySelectorAll(
    "script, style, iframe, object, embed"
  ).forEach(n => n.remove());

  const walker = document.createTreeWalker(
    tpl.content,
    NodeFilter.SHOW_ELEMENT,
    null
  );

  const toRemove = [];

  while (walker.nextNode()){
    const el = walker.currentNode;

    // Remove disallowed tags but keep their children
    if (!ALLOWED.has(el.tagName)){
      const parent = el.parentNode;
      if (parent){
        while (el.firstChild){
          parent.insertBefore(el.firstChild, el);
        }
        toRemove.push(el);
      }
      continue;
    }

    // Strip unsafe attributes
    [...el.attributes].forEach(attr => {
      const name = attr.name.toLowerCase();
      const val = (attr.value || "").toLowerCase();

      if (name.startsWith("on")) el.removeAttribute(attr.name);
      if (
        (name === "href" || name === "src") &&
        val.startsWith("javascript:")
      ) el.removeAttribute(attr.name);
      if (name === "style") el.removeAttribute(attr.name);
    });
  }

  toRemove.forEach(n => n.remove());
  return tpl.innerHTML;
}

function showTooltip(targetEl){
mountTooltipForTarget(targetEl);
  const title = targetEl.getAttribute("data-tooltip-title") || "";
  const body  = targetEl.getAttribute("data-tooltip-body") || "";

  ttTitle.textContent = title;
  ttBody.innerHTML = sanitizeTooltipHTML(body);

  activeTipTarget = targetEl;
  lastTooltipOpenAt = Date.now();
  positionTooltipNear(targetEl);
}

function hideTooltip(){
  tooltip.hidden = true;
  tooltip.style.visibility = "";
  activeTipTarget = null;
}

ttClose.addEventListener("click", (e) => {
  e.preventDefault();
  hideTooltip();
});

function getTooltipEventElement(e){
  // iOS/Safari may report a text node or an inner SVG/path as the event target.
  // Walk the composed path so taps anywhere inside the circular info control
  // resolve back to the actual tooltip button.
  const path = (e && typeof e.composedPath === "function") ? e.composedPath() : [];
  for (const node of path){
    if (node && node.nodeType === 1 && node.matches && node.matches("[data-tooltip-title]")) return node;
  }
  let node = e ? e.target : null;
  if (node && node.nodeType !== 1) node = node.parentElement;
  return node && node.closest ? node.closest("[data-tooltip-title]") : null;
}

function handleTooltipActivation(e){
  const trigger = getTooltipEventElement(e);
  let rawTarget = e ? e.target : null;
  if (rawTarget && rawTarget.nodeType !== 1) rawTarget = rawTarget.parentElement;
  const clickedInsideTooltip = !!(rawTarget && tooltip.contains(rawTarget));

  if (trigger) {
    if (e.cancelable) e.preventDefault();
    e.stopPropagation();

    // Toggle if clicking/tapping the same trigger again.
    if (!tooltip.hidden && activeTipTarget === trigger) hideTooltip();
    else showTooltip(trigger);
    return true;
  }

  if (!clickedInsideTooltip && !tooltip.hidden) hideTooltip();
  return false;
}

// Use one primary activation path. pointerdown fires before mobile browsers
// synthesize hover/click behavior, so the tooltip opens reliably on the first
// tap. The click fallback supports browsers without Pointer Events and keyboard
// activation. A timestamp suppresses the synthetic click after a touch/pen tap.
document.addEventListener("pointerdown", (e) => {
  if (e.pointerType === "mouse") return;
  const handled = handleTooltipActivation(e);
  if (handled) lastTouchTooltipAt = Date.now();
}, { capture:true, passive:false });

document.addEventListener("click", (e) => {
  if (Date.now() - lastTouchTooltipAt < 800) {
    const trigger = getTooltipEventElement(e);
    if (trigger) {
      if (e.cancelable) e.preventDefault();
      e.stopPropagation();
    }
    return;
  }
  handleTooltipActivation(e);
}, true);

// The Global Filters info button is repeatedly cloned/re-parented by the filter
// renderer.  Do not rely on a listener attached to one particular instance, and
// do not route this one control through the generic tooltip event chain.  Give it
// a self-contained fixed popover mounted under <html>, just like the Calendar /
// Asset Vault modal.  This survives node replacement and cannot be hidden behind
// the app's mobile full-bleed layout or swallowed by competing filter listeners.
function getGlobalFiltersInfoTrigger(e){
  const path = (e && typeof e.composedPath === "function") ? e.composedPath() : [];
  for (const node of path){
    if (node && node.nodeType === 1 && node.id === "signalsInfoBtn") return node;
  }
  let node = e ? e.target : null;
  if (node && node.nodeType !== 1) node = node.parentElement;
  return node && node.closest ? node.closest("#signalsInfoBtn") : null;
}

let globalInfoTrigger = null;
let globalInfoOpenedAt = 0;

function ensureGlobalFiltersInfoPopover(){
  let pop = document.getElementById("uluGlobalFiltersInfoPopover");
  if (pop) return pop;

  pop = document.createElement("div");
  pop.id = "uluGlobalFiltersInfoPopover";
  pop.className = "tooltip-float";
  pop.hidden = true;
  pop.setAttribute("role", "dialog");
  pop.setAttribute("aria-modal", "false");
  pop.innerHTML = `
    <div class="tooltip-header">
      <span class="tooltip-title"></span>
      <button class="tooltip-close" type="button" aria-label="Close">×</button>
    </div>
    <div class="tooltip-divider"></div>
    <div class="tooltip-body"></div>
  `;
  // Mount outside <body> so body.ulu-mobile-full-bleed > * rules cannot change
  // its fixed positioning. Because this makes the popover a sibling of <body>,
  // it would otherwise inherit the browser/default <html> font instead of the
  // ULUsignals application font. Copy the live computed application font onto
  // the popover explicitly, and make the button inherit it as well.
  document.documentElement.appendChild(pop);
  try {
    const appFontSource = document.body || document.documentElement;
    const appFont = window.getComputedStyle(appFontSource).fontFamily;
    if (appFont) pop.style.setProperty("font-family", appFont, "important");
  } catch (_fontError) {}
  const popClose = pop.querySelector(".tooltip-close");
  if (popClose) popClose.style.setProperty("font-family", "inherit", "important");

  pop.querySelector(".tooltip-close").addEventListener("click", (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    hideGlobalFiltersInfoPopover();
  });
  return pop;
}

function positionGlobalFiltersInfoPopover(pop, trigger){
  const r = trigger.getBoundingClientRect();
  const vw = document.documentElement.clientWidth || window.innerWidth;
  const vh = window.innerHeight || document.documentElement.clientHeight;
  const mobile = vw <= 820;
  const pad = mobile ? 16 : 10;

  pop.style.position = "fixed";
  pop.style.transform = "none";
  pop.style.zIndex = "2147483647";
  pop.style.pointerEvents = "auto";
  pop.style.visibility = "hidden";
  pop.hidden = false;

  if (mobile){
    pop.style.width = `calc(100vw - ${pad * 2}px)`;
    pop.style.maxWidth = `calc(100vw - ${pad * 2}px)`;
    pop.style.maxHeight = `${Math.max(180, vh - pad * 2)}px`;
    pop.style.overflowY = "auto";
    const ph = pop.offsetHeight;
    pop.style.left = `${pad}px`;
    pop.style.top = `${Math.max(pad, Math.round((vh - ph) / 2))}px`;
  } else {
    pop.style.width = "";
    pop.style.maxWidth = "calc(100vw - 20px)";
    pop.style.maxHeight = `${Math.max(160, vh - pad * 2)}px`;
    pop.style.overflowY = "auto";
    const pw = pop.offsetWidth;
    const ph = pop.offsetHeight;
    let left = r.right - pw;
    left = Math.max(pad, Math.min(left, vw - pw - pad));
    const gap = 12;
    let top = (vh - r.bottom >= Math.min(220, ph) || vh - r.bottom >= r.top)
      ? r.bottom + gap
      : r.top - ph - gap;
    top = Math.max(pad, Math.min(top, vh - ph - pad));
    pop.style.left = `${left}px`;
    pop.style.top = `${top}px`;
  }
  pop.style.visibility = "";
}

function showGlobalFiltersInfoPopover(trigger){
  const pop = ensureGlobalFiltersInfoPopover();
  // Re-sync on every open in case the application theme/font was loaded or
  // changed after this fixed popover was first created. Prefer the live trigger
  // (which is inside the styled app shell), then fall back to <body>.
  try {
    const appFontSource = trigger || document.body || document.documentElement;
    const appFont = window.getComputedStyle(appFontSource).fontFamily;
    if (appFont) pop.style.setProperty("font-family", appFont, "important");
  } catch (_fontError) {}
  const title = trigger.getAttribute("data-tooltip-title") || "Global Filters";
  const body = trigger.getAttribute("data-tooltip-body") || "Use these filters to refine the audience intelligence displayed on the current tab.";
  pop.querySelector(".tooltip-title").textContent = title;
  pop.querySelector(".tooltip-body").innerHTML = sanitizeTooltipHTML(body);
  globalInfoTrigger = trigger;
  globalInfoOpenedAt = Date.now();
  positionGlobalFiltersInfoPopover(pop, trigger);
}

function hideGlobalFiltersInfoPopover(){
  const pop = document.getElementById("uluGlobalFiltersInfoPopover");
  if (pop){
    pop.hidden = true;
    pop.style.visibility = "";
  }
  globalInfoTrigger = null;
}

function activateGlobalFiltersInfo(e){
  const trigger = getGlobalFiltersInfoTrigger(e);
  if (!trigger) return false;
  if (e.cancelable) e.preventDefault();
  e.stopPropagation();
  if (typeof e.stopImmediatePropagation === "function") e.stopImmediatePropagation();

  const pop = document.getElementById("uluGlobalFiltersInfoPopover");
  if (pop && !pop.hidden && globalInfoTrigger === trigger) hideGlobalFiltersInfoPopover();
  else showGlobalFiltersInfoPopover(trigger);
  return true;
}

// pointerdown is used for mouse, pen, and touch so the control activates before
// any later filter-row handler has an opportunity to cancel the event.
window.addEventListener("pointerdown", (e) => {
  if (activateGlobalFiltersInfo(e)) globalInfoOpenedAt = Date.now();
}, { capture:true, passive:false });

// Keyboard activation and older browsers still produce click without a useful
// pointer event. Suppress the synthetic click that follows pointerdown.
window.addEventListener("click", (e) => {
  const trigger = getGlobalFiltersInfoTrigger(e);
  if (!trigger) return;
  if (Date.now() - globalInfoOpenedAt < 650) {
    if (e.cancelable) e.preventDefault();
    e.stopPropagation();
    if (typeof e.stopImmediatePropagation === "function") e.stopImmediatePropagation();
    return;
  }
  activateGlobalFiltersInfo(e);
}, { capture:true, passive:false });

// Close when clicking elsewhere, pressing Escape, scrolling, or resizing.
document.addEventListener("pointerdown", (e) => {
  const pop = document.getElementById("uluGlobalFiltersInfoPopover");
  if (!pop || pop.hidden) return;
  const t = e.target && e.target.nodeType === 1 ? e.target : e.target && e.target.parentElement;
  if (t && (pop.contains(t) || (t.closest && t.closest("#signalsInfoBtn")))) return;
  hideGlobalFiltersInfoPopover();
}, true);
document.addEventListener("keydown", (e) => { if (e.key === "Escape") hideGlobalFiltersInfoPopover(); });
window.addEventListener("scroll", () => { if (Date.now() - globalInfoOpenedAt > 300) hideGlobalFiltersInfoPopover(); }, {passive:true});
window.addEventListener("resize", () => {
  const pop = document.getElementById("uluGlobalFiltersInfoPopover");
  if (!pop || pop.hidden || !globalInfoTrigger || !document.contains(globalInfoTrigger)) return;
  requestAnimationFrame(() => positionGlobalFiltersInfoPopover(pop, globalInfoTrigger));
}, {passive:true});

// ------------------------------------------------------------
// Rollover (hover) tooltips for elements with:
// data-tooltip-title + data-tooltip-body + data-tooltip-trigger="hover"
// ------------------------------------------------------------
let hoverOpenTimer = null;
let hoverCloseTimer = null;

function isHoverTrigger(el){
  return !!(el && el.getAttribute && el.getAttribute("data-tooltip-trigger") === "hover");
}

document.addEventListener("mouseover", (e) => {
  if (window.matchMedia && window.matchMedia("(hover: none), (pointer: coarse)").matches) return;
  const trigger = e.target.closest("[data-tooltip-title][data-tooltip-trigger='hover']");
  if (!trigger) return;

  // Cancel any close in progress
  if (hoverCloseTimer) { clearTimeout(hoverCloseTimer); hoverCloseTimer = null; }

  // Small delay prevents flicker when moving across elements
  if (hoverOpenTimer) clearTimeout(hoverOpenTimer);
  hoverOpenTimer = setTimeout(() => {
    showTooltip(trigger);
  }, 120);
});

document.addEventListener("mouseout", (e) => {
  if (window.matchMedia && window.matchMedia("(hover: none), (pointer: coarse)").matches) return;
  const trigger = e.target.closest("[data-tooltip-title][data-tooltip-trigger='hover']");
  if (!trigger) return;

  // If moving into the tooltip itself, don’t close
  const toEl = e.relatedTarget;
  if (toEl && tooltip.contains(toEl)) return;

  if (hoverOpenTimer) { clearTimeout(hoverOpenTimer); hoverOpenTimer = null; }

  // Close after a short delay (lets user “land” on nearby elements)
  if (hoverCloseTimer) clearTimeout(hoverCloseTimer);
  hoverCloseTimer = setTimeout(() => {
    // Only close if the active target is a hover target
    if (activeTipTarget && isHoverTrigger(activeTipTarget)) hideTooltip();
  }, 140);
});

// Keep tooltip open if user hovers the tooltip itself
tooltip.addEventListener("mouseover", () => {
  if (hoverCloseTimer) { clearTimeout(hoverCloseTimer); hoverCloseTimer = null; }
});
tooltip.addEventListener("mouseout", (e) => {
  const toEl = e.relatedTarget;
  if (toEl && (tooltip.contains(toEl) || isHoverTrigger(toEl.closest?.("[data-tooltip-trigger='hover']")))) return;

  if (hoverCloseTimer) clearTimeout(hoverCloseTimer);
  hoverCloseTimer = setTimeout(() => {
    if (activeTipTarget && isHoverTrigger(activeTipTarget)) hideTooltip();
  }, 140);
});



document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !tooltip.hidden) hideTooltip();
});

window.addEventListener("scroll", () => {
  // On mobile, tapping an info icon can trigger a tiny browser-chrome scroll
  // event immediately after the tooltip opens. Do not close it instantly.
  if (!tooltip.hidden && Date.now() - lastTooltipOpenAt > 450) hideTooltip();
}, { passive: true });

window.addEventListener("resize", () => {
  if (tooltip.hidden || !activeTipTarget) return;
  // Mobile browser chrome commonly emits resize events during a tap. Keeping
  // the tooltip open and recalculating its position avoids an open-then-close
  // flash that made the control appear nonfunctional.
  requestAnimationFrame(() => {
    if (!tooltip.hidden && activeTipTarget && document.contains(activeTipTarget)) {
      positionTooltipNear(activeTipTarget);
    }
  });
});

