// Binds hover tooltips to Market Intelligence chart DOM nodes.
// Works with either:
// 1) explicit markers: <div data-mi-metric="narrativeDiff" ...>
// 2) known IDs (if charts are mounted by external modules)
// 3) ECharts mouseover events (preferred: tooltips appear only when hovering chart elements)
function initMediaMarketIntelligenceHoverTooltips(){
  const root = document.getElementById("mediaMarketIntelligencePanel") || document;
  if (!root) return;

  // Build (or rebuild) overlay hover targets for every MI mini-chart based on the
  // chart’s actual category labels (so every competitor chart can have a different set/order of bars).
  if (!window.echarts || typeof window.echarts.getInstanceByDom !== "function") return;

  // Map visible row labels -> MI_ROLLOVER_TOOLTIPS keys
  const labelToKey = (labelRaw) => {
    const label = String(labelRaw || "").trim();
    const norm = label.toLowerCase()
      .replace(/[–—]/g, "-")
      .replace(/\s+/g, " ")
      .replace(/[^\w\s\-\+\/]/g, "")
      .trim();

    const map = {
      "narrative differentiation": "narrativeDiff",
      "relative position": "relativePosition",
      "audience recall": "audienceRecall",
      "signal reinforcement": "signalReinforcement",
      "signal reinforcement+": "signalReinforcementPlus",
      "signal reinforcement +": "signalReinforcementPlus",
      "falling recall": "fallingRecall",
      "signal decline": "signalDecline",
      "signal decline / falling recall": "signalDecline",
      "signal decline/falling recall": "signalDecline"
    };
    return map[norm] || null;
  };

  // Helper to read the category labels from an ECharts instance
  const getCategories = (chart) => {
    try{
      const opt = chart.getOption && chart.getOption();
      const y = opt && opt.yAxis && opt.yAxis[0];
      const x = opt && opt.xAxis && opt.xAxis[0];

      const asBool = (v) => {
        if (Array.isArray(v)) v = v[0];
        return (v === true || v === 1 || v === "true");
      };

      // Most of your MI mini charts are horizontal bars with category y-axis
      // ECharts renders the first category at the *bottom* when inverse is false,
      // so to map overlay rows top→bottom we reverse unless the axis is inverted.
      if (y && Array.isArray(y.data) && y.data.length) {
        const cats = y.data.slice();
        return asBool(y.inverse) ? cats : cats.reverse();
      }

      // Fallback: vertical charts (category x-axis)
      // For x-axis categories, left→right matches data order unless inverse is true.
      if (x && Array.isArray(x.data) && x.data.length) {
        const cats = x.data.slice();
        return asBool(x.inverse) ? cats.reverse() : cats;
      }
    }catch(e){}
    return null;
  };

  const buildOverlays = () => {
    let pending = 0;

    root.querySelectorAll(".mi-mini-wrap").forEach(wrap => {
      const chartEl = wrap.querySelector(".echart.mi-mini");
      if (!chartEl) return;

      const chart = window.echarts.getInstanceByDom(chartEl);
      if (!chart){
        pending++;
        return;
      }

      const categories = getCategories(chart);
      if (!categories || !categories.length){
        pending++;
        return;
      }

      // Ensure overlay container exists
      let overlay = wrap.querySelector(".mi-mini-overlay");
      if (!overlay){
        overlay = document.createElement("div");
        overlay.className = "mi-mini-overlay";
        overlay.setAttribute("aria-hidden", "true");
        wrap.appendChild(overlay);
      }

      // Build hotspots only once per chart version (but allow rebuild if categories changed)
      const sig = categories.join("|");
      if (overlay.dataset.miSig === sig) return;
      overlay.dataset.miSig = sig;

      overlay.innerHTML = "";

      const rows = categories.length;
      const rowH = 100 / rows;

      categories.forEach((label, i) => {
        const key = labelToKey(label);
        const tip = key ? MI_ROLLOVER_TOOLTIPS[key] : null;

        // If we don't have tooltip copy for a label yet, still create a hotspot with a sensible fallback.
        const title = tip ? tip.title : String(label).trim();
        const body  = tip ? tip.body  : `<p>${String(label).trim()}</p>`;

        const hs = document.createElement("div");
        hs.className = "mi-mini-hotspot";
        hs.style.top = (i * rowH) + "%";
        hs.style.height = rowH + "%";

        hs.setAttribute("data-tooltip-trigger", "hover");
        hs.setAttribute("data-tooltip-title", title);
        hs.setAttribute("data-tooltip-body", body);

        overlay.appendChild(hs);
      });
    });

    return pending;
  };

  // Retry a few times because charts may initialize after the panel HTML renders
  let tries = 0;
  const maxTries = 20;

  const tick = () => {
    tries++;
    const pending = buildOverlays();
    if (pending > 0 && tries < maxTries){
      setTimeout(tick, 150);
    }
  };

  tick();
}



