function updateTopRightInfo(mainKey, subName){
  if (!elInfoBtn) return;

  if (mainKey === "signals") {
    const entry = SIGNALS_SUBTAB_INFO[subName] || SIGNALS_SUBTAB_INFO["Dashboard"] || SIGNALS_SUBTAB_INFO["Overview"];
    elInfoBtn.setAttribute("data-tooltip-title", entry.title);
    elInfoBtn.setAttribute("data-tooltip-body", entry.body);
    setSignalsInfoVisible(true);
    return;
  }

  if (mainKey === "brand") {
    const canonicalSub = canonicalSubtabName("brand", subName);
    const entry = BRAND_SUBTAB_INFO[canonicalSub] || BRAND_SUBTAB_INFO["Library"];
    elInfoBtn.setAttribute("data-tooltip-title", entry.title);
    elInfoBtn.setAttribute("data-tooltip-body", entry.body);
    setSignalsInfoVisible(true);
    return;
  }

  if (mainKey === "media") {
    const entry = MEDIA_SUBTAB_INFO[subName] || MEDIA_SUBTAB_INFO["Overview"];
    elInfoBtn.setAttribute("data-tooltip-title", entry.title);
    elInfoBtn.setAttribute("data-tooltip-body", entry.body);
    setSignalsInfoVisible(true);
    return;
  }

  // Hide on other main tabs for now
  setSignalsInfoVisible(false);
}


