// Desktop Media dashboard: remove the two explanatory cards that were rendered
// inside the Audience Journey ECharts graphic ("AL Interpretation" and
// "Recommended Action") and reclaim the vertical space they occupied.
// The mobile chart is intentionally left unchanged.
function compactMediaAudienceJourneyChart(){
  const el = document.getElementById('chart-media-journey');
  if(!el || !window.echarts || typeof window.echarts.getInstanceByDom !== 'function') return;

  const DESKTOP_HEIGHT = 208;
  const targets = ['AL Interpretation', 'Recommended Action'];

  function textValue(node){
    if(!node || typeof node !== 'object') return '';
    const values = [];
    if(typeof node.text === 'string') values.push(node.text);
    if(node.style && typeof node.style.text === 'string') values.push(node.style.text);
    if(node.style && typeof node.style.rich === 'object'){
      try{
        Object.keys(node.style.rich).forEach(function(k){
          const r = node.style.rich[k];
          if(r && typeof r.text === 'string') values.push(r.text);
        });
      }catch(_e){}
    }
    return values.join(' ');
  }

  function subtreeHasTarget(node){
    if(!node || typeof node !== 'object') return false;
    const own = textValue(node);
    if(targets.some(function(t){ return own.indexOf(t) !== -1; })) return true;
    const kids = Array.isArray(node.children) ? node.children : [];
    return kids.some(subtreeHasTarget);
  }

  function pruneGraphicNode(node){
    if(!node || typeof node !== 'object') return node;
    const copy = Array.isArray(node) ? node.slice() : Object.assign({}, node);
    if(Array.isArray(copy.children)){
      copy.children = copy.children
        .filter(function(child){
          // The two footer cards are grouped graphics. Removing the matching
          // group removes its background, heading and explanatory copy together.
          return !(child && child.type === 'group' && subtreeHasTarget(child));
        })
        .map(pruneGraphicNode);
    }
    if(Array.isArray(copy.elements)){
      copy.elements = copy.elements
        .filter(function(child){
          return !(child && child.type === 'group' && subtreeHasTarget(child));
        })
        .map(pruneGraphicNode);
    }
    return copy;
  }

  function apply(){
    const chart = window.echarts.getInstanceByDom(el);
    if(!chart) return false;

    const isDesktop = window.matchMedia ? window.matchMedia('(min-width: 821px)').matches : window.innerWidth > 820;
    if(!el.__uluJourneyOriginalGraphic){
      try{
        const option = chart.getOption && chart.getOption();
        if(option && Array.isArray(option.graphic)){
          el.__uluJourneyOriginalGraphic = JSON.parse(JSON.stringify(option.graphic));
        }
      }catch(_e){}
    }

    try{
      if(isDesktop){
        const option = chart.getOption && chart.getOption();
        if(option && Array.isArray(option.graphic)){
          // IMPORTANT: the footer cards can themselves be top-level `graphic`
          // groups. The previous v33 code only pruned matching child groups,
          // so a top-level AL Interpretation / Recommended Action group survived.
          const cleaned = option.graphic
            .filter(function(node){ return !subtreeHasTarget(node); })
            .map(pruneGraphicNode);
          chart.setOption({ graphic: cleaned }, { replaceMerge: ['graphic'], lazyUpdate: false });
        }
        el.style.height = DESKTOP_HEIGHT + 'px';
      }else{
        if(el.__uluJourneyOriginalGraphic){
          chart.setOption({ graphic: JSON.parse(JSON.stringify(el.__uluJourneyOriginalGraphic)) }, { replaceMerge: ['graphic'], lazyUpdate: false });
        }
        el.style.removeProperty('height');
      }
      chart.resize();
      return true;
    }catch(_e){
      return false;
    }
  }

  // ChartManager initializes asynchronously relative to the panel mount, so retry
  // briefly until the ECharts instance exists and then keep desktop/mobile state
  // correct if the viewport crosses the 820px breakpoint.
  // The Media chart can be redrawn shortly after panel initialization. Reapply
  // the desktop cleanup across that initialization window so a later setOption()
  // cannot restore the two footer cards after we have removed them.
  [0, 80, 180, 360, 700, 1200].forEach(function(delay){
    setTimeout(function(){ apply(); }, delay);
  });

  if(!window.__uluMediaJourneyCompactResizeBound){
    window.__uluMediaJourneyCompactResizeBound = true;
    window.addEventListener('resize', function(){
      requestAnimationFrame(function(){
        try{ compactMediaAudienceJourneyChart(); }catch(_e){}
      });
    }, { passive:true });
  }
}

