    let lastMobileRowMenuTouchAt=0;
    function bindMobileRowActionTriggers(){
      root.querySelectorAll('[data-bv-row-menu]').forEach(button=>{
        if(button.dataset.bvMobileMenuBound==='1')return;
        button.dataset.bvMobileMenuBound='1';
        const isMobile=()=>window.matchMedia&&window.matchMedia('(max-width:820px)').matches;
        const activate=(e)=>{
          if(!isMobile())return false;
          if(e&&e.cancelable)e.preventDefault();
          if(e){e.stopPropagation();if(typeof e.stopImmediatePropagation==='function')e.stopImmediatePropagation()}
          const idx=+(button.dataset.index||0);
          if(rowActionMenu&&rowActionMenu.dataset.index===String(idx))closeRowActionMenu();
          else openRowActionMenu(button,idx);
          return true;
        };
        /* Dedicated mobile control: use Pointer Events first because they are
           supported by current iOS Safari and Chrome. This fires directly on
           the 42px absolute-positioned mobile button, before the card row can
           interpret the gesture as a request to open Communication Detail. */
        button.addEventListener('pointerup',e=>{
          if(!isMobile())return;
          if(activate(e))lastMobileRowMenuTouchAt=Date.now();
        },{passive:false});
        /* Fallback for older WebKit paths that may still deliver touch events. */
        button.addEventListener('touchend',e=>{
          if(!isMobile())return;
          if(Date.now()-lastMobileRowMenuTouchAt<250){if(e.cancelable)e.preventDefault();e.stopPropagation();return}
          if(activate(e))lastMobileRowMenuTouchAt=Date.now();
        },{passive:false});
        /* Suppress the compatibility click following pointer/touch activation;
           keyboard/accessibility clicks still open the menu normally. */
        button.addEventListener('click',e=>{
          if(!isMobile())return;
          if(Date.now()-lastMobileRowMenuTouchAt<1000){
            if(e.cancelable)e.preventDefault();
            e.stopPropagation();
            if(typeof e.stopImmediatePropagation==='function')e.stopImmediatePropagation();
            return;
          }
          activate(e);
        });
      });
    }
    function openRowActionMenu(button,index){
      closeRowActionMenu();
      const r=comms[index];if(!r)return;
      const menu=document.createElement('div');
      const mobileRowMenu=window.matchMedia&&window.matchMedia('(max-width:820px)').matches;
      menu.className=mobileRowMenu?'bv-row-action-menu bv-mobile-row-action-menu':'bv-row-action-menu';
      menu.setAttribute('role','menu');menu.dataset.index=String(index);menu.innerHTML=rowActionMenuHTML(index);
      /* v11 mobile fix: keep the menu in the valid BODY portal and give it a
         dedicated mobile class that explicitly overrides the app's generic
         body > * full-bleed rule. Appending popup UI under <html> proved
         unreliable on iOS WebKit/Chrome. */
      document.body.appendChild(menu);rowActionMenu=menu;button.setAttribute('aria-expanded','true');
      const rect=button.getBoundingClientRect();
      const width=menu.offsetWidth||246;const height=menu.offsetHeight||430;
      let left=rect.right-width;let top=rect.bottom+6;
      if(left<8)left=8;if(left+width>window.innerWidth-8)left=window.innerWidth-width-8;
      if(top+height>window.innerHeight-8)top=Math.max(8,rect.top-height-6);
      menu.style.left=`${left}px`;menu.style.top=`${top}px`;
      const first=menu.querySelector('.bv-row-action-btn');
      /* Do not move focus on mobile. iOS can emit a scroll event when focus is
         moved into a newly-mounted fixed popup; the legacy global scroll-close
         listener would then remove the menu before it ever became visible. */
      if(first&&!mobileRowMenu){try{first.focus({preventScroll:true})}catch(_e){first.focus()}}
    }
