      if(selection.type==='communication'||selection.type==='version') parts.push({label:'Communication',attrs:selection.type==='communication'?'':`data-bv-select-node data-type="communication" data-strategy="${selection.strategyAngleIndex}" data-communication="${selection.communicationIndex}"`});
      if(selection.type==='version') parts.push({label:'Version',attrs:''});
      return parts.map((part,i)=>`${i?'<span>›</span>':''}${i===parts.length-1?`<strong>${part.label}</strong>`:`<button ${part.attrs}>${part.label}</button>`}`).join('');
