    function bvEnsureDeleteUnavailableTooltip(){
      let tip=document.getElementById('bvDeleteUnavailableTooltip');
      if(tip)return tip;
      tip=document.createElement('div');
      tip.id='bvDeleteUnavailableTooltip';
      tip.className='bv-delete-unavailable-tooltip';
      tip.setAttribute('role','tooltip');
      tip.textContent='Delete function only available when a Version is displayed in the workspace below';
      document.body.appendChild(tip);
      return tip;
    }
    function bvPositionDeleteUnavailableTooltip(tip,button){
      if(!tip||!button)return;
      const pad=12,gap=8;
      const br=button.getBoundingClientRect();
      const vv=window.visualViewport;
      const viewportLeft=vv?vv.offsetLeft:0;
      const viewportTop=vv?vv.offsetTop:0;
      const viewportWidth=vv?vv.width:window.innerWidth;
      const viewportHeight=vv?vv.height:window.innerHeight;
      tip.classList.add('is-visible');
      /* The mobile full-bleed rules use !important positioning. Feed the
         calculated coordinates through CSS variables so the tooltip remains
         anchored to the Delete control instead of being forced to 0,0. */
      tip.style.setProperty('--bv-delete-tip-left',(viewportLeft+pad)+'px');
      tip.style.setProperty('--bv-delete-tip-top',(viewportTop+pad)+'px');
      if(window.innerWidth<=820){
        tip.style.left='';
        tip.style.top='';
      }else{
        tip.style.left='0px';
        tip.style.top='0px';
      }
      const tr=tip.getBoundingClientRect();
      let left=br.left+(br.width-tr.width)/2;
      left=Math.max(viewportLeft+pad,Math.min(left,viewportLeft+viewportWidth-tr.width-pad));
      /* On phones this guidance belongs to the control that triggered it: keep
         it immediately above Delete, only clamping to the visible viewport. */
      let top=br.top-tr.height-gap;
      if(window.innerWidth>820 && top<viewportTop+pad)top=br.bottom+gap;
      const viewportBottom=viewportTop+viewportHeight;
      if(top+tr.height>viewportBottom-pad)top=viewportBottom-tr.height-pad;
      if(top<viewportTop+pad)top=viewportTop+pad;
      if(window.innerWidth<=820){
        tip.style.setProperty('--bv-delete-tip-left',Math.round(left)+'px');
        tip.style.setProperty('--bv-delete-tip-top',Math.round(top)+'px');
      }else{
        tip.style.left=Math.round(left)+'px';
        tip.style.top=Math.round(top)+'px';
      }
    }
    function bvShowDeleteUnavailableTooltip(button){
      if(!button)return;
      const tip=bvEnsureDeleteUnavailableTooltip();
      tip.textContent='Delete function only available when a Version is displayed in the workspace below';
      tip.classList.add('is-visible');
      button.setAttribute('aria-describedby',tip.id);
      bvPositionDeleteUnavailableTooltip(tip,button);
      clearTimeout(bvShowDeleteUnavailableTooltip._timer);
      bvShowDeleteUnavailableTooltip._timer=setTimeout(()=>bvHideDeleteUnavailableTooltip(button),3200);
    }
    function bvHideDeleteUnavailableTooltip(button){
      const tip=document.getElementById('bvDeleteUnavailableTooltip');
      if(tip)tip.classList.remove('is-visible');
      if(button)button.removeAttribute('aria-describedby');
      clearTimeout(bvShowDeleteUnavailableTooltip._timer);
    }

