      if(!communicationDlg){communicationDlg=document.createElement('dialog');communicationDlg.id='bvCommunicationCreateModal';communicationDlg.className='bv-modal bv-hierarchy-creation-modal';document.body.appendChild(communicationDlg);communicationDlg.addEventListener('click',e=>{if(e.target===communicationDlg||e.target.closest('[data-bv-creation-close]')){e.preventDefault();communicationDlg.close();return}if(e.target.closest('[data-bv-communication-create]')){e.preventDefault();const idx=+(communicationDlg.dataset.index||currentDetailIndex);const parent=comms[idx]||comms[0];const si=+(communicationDlg.dataset.strategy||0);const angle=strategyAngleNodes(parent,idx)[si];if(!angle)return;const count=Math.max(1,Math.min(6,+(communicationDlg.querySelector('[data-bv-communication-version-count]')?.value||1)));const name=(communicationDlg.querySelector('[data-bv-communication-name]')?.value||`${angle.name} Communication`).trim();const platform=communicationDlg.querySelector('[data-bv-communication-platform]')?.value||'LinkedIn';const brief=communicationDlg.querySelector('[data-bv-communication-brief]')?.value||angle.premise||'';const versions=Array.from({length:count},(_,vi)=>({type:'version',name:`${name} - Version ${vi+1}`,status:'Draft',platform,promoted:false,body:`${name} - Version ${vi+1}\n\n${brief}\n\nVersion ${vi+1} was created with this new Communication under the “${angle.name}” Strategy Angle.`}));const group={type:'communication',name,status:'Draft',platform,promoted:false,body:`${name}\n\n${brief}`,versions,generated:true,strategyAngleIndex:si,strategyAngleName:angle.name,createdAt:new Date().toISOString()};const key=String(parent[12]||parent[0]);const existing=generatedVersionNodesByCommunication.get(key)||[];generatedVersionNodesByCommunication.set(key,existing.concat(group));parent[3]=Number(parent[3]||0)+count;communicationDlg.close();const all=communicationVersionNodes(parent);const c=all[all.length-1];currentDetailSelection=c.versions[0]||c;detail(idx,'angles',currentDetailSelection);}});communicationDlg.addEventListener('cancel',e=>{e.preventDefault();communicationDlg.close()});}
      let versionDlg=document.getElementById('bvVersionCreateModal');
      if(!versionDlg){versionDlg=document.createElement('dialog');versionDlg.id='bvVersionCreateModal';versionDlg.className='bv-modal bv-hierarchy-creation-modal';document.body.appendChild(versionDlg);versionDlg.addEventListener('click',e=>{if(e.target===versionDlg||e.target.closest('[data-bv-creation-close]')){e.preventDefault();versionDlg.close();return}if(e.target.closest('[data-bv-version-create]')){e.preventDefault();const idx=+(versionDlg.dataset.index||currentDetailIndex);const parent=comms[idx]||comms[0];const ci=+(versionDlg.dataset.communication||0);const communication=communicationVersionNodes(parent)[ci];if(!communication)return;const count=Math.max(1,Math.min(6,+(versionDlg.querySelector('[data-bv-version-count]')?.value||1)));const focus=versionDlg.querySelector('[data-bv-version-focus]')?.value||'alternative execution';const platform=versionDlg.querySelector('[data-bv-version-platform]')?.value||communication.platform;const instructions=(versionDlg.querySelector('[data-bv-version-instructions]')?.value||'').trim();const existingExtras=generatedExtraVersionsByCommunication.get(communicationExtraVersionKey(parent,communication))||[];const start=communication.versions.length+1;const extras=Array.from({length:count},(_,i)=>({type:'version',name:`${communication.name} - Version ${start+i}`,status:'Draft',platform,promoted:false,body:`${communication.name} - Version ${start+i}\n\nThis Version tests ${focus.toLowerCase()} while remaining a child of “${communication.name}”.${instructions?`\n\nAdditional instructions: ${instructions}`:''}`}));generatedExtraVersionsByCommunication.set(communicationExtraVersionKey(parent,communication),existingExtras.concat(extras));parent[3]=Number(parent[3]||0)+count;versionDlg.close();const updated=communicationVersionNodes(parent)[ci];currentDetailSelection=updated.versions[updated.versions.length-count]||updated;detail(idx,'angles',currentDetailSelection);}});versionDlg.addEventListener('cancel',e=>{e.preventDefault();versionDlg.close()});}
      return {communicationDlg,versionDlg};
