    function openCommunicationModal(strategyIndex){const parent=comms[currentDetailIndex]||comms[0];const selection=detailSelectionFor(parent);const hasStrategyIndex=strategyIndex!==null&&strategyIndex!==undefined&&String(strategyIndex)!=='';const si=hasStrategyIndex&&Number.isFinite(Number(strategyIndex))?Number(strategyIndex):Number(selection.strategyAngleIndex);const angle=strategyAngleNodes(parent,currentDetailIndex)[si];if(!angle)return;const {communicationDlg}=ensureHierarchyCreationDialogs();communicationDlg.dataset.index=String(currentDetailIndex);communicationDlg.dataset.strategy=String(si);communicationDlg.innerHTML=bvCommunicationModalHTML(parent,angle);communicationDlg.showModal();}
    function openVersionModal(communicationIndex){const parent=comms[currentDetailIndex]||comms[0];const selection=detailSelectionFor(parent);const hasCommunicationIndex=communicationIndex!==null&&communicationIndex!==undefined&&String(communicationIndex)!=='';const ci=hasCommunicationIndex&&Number.isFinite(Number(communicationIndex))?Number(communicationIndex):Number(selection.communicationIndex);const communication=communicationVersionNodes(parent)[ci];if(!communication)return;const {versionDlg}=ensureHierarchyCreationDialogs();versionDlg.dataset.index=String(currentDetailIndex);versionDlg.dataset.communication=String(ci);versionDlg.innerHTML=bvVersionModalHTML(parent,communication);versionDlg.showModal();}
    function generateStrategyRecords(dlg){
      const idx=+(dlg.dataset.index||currentDetailIndex||0);
      const parent=comms[idx]||comms[0];
      const mode=dlg.dataset.mode||'recommended';
      const baseName=(dlg.querySelector('[data-bv-strategy-name]')?.value||'New Strategy').trim()||'New Strategy';
      const versions=Math.max(1,Math.min(6,+(dlg.querySelector('[data-bv-strategy-versions]')?.value||3)));
      const duration=Math.max(5,+(dlg.querySelector('[data-bv-strategy-duration]')?.value||60));
      const platforms=[...dlg.querySelectorAll('[data-bv-strategy-platform]:checked')].map(x=>x.value);
      const selectedPlatforms=platforms.length?platforms:['LinkedIn'];
      const recommendedKey=dlg.querySelector('input[name="bvRecommendedStrategy"]:checked')?.value||'best';
      const selected=(BV_STRATEGY_MODAL_DATA.recommended.find(x=>x[0]===recommendedKey)||BV_STRATEGY_MODAL_DATA.recommended[0]);
      const adv=Object.fromEntries([...dlg.querySelectorAll('[data-bv-advanced]')].map(x=>[x.dataset.bvAdvanced,x.value]));
      const seeds=mode==='advanced'
        ? [adv.angle||adv.purpose||baseName,adv.emotion?`${adv.emotion} Response`:'Audience Resonance',adv.theme?`${adv.theme} Advantage`:'Distinctive Value']
        : ({best:['Trust Through Proof','Audience-First Value','Authentic Founder Perspective'],emotional:['Emotional Connection','Human Stakes','Shared Aspiration'],educational:['Practical Education','Myth to Insight','Actionable Framework'],contrarian:['Challenge the Default','What Everyone Gets Wrong','A Better Point of View'],founder:['Founder Journey','The Lesson Behind the Build','Why We Started'],sales:['Value and Urgency','Proof That Converts','Outcome-Focused Offer'],engagement:['Curiosity Hook','Conversation Starter','Shareable Insight'],audience:['New Audience Bridge','Adjacent Need','Unexpected Use Case'],competitor:['Category Difference','Why This Approach Wins','The Alternative to Status Quo'],surprise:['Hidden Audience Signal','Unexpected Emotional Driver','Emerging Opportunity']}[recommendedKey]||['Trust Through Proof','Audience-First Value','Authentic Founder Perspective']);
      const count=Math.max(1,Math.min(6,versions));
      const versionType=dlg.querySelector('input[name="bvVersionType"]:checked')?.value||'storylines';
      const stamp=new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date());
      const generatedKey=String(parent[12]||parent[0]);
      const existing=generatedVersionNodesByCommunication.get(generatedKey)||[];
      const nextNumber=existing.reduce((sum,group)=>sum+(group.versions||[]).length,0)+1;
      const platformPool=selectedPlatforms.length?selectedPlatforms:['LinkedIn'];
      let generatedGroups=[];

      if(versionType==='variations'){
        const platform=platformPool[0];
        const communicationName=`${baseName} - ${platform}`;
        const versionsList=Array.from({length:count},(_,i)=>({
          type:'version',
          name:`${communicationName} - Version ${nextNumber+i}`,
          status:'Draft',platform,promoted:false,
          body:`${communicationName} - Version ${nextNumber+i}

This generated variation preserves the same storyline while testing a different ${i%3===0?'opening hook':i%3===1?'benefit emphasis':'call to action'}. It was created from ${parent[0]} using ${mode==='advanced'?'the selected advanced settings':'ULUsignals AI recommendations'}.`
        }));
        generatedGroups=[{type:'communication',name:communicationName,status:'Draft',platform,promoted:false,body:`A generated communication based on ${parent[0]}. The versions below keep the same storyline and vary the execution.`,versions:versionsList,generated:true,updated:stamp}];
      }else{
        generatedGroups=Array.from({length:count},(_,i)=>{
          const platform=platformPool[i%platformPool.length];
          const seed=seeds[i%seeds.length]||`Storyline ${i+1}`;
          const communicationName=i===0?baseName:`${baseName}: ${seed}`;
          return {type:'communication',name:communicationName,status:'Draft',platform,promoted:false,body:`A distinct generated storyline based on ${parent[0]}, framed around ${seed}.`,versions:[{type:'version',name:`${communicationName} - Version 1`,status:'Draft',platform,promoted:false,body:`${communicationName} - Version 1

This version uses a distinct storyline around ${seed} while preserving the cluster communication theme. It was created using ${mode==='advanced'?'the selected advanced settings':'ULUsignals AI recommendations'}.`}],generated:true,updated:stamp};
        });
      }

      generatedVersionNodesByCommunication.set(generatedKey,generatedGroups.concat(existing));
      parent[3]=Number(parent[3]||0)+generatedGroups.reduce((sum,group)=>sum+(group.versions||[]).length,0);
      return idx;
    }
    function strategyHierarchyRows(list){
      const communicationNames=[
        ['TikTok Post','YouTube Video','LinkedIn Founder Post'],
        ['Build-in-Public Update','Behind-the-Scenes Reel'],
        ['Comeback Video','What Changed Email'],
        ['Three Lessons Post','Founder Lessons Email'],
        ['Launch Reveal Video']
      ];
      let html='';
      const parentPlatform='LinkedIn';
      const parentPlatformHTML=`<span class="bv-platform-cell"><img src="${strategyPlatformIcon(parentPlatform)}" alt="${parentPlatform}">${parentPlatform}</span>`;
      list.forEach((a,si)=>{
        const sid=`strategy-${si}`;
        const strategyOpen=si===0;
        const strategyType=a.emotion==='Education'?'Educate':a.emotion==='Transparency'?'Build Trust':a.emotion;
        const strategyPerf=si===0?'+18%':si===1?'+14%':si===2?'+12%':'-';
        html+=`<tr class="bv-hierarchy-row" data-level="strategy" data-strategy-id="${sid}" data-search="${a.name} ${a.emotion} ${a.status}" data-platform="All" data-status="${a.recommended?'Recommended':a.status}"><td><div class="bv-hierarchy-name"><button class="bv-tree-toggle" type="button" data-bv-tree="strategy" data-target="${sid}" aria-expanded="${strategyOpen?'true':'false'}">›</button><span class="bv-level-icon strategy">★</span><span class="bv-hierarchy-text"><span class="bv-hierarchy-kind">Strategy Angle</span><span class="bv-hierarchy-item-name">${a.name}</span></span></div></td><td>${strategyType}</td><td>${parentPlatformHTML}</td><td><span class="bv-h-status ${a.recommended?'recommended':strategyStatusClass(a.status)}">${a.recommended?'Recommended':a.status}</span></td><td>Jul ${12-si}, ${si===0?'9:41 AM':si===1?'4:22 PM':'2:10 PM'}</td><td class="${strategyPerf==='-'?'bv-h-muted':'bv-h-perf'}">${strategyPerformanceHTML(strategyPerf)}</td><td class="bv-h-actions"><button class="bv-kebab" type="button">•••</button></td></tr>`;
        a.variations.slice(0,si===0?2:1).forEach((v,ci)=>{
          const cid=`${sid}-communication-${ci}`;
          const cOpen=si===0;
          const cName=(communicationNames[si]&&communicationNames[si][ci])||v[0];
          const platformFromName=(name,fallback)=>{
            const text=String(name||'').toLowerCase();
            if(text.includes('tiktok')) return 'TikTok';
            if(text.includes('youtube')) return 'YouTube';
            if(text.includes('linkedin')) return 'LinkedIn';
            if(text.includes('instagram')||text.includes('reel')) return 'Instagram';
            if(text.includes('facebook')) return 'Facebook';
            if(text.includes('email')) return 'Email';
            if(text.includes('website')||text.includes('web ')) return 'Website';
            return fallback;
          };
          const storedPlatform=String(v[2]).split('/')[0].trim();
          const platform=platformFromName(cName,storedPlatform);
          const status=v[3];
          const communicationPlatformHTML=`<span class="bv-platform-cell"><img src="${strategyPlatformIcon(platform)}" alt="${platform}">${platform}</span>`;
          html+=`<tr class="bv-hierarchy-row" data-level="communication" data-parent="${sid}" data-communication-id="${cid}" data-search="${cName} ${platform} ${status}" data-platform="${platform}" data-status="${status}" ${strategyOpen?'':'hidden'}><td><div class="bv-hierarchy-name bv-hierarchy-indent-1"><button class="bv-tree-toggle" type="button" data-bv-tree="communication" data-target="${cid}" aria-expanded="${cOpen?'true':'false'}">›</button><span class="bv-level-icon communication">↗</span><span class="bv-hierarchy-text"><span class="bv-hierarchy-kind">Communication</span><span class="bv-hierarchy-item-name">${cName}</span></span></div></td><td>${v[1]}</td><td>${communicationPlatformHTML}</td><td><span class="bv-h-status ${strategyStatusClass(status)}">${status}</span></td><td>Jul 12, ${ci===0?'9:41 AM':'8:15 AM'}</td><td class="${v[4]==='-'?'bv-h-muted':'bv-h-perf'}">${strategyPerformanceHTML(v[4])}</td><td class="bv-h-actions"><button class="bv-kebab" type="button">•••</button></td></tr>`;
          const versionCount=si===0&&ci===0?2:1;
          for(let vi=0;vi<versionCount;vi++){
            const versionStatus=bvVersionStatusLabel(vi===0?status:'Draft');
            const versionPerf=vi===0?v[4]:'-';
            html+=`<tr class="bv-hierarchy-row" data-level="version" data-parent="${cid}" data-search="Version ${ci+1}-${vi+1} ${platform} ${versionStatus}" data-platform="${platform}" data-status="${versionStatus}" ${(strategyOpen&&cOpen)?'':'hidden'}><td><div class="bv-hierarchy-name bv-hierarchy-indent-2"><span class="bv-tree-spacer"></span><span class="bv-level-icon version">◇</span><span class="bv-hierarchy-text"><span class="bv-hierarchy-kind">Variation</span><span class="bv-hierarchy-item-name">${ci+1}-${vi+1}</span></span></div></td><td class="bv-h-muted">-</td><td>${communicationPlatformHTML}</td><td><span class="bv-h-status ${strategyStatusClass(versionStatus)}">${versionStatus}</span></td><td>Jul 12, ${vi===0?'9:41 AM':'8:15 AM'}</td><td class="${versionPerf==='-'?'bv-h-muted':'bv-h-perf'}">${strategyPerformanceHTML(versionPerf)}</td><td class="bv-h-actions"><div class="bv-version-row-actions"><span class="bv-version-match ${vi===0?'matched':'unmatched'}">${vi===0?'Matched':'Unmatched'}</span><button class="bv-version-add-row" type="button" data-bv-create-version data-communication="${ci}">+ Version</button>${vi===0?`<a class="bv-version-post-url" href="https://www.instagram.com/p/resistance-chair-version-${ci+1}-${vi+1}/" target="_blank" rel="noopener noreferrer">instagram.com/p/resistance-chair-version-${ci+1}-${vi+1}/</a>`:''}</div></td></tr>`;
          }
        });
      });
      return html;
    }
    function strategiesView(r,idx){
      const list=strategiesForCommunication(idx,r);
      return `<div class="bv-strategy-table-panel" data-bv-strategy-panel><div class="bv-strategy-toolbar"><div class="bv-strategy-search-wrap"><input class="bv-strategy-search" type="search" placeholder="Search..." aria-label="Search strategies, communications, and versions" data-bv-strategy-search></div><select class="bv-strategy-filter" data-bv-filter="strategy"><option value="All">All Strategies</option>${list.map(a=>`<option value="${a.name}">${a.name}</option>`).join('')}</select><select class="bv-strategy-filter" data-bv-filter="platform"><option value="All">All Platforms</option><option>TikTok</option><option>YouTube</option><option>LinkedIn</option><option>Instagram</option><option>Email</option></select><select class="bv-strategy-filter" data-bv-filter="status"><option value="All">All Statuses</option><option>Recommended</option><option>Active</option><option>Published</option><option>Ready to Deploy</option><option>Draft</option><option>Testing</option></select><button class="bv-btn primary bv-strategy-create" data-bv-angle>+ Create Strategy</button></div><div class="bv-strategy-bulk-actions" aria-label="Hierarchy controls"><button class="bv-strategy-bulk-btn" type="button" data-bv-expand-all>Expand All</button><button class="bv-strategy-bulk-btn" type="button" data-bv-collapse-all>Collapse All</button></div><div class="bv-hierarchy-scroll"><table class="bv-hierarchy-table"><thead><tr><th>Name</th><th>Type</th><th>Platform</th><th>Status</th><th>Updated</th><th>Performance</th><th>Actions</th></tr></thead><tbody>${strategyHierarchyRows(list)}</tbody></table><div class="bv-strategy-empty" data-bv-strategy-empty>No matching strategies, communications, or versions.</div></div><div class="bv-strategy-legend"><div class="bv-legend-items"><span class="bv-legend-item"><span class="bv-level-icon strategy">★</span>Strategy Angle</span><span class="bv-legend-item"><span class="bv-level-icon communication">↗</span>Communication</span><span class="bv-legend-item"><span class="bv-level-icon version">◇</span>Variation</span></div><span>ⓘ Click any row to view or edit</span></div></div>`;
    }
    function intelligenceView(){
      return `<section class="bv-learning-hero"><div class="bv-section-kicker">What the audience taught us</div><h4>Personal founder storytelling is producing the strongest trust response.</h4><p class="bv-copy">The Founder Journey angle is outperforming direct product framing because audiences are responding to authentic lessons, visible sacrifice, and a clear reason for the period of silence.</p><div class="bv-learning-grid"><article class="bv-insight-card"><strong>+31%</strong><p>Higher completion for personal lessons.</p></article><article class="bv-insight-card"><strong>+24%</strong><p>More saves for founder-led long-form posts.</p></article><article class="bv-insight-card"><strong>+18%</strong><p>More profile visits after vulnerable stories.</p></article></div><div class="bv-recommendation"><b>Recommendation:</b> Create two additional Founder Journey variations using stronger opening hooks and a direct invitation to follow the launch. Keep product proof after the human story rather than leading with it.</div></section><div class="bv-detail-grid" style="margin-top:10px"><section class="bv-subcard"><div class="bv-section-kicker">Audience behavior supporting the recommendation</div><div class="bv-summary-row"><span class="bv-summary-name">Founder-led communication</span><b>2.3x more saves</b></div><div class="bv-summary-row"><span class="bv-summary-name">Personal lessons</span><b>41% higher completion</b></div><div class="bv-summary-row"><span class="bv-summary-name">Direct promotional messaging</span><b>18% lower engagement</b></div></section><aside class="bv-subcard"><div class="bv-section-kicker">Learning record</div><h4>Applied to Brand Voice</h4><p class="bv-copy">These findings are stored with the cluster communication and contribute to the broader Brand Voice intelligence profile.</p><button class="bv-btn primary">Apply Learning to Future Content</button></aside></div>`;
    }
    function performanceView(r){
      const scores=[
        {kind:'Parent Communication',name:r[0],score:82,level:'parent'},
        {kind:'Strategy Angle 01',name:'The Founder Journey',score:91,level:'angle'},
        {kind:'Variation',name:'LinkedIn Founder Post',score:94,level:'variation'},
        {kind:'Variation',name:'Founder Story Video',score:88,level:'variation'},
        {kind:'Strategy Angle 02',name:'Building in Public',score:84,level:'angle'},
        {kind:'Strategy Angle 03',name:'The Cost of Disappearing',score:76,level:'angle'}
      ];
      return `<div class="bv-performance-grid"><article class="bv-perf-card"><strong>82</strong><p>Overall Communication Score</p></article><article class="bv-perf-card"><strong>91</strong><p>Leading Angle Score</p></article><article class="bv-perf-card"><strong>94</strong><p>Best Variation Score</p></article></div><div class="bv-detail-grid" style="margin-top:10px"><section class="bv-subcard"><div class="bv-section-kicker">Performance hierarchy</div><h4>Parent → Strategy Angle → Variation</h4><div class="bv-score-header" aria-hidden="true"><span>Communication hierarchy</span><span>Score</span><span>Overall Communication Score (0–100)</span></div>${scores.map(x=>`<div class="bv-score-row"><div class="bv-score-label level-${x.level}"><small class="bv-score-kind">${x.kind}</small><div class="bv-score-name">${x.name}</div></div><b style="color:#fff;text-align:right">${x.score}</b><div class="bv-score-track"><div class="bv-score-fill" style="width:${x.score}%"></div></div></div>`).join('')}</section><aside class="bv-subcard"><div class="bv-section-kicker">System interpretation</div><h4>Best-performing path</h4><p class="bv-copy"><b style="color:#fff">The Founder Journey</b> is the strongest strategic framing, and the <b style="color:#fff">LinkedIn Founder Post</b> is its strongest execution.</p><div class="bv-recommendation">Allocate the next test to two new Founder Journey variations. Preserve the long-form lesson structure while testing a stronger first-line hook.</div><button class="bv-btn ghost" data-bv-go-strategies style="margin-top:10px">Open Strategies</button></aside></div>`;
    }
    function view(tab,r,idx){
      if(tab==='Strategies')return strategiesView(r,idx);
      if(tab==='Intelligence')return intelligenceView(r);
      if(tab==='Performance')return performanceView(r);
      return overviewView(r,idx);
    }
    const BV_NOTES_STORAGE_KEY='uluCommunicationNotesV1';
    const bvDefaultNotes={
      0:[
        {author:'Johnson Industries',stamp:'Jul 12, 2026, 8:18 PM',text:'Use the founder-led framing as the control message for the next round of strategy testing.'},
        {author:'Alex Morgan',stamp:'Jul 11, 2026, 3:42 PM',text:'LinkedIn is currently producing the strongest response. Preserve the longer lesson-oriented structure in new versions.'}
      ]
    };
    function loadCommunicationNotes(){
      try{
        const saved=JSON.parse(localStorage.getItem(BV_NOTES_STORAGE_KEY)||'{}');
        return saved&&typeof saved==='object'?saved:{};
      }catch(e){return {}}
    }
    function saveCommunicationNotes(notes){
      try{localStorage.setItem(BV_NOTES_STORAGE_KEY,JSON.stringify(notes))}catch(e){}
    }
    function notesForCommunication(idx){
      const saved=loadCommunicationNotes();
      const key=String(idx);
      if(!Array.isArray(saved[key])) saved[key]=(bvDefaultNotes[idx]||[]).map(note=>({...note}));
      saveCommunicationNotes(saved);
      return saved[key];
    }
    function renderCommunicationNotes(idx){
      const dlg=document.getElementById('bvNotesModal');
      if(!dlg)return;
      const r=comms[idx]||comms[0];
      dlg.dataset.index=String(idx);
      const title=dlg.querySelector('[data-bv-notes-parent]');
      if(title)title.textContent=r[0];
      const list=dlg.querySelector('[data-bv-notes-list]');
      const notes=notesForCommunication(idx);
      if(list){
        list.innerHTML=notes.length?notes.map(note=>`<article class="bv-note-item"><div class="bv-note-meta"><span class="bv-note-author">${escapeHtml(note.author)}</span><time>${escapeHtml(note.stamp)}</time></div><div class="bv-note-text">${escapeHtml(note.text)}</div></article>`).join(''):'<div class="bv-notes-empty">No notes have been added for this cluster communication.</div>';
        requestAnimationFrame(()=>{list.scrollTop=list.scrollHeight});
      }
      const textarea=dlg.querySelector('[data-bv-note-input]');
      if(textarea)textarea.value='';
    }
    function ensureNotesModal(){
      let dlg=document.getElementById('bvNotesModal');
      if(dlg)return dlg;
      dlg=document.createElement('dialog');
      dlg.id='bvNotesModal';
      dlg.className='bv-notes-modal';
      dlg.innerHTML=`<div class="bv-notes-card"><div class="bv-notes-head"><div><div class="bv-eyebrow">Cluster Communication Notes</div><div class="bv-notes-subtitle" data-bv-notes-parent></div></div><button class="bv-notes-close" type="button" data-bv-notes-close aria-label="Close">×</button></div><div class="bv-notes-list" data-bv-notes-list></div><div class="bv-notes-compose"><label for="bvNoteInput">Add a note</label><textarea id="bvNoteInput" class="bv-notes-textarea" data-bv-note-input placeholder="Write a note related to this cluster communication..."></textarea><div class="bv-notes-compose-actions"><span class="bv-notes-user">Posting as Johnson Industries</span><button class="bv-btn primary" type="button" data-bv-add-note>Add Note</button></div></div></div>`;
      document.body.appendChild(dlg);
      dlg.addEventListener('click',e=>{
        if(e.target.closest('[data-bv-notes-close]')){dlg.close();return}
        if(e.target.closest('[data-bv-add-note]')){
          const input=dlg.querySelector('[data-bv-note-input]');
          const text=(input?.value||'').trim();
          if(!text){input?.focus();return}
          const idx=+(dlg.dataset.index||0);
          const saved=loadCommunicationNotes();
          const key=String(idx);
          if(!Array.isArray(saved[key]))saved[key]=notesForCommunication(idx);
          saved[key].push({author:'Johnson Industries',stamp:new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date()),text});
          saveCommunicationNotes(saved);
          renderCommunicationNotes(idx);
        }
      });
      dlg.addEventListener('cancel',e=>{e.preventDefault();dlg.close()});
      return dlg;
    }
    function openCommunicationNotes(idx){
      const dlg=ensureNotesModal();
      renderCommunicationNotes(idx);
      if(typeof dlg.showModal==='function')dlg.showModal();else dlg.setAttribute('open','');
    }
    function ensureDialogs(){
      if(document.getElementById('bvCreateModal'))return;
      const d=document.createElement('dialog');
      d.id='bvCreateModal';
      d.className='bv-modal bv-create-import-modal';
      d.innerHTML=`<div class="bv-modal-card bv-create-import-card">
        <div class="bv-modal-head bv-create-import-head ulu-mobile-create-cluster-head">
          <div class="ulu-mobile-create-cluster-title-wrap"><h3>Create Cluster Communication</h3><p class="ulu-mobile-create-cluster-subtitle">Create a new cluster communication to start capturing audience intelligence.</p></div>
          <div class="bv-cluster-head-actions">
            <button class="bv-cluster-info-btn info-icon panel-info-btn" type="button" data-tooltip-title="What is a Cluster?" data-tooltip-body="A Cluster is the master project that defines the original message, objective, audience, and business goal behind a communication effort. It serves as the permanent strategic source record for all Strategy Angles, platform-specific Communications, and Variations created beneath it. The Cluster Communication preserves the original intent so every later message and performance result can be traced back to what the Creator or organization was trying to communicate and accomplish." aria-label="What is a Cluster?">i</button>
            <button class="bv-modal-close" data-bv-close aria-label="Close">×</button>
          </div>
        </div>
        <div class="bv-parent-name-wrap">
          <label class="bv-parent-name-label" for="bvParentCommunicationName">
            <span>Cluster Name<em>*</em></span>
            <input id="bvParentCommunicationName" class="bv-parent-name-input" type="text" name="parentCommunicationName" placeholder="Enter a name for this Cluster Communication" autocomplete="off" data-bv-parent-name required>
            <small class="bv-parent-name-help ulu-mobile-create-cluster-name-help">Identifies the Cluster throughout Brand Voice.</small>
          </label>
        </div>
        <div class="bv-parent-create-options ulu-mobile-create-cluster-metrics">
          <label class="bv-parent-create-option"><span class="bv-parent-option-label"><span class="bv-parent-option-title">Number of Versions to Create</span><small>10 versions max.</small></span><input type="number" min="1" max="10" step="1" value="1" inputmode="numeric" data-bv-version-count data-bv-ci-required></label>
          <label class="bv-parent-create-option"><span class="bv-parent-option-label"><span class="bv-parent-option-title">Length in Seconds</span><small>3600 seconds max.</small></span><input type="number" min="1" max="3600" step="1" value="60" inputmode="numeric" data-bv-length-seconds data-bv-ci-required></label>
        </div>
        <div class="bv-modal-body bv-create-import-body" data-bv-modal-body></div>
        <div class="bv-modal-footer bv-create-import-footer"><button class="bv-btn ghost" data-bv-prev>Cancel</button><button class="bv-btn primary" data-bv-next>Create Communication</button></div>
      </div>`;
      document.body.appendChild(d);
      const enforceCreateClusterMaximum=(input,max)=>{
        input.dataset.lastValid=String(input.value||'');
        input.addEventListener('focus',()=>{if(input.checkValidity()&&Number(input.value)<=max)input.dataset.lastValid=String(input.value)});
        input.addEventListener('input',()=>{
          const raw=String(input.value||'');
          if(raw==='')return;
          const n=Number(raw);
          if(!Number.isFinite(n)||n>max){input.value=input.dataset.lastValid||String(max);input.setCustomValidity(`Maximum allowed value is ${max}.`);input.reportValidity();setTimeout(()=>input.setCustomValidity(''),900);return}
          if(n>=1){input.dataset.lastValid=raw;input.setCustomValidity('')}
        });
      };
      const versionLimitInput=d.querySelector('[data-bv-version-count]');if(versionLimitInput)enforceCreateClusterMaximum(versionLimitInput,10);
      const secondsLimitInput=d.querySelector('[data-bv-length-seconds]');if(secondsLimitInput)enforceCreateClusterMaximum(secondsLimitInput,3600);
      d.addEventListener('click',e=>{
        if(e.target.closest('[data-bv-close]')){d.close();return}
        const platform=e.target.closest('[data-bv-ci-platform]');
        if(platform){platform.classList.toggle('active');platform.setAttribute('aria-pressed',platform.classList.contains('active')?'true':'false');return}
        if(e.target.closest('[data-bv-next]'))wizardNext();
        if(e.target.closest('[data-bv-prev]'))wizardPrev();
      });
      const a=document.createElement('dialog');
      a.id='bvAngleModal';
      a.className='bv-modal bv-strategy-angle-modal';
      a.dataset.mode='guided';
      a.innerHTML=bvStrategyModalHTML((comms[currentDetailIndex]||comms[0])[0]);
      document.body.appendChild(a);
      a.addEventListener('click',e=>{
        if(e.target.closest('[data-bv-strategy-close]')){a.close();return}
        const mode=e.target.closest('[data-bv-angle-mode]');
        if(mode){const value=mode.dataset.bvAngleMode;a.dataset.mode=value;a.querySelectorAll('[data-bv-angle-mode]').forEach(x=>x.classList.toggle('active',x===mode));a.querySelectorAll('[data-bv-angle-panel]').forEach(x=>x.hidden=x.dataset.bvAnglePanel!==value);return}
        const recommended=e.target.closest('.bv-angle-guided-list label');
        if(recommended){a.querySelectorAll('.bv-angle-guided-list label').forEach(x=>x.classList.toggle('selected',x===recommended));const radio=recommended.querySelector('input');if(radio)radio.checked=true;return}
        const option=e.target.closest('.bv-angle-option-card');
        if(option){a.querySelectorAll('.bv-angle-option-card').forEach(x=>x.classList.toggle('selected',x===option));const radio=option.querySelector('input[type="radio"]');if(radio)radio.checked=true;return}
        if(e.target.closest('[data-bv-angle-back]')){const parent=comms[+(a.dataset.index||currentDetailIndex)]||comms[0];a.innerHTML=bvStrategyModalHTML(parent[0]);return}
        const generate=e.target.closest('[data-bv-angle-generate-options]');
        if(generate){e.preventDefault();generate.disabled=true;generate.textContent='Generating Angle Options...';setTimeout(()=>{const parent=comms[+(a.dataset.index||currentDetailIndex)]||comms[0];a.__angleOptions=buildStrategyAngleOptions(a);a.innerHTML=bvReviewAngleOptionsHTML(parent[0],a.__angleOptions);},450);return}
        if(e.target.closest('[data-bv-angle-create]')){e.preventDefault();const selection=createSelectedStrategyAngle(a);if(!selection)return;a.close();currentDetailSelection=selection;detail(+(a.dataset.index||currentDetailIndex),'angles',selection);return}
      });
      a.addEventListener('input',e=>{if(e.target.matches('[data-bv-angle-constraints]')){const count=a.querySelector('[data-bv-angle-constraint-count]');if(count)count.textContent=String(e.target.value.length);}});
      a.addEventListener('cancel',e=>{e.preventDefault();a.close()});
    }
    function ciField(label,control,help,required){return `<label class="bv-ci-field"><span>${label}${required?'<em>*</em>':''}</span>${control}${help?`<small>${help}</small>`:''}</label>`}
    function createParentVersionBody(index,{coreMessage,audience,objective,product,theme,directions}){
      const audienceName=audience||'the intended audience';
      const productName=product||'this offer';
      const objectiveName=objective?objective.toLowerCase():'move forward';
      const themeName=theme||'the central idea';
      const directionCopy=directions||`Keep the message focused on helping the audience ${objectiveName}.`;
      const variants=[
        coreMessage,
        `For ${audienceName}, the most important point is this:\n\n${coreMessage}\n\n${directionCopy}`,
        `When it comes to ${productName}, the next step should feel clear and achievable.\n\n${coreMessage}\n\nUse this message to help the audience ${objectiveName}.`,
        `${themeName}: a message built around the audience's real needs.\n\n${coreMessage}\n\nThe focus is relevance, clarity, and a practical reason to act.`,
        `Here is the shorter, more direct version:\n\n${coreMessage}\n\nMake the benefit clear. Keep the message human. End with one specific next step.`
      ];
      const body=variants[index%variants.length];
      return index<variants.length?body:`${body}\n\nAlternative variation ${index+1}: adjust the opening and closing language while preserving the cluster communication's central meaning.`;
    }
    function createCommunicationPanel(){
      return `<section class="bv-ci-section"><div class="bv-ci-section-title"><b>1. Communication Basics</b><small>Define the foundation for your communication.</small></div><div class="bv-ci-grid">
        ${ciField('Communication Type','<select data-bv-ci-required data-bv-ci-type><option value="">Select type...</option><option>Brochure / Sales Literature</option><option>Campaign Communication</option><option>Elevator Pitch</option><option>Email</option><option>FAQ documentation</option><option>Document</option><option>Infographics</option><option>Interviews</option><option>Long-Form Infomercial</option><option>Manual</option><option>Micro-drama</option><option>Newsletter</option><option>Podcast</option><option>Press Release</option><option>Radio Commercial</option><option>Seminars</option><option>Short-Form Video</option><option>Social Media Post</option><option>Speech</option><option>Storyboard</option><option>Telephone Script</option><option>Television Commercial</option><option>Text Message</option><option>Toasts</option><option>Tradeshow Banner</option><option>Voice Message Script</option><option>Website Content</option><option>White Paper</option></select>','Choose the primary type of communication.',true)}
        ${ciField('Product / Keyword','<input data-bv-ci-required data-bv-ci-product placeholder="Enter product, service or keyword">','What is this communication about?',true)}
        ${ciField('Theme / Campaign','<input data-bv-ci-theme placeholder="Enter theme or campaign name (optional)">','Name your theme, campaign or initiative.',false)}
        ${ciField('Target Audience','<input data-bv-ci-required data-bv-ci-audience placeholder="Describe your target audience">','Who is this communication intended for?',true)}
      </div></section>
      <section class="bv-ci-section"><div class="bv-ci-section-title"><b>2. Messaging Direction</b><small>Guide AL and your team with key messaging insights.</small></div><div class="bv-ci-grid">
        ${ciField('Primary Objective','<select data-bv-ci-required data-bv-ci-objective><option value="">Select primary objective...</option><option>Build Trust</option><option>Educate</option><option>Drive Engagement</option><option>Generate Leads</option><option>Drive Conversion</option><option>Retain Customers</option></select>','What do you want this communication to achieve?',true)}
        ${ciField('Core Message / Key Takeaway','<textarea data-bv-ci-required data-bv-ci-core-message rows="3" placeholder="What is the most important thing you want your audience to understand or do?"></textarea>','The central message you want to communicate.',true)}
        <label class="bv-ci-field bv-ci-span-2"><span>Messaging Directions</span><textarea data-bv-ci-directions rows="3" placeholder="Enter key messages, talking points or directions for this communication. You can include tone, benefits, differentiators, proof points, etc."></textarea><small>Provide context, direction and key points to guide content creation.</small></label>
      </div></section>
      <section class="bv-ci-section"><div class="bv-ci-section-title"><b>3. Intended Platforms</b><small>Select where this communication is intended to live.</small></div><div class="bv-ci-platforms">
        ${[
          ['TikTok','logos/tiktok-logo.png'],
          ['Instagram','logos/instagram-logo.png'],
          ['YouTube','logos/YouTube-logo.png'],
          ['Document','logos/document-icon.png'],
          ['Email','logos/email-icon.png'],
          ['Google Ads','logos/google-ads-logo.png'],
          ['Website','logos/website-logo.png']
        ].map((x,i)=>`<button type="button" class="bv-ci-platform${i<3?' active':''}" data-bv-ci-platform aria-pressed="${i<3?'true':'false'}"><span class="bv-ci-platform-logo"><img src="${x[1]}" alt="${x[0]}"></span>${x[0]}</button>`).join('')}
      </div></section>
      <section class="bv-ci-section bv-ci-notes">${ciField('Additional Notes (Optional)','<textarea data-bv-ci-notes rows="2" placeholder="Any additional context, notes or references for this communication..."></textarea>','',false)}</section>
      <div class="bv-ci-callout"><span>💡</span><p>This will create a new <b>Cluster Communication</b>. You’ll be able to generate strategies, angles and versions next.</p></div>`;
    }
    function showWizard(){
      const d=document.getElementById('bvCreateModal');
      if(!d)return;
      const parentName=d.querySelector('[data-bv-parent-name]');
      if(parentName)parentName.value='';
      const versionCount=d.querySelector('[data-bv-version-count]');
      if(versionCount)versionCount.value='1';
      const lengthSeconds=d.querySelector('[data-bv-length-seconds]');
      if(lengthSeconds)lengthSeconds.value='60';
      d.querySelector('[data-bv-modal-body]').innerHTML=createCommunicationPanel();
      d.querySelector('[data-bv-prev]').textContent='Cancel';
      const next=d.querySelector('[data-bv-next]');
      next.textContent='Create Communication';
      next.classList.remove('green-action');
    }
    function wizardNext(){
      const d=document.getElementById('bvCreateModal');
      const required=[...d.querySelectorAll('[data-bv-parent-name],[data-bv-ci-required]')];
      const missing=required.find(el=>!String(el.value||'').trim()||(el.type==='number'&&!el.checkValidity()));
      if(missing){missing.focus();missing.classList.add('is-invalid');setTimeout(()=>missing.classList.remove('is-invalid'),1200);return}
      const next=d.querySelector('[data-bv-next]');
      const original=next.textContent;
      next.disabled=true;next.textContent='Creating...';
      const value=(selector)=>String(d.querySelector(selector)?.value||'').trim();
      const name=value('[data-bv-parent-name]');
      const versionCount=Math.max(1,Math.min(10,Math.trunc(Number(value('[data-bv-version-count]'))||1)));
      const lengthSeconds=Math.max(1,Math.min(3600,Math.trunc(Number(value('[data-bv-length-seconds]'))||60)));
      const communicationType=value('[data-bv-ci-type]');
      const product=value('[data-bv-ci-product]');
      const theme=value('[data-bv-ci-theme]');
      const audience=value('[data-bv-ci-audience]');
      const objective=value('[data-bv-ci-objective]');
      const coreMessage=value('[data-bv-ci-core-message]');
      const directions=value('[data-bv-ci-directions]');
      const notes=value('[data-bv-ci-notes]');
      const platforms=[...d.querySelectorAll('[data-bv-ci-platform].active')].map(button=>String(button.textContent||'').trim()).filter(Boolean);
      const nextNumber=comms.reduce((highest,row)=>{
        const match=String(row[12]||'').match(/^COM-(\d+)$/);
        return match?Math.max(highest,Number(match[1])):highest;
      },1000)+1;
      const id=`COM-${nextNumber}`;
      const purpose=objective||communicationType;
      const initialAngle={name:'Original Communication',emotion:'Foundation',audience:audience||'Target Audience',channels:platforms.join(', ')||'Multi-platform',confidence:0,status:'Draft',recommended:false,premise:coreMessage,message:coreMessage,rationale:[],variations:[]};
      const initialVersions=Array.from({length:versionCount},(_,index)=>({
        type:'version',
        name:`${name} - Version ${index+1}`,
        status:'Draft',
        platform:platforms[0]||'Multi-platform',
        promoted:false,
        durationSeconds:lengthSeconds,
        variantNumber:index+1,
        body:createParentVersionBody(index,{coreMessage,audience,objective,product,theme,directions})
      }));
      const initialCommunication={type:'communication',name,status:'Draft',platform:platforms[0]||'Multi-platform',promoted:false,durationSeconds:lengthSeconds,body:coreMessage,versions:initialVersions,generated:true,strategyAngleIndex:0,strategyAngleName:initialAngle.name,createdAt:new Date().toISOString()};
      const newCommunication=[name,purpose,1,versionCount,0,'Not available',0,0,'Draft','Just now','✎','blue',id];
      newCommunication.formData={communicationType,product,theme,audience,objective,coreMessage,directions,platforms,notes,versionCount,lengthSeconds,createdFromForm:true};
      newCommunication.createdStrategyAngles=[initialAngle];
      setTimeout(()=>{
        comms.unshift(newCommunication);
        generatedVersionNodesByCommunication.set(id,[initialCommunication]);
        workflowStatusByCommunication.set(id,'Draft');
        next.disabled=false;
        next.textContent=original;
        d.close();
        dashboard(1);
      },650);
    }
    function wizardPrev(){const d=document.getElementById('bvCreateModal');if(d)d.close()}
    function refreshStrategyHierarchy(){
      const panel=host.querySelector('[data-bv-strategy-panel]');
      if(!panel)return;
      const q=(panel.querySelector('[data-bv-strategy-search]')?.value||'').trim().toLowerCase();
      const strategyFilter=panel.querySelector('[data-bv-filter="strategy"]')?.value||'All';
      const platformFilter=panel.querySelector('[data-bv-filter="platform"]')?.value||'All';
      const statusFilter=panel.querySelector('[data-bv-filter="status"]')?.value||'All';
      const rows=[...panel.querySelectorAll('.bv-hierarchy-row')];
      let shown=0;
      rows.forEach(row=>{
        const text=(row.dataset.search||row.textContent||'').toLowerCase();
        const platform=row.dataset.platform||'All';
        const status=row.dataset.status||'';
        let strategyName='';
        if(row.dataset.level==='strategy') strategyName=(row.querySelector('td')?.textContent||'').replace(/^.*Strategy\s*-\s*/,'').trim();
        else{
          const parentStrategy=row.dataset.level==='communication'?row.dataset.parent:(panel.querySelector(`[data-communication-id="${row.dataset.parent}"]`)?.dataset.parent||'');
          strategyName=(panel.querySelector(`[data-strategy-id="${parentStrategy}"] td`)?.textContent||'').replace(/^.*Strategy\s*-\s*/,'').trim();
        }
        const matchText=!q||text.includes(q);
        const matchStrategy=strategyFilter==='All'||strategyName===strategyFilter;
        const matchPlatform=platformFilter==='All'||platform===platformFilter;
        const matchStatus=statusFilter==='All'||status===statusFilter;
        const hierarchyVisible=!row.hasAttribute('data-collapsed-hidden');
        const visible=matchText&&matchStrategy&&matchPlatform&&matchStatus&&hierarchyVisible;
        row.hidden=!visible;
        if(visible)shown++;
      });
      const empty=panel.querySelector('[data-bv-strategy-empty]');
      if(empty)empty.style.display=shown?'none':'block';
    }
    function setHierarchyChildren(target,open,level){
      const panel=host.querySelector('[data-bv-strategy-panel]');
      if(!panel)return;
      const direct=[...panel.querySelectorAll(`[data-parent="${target}"]`)];
      direct.forEach(row=>{
        if(open) row.removeAttribute('data-collapsed-hidden'); else row.setAttribute('data-collapsed-hidden','1');
        if(!open&&level==='strategy'&&row.dataset.level==='communication'){
          panel.querySelectorAll(`[data-parent="${row.dataset.communicationId}"]`).forEach(v=>v.setAttribute('data-collapsed-hidden','1'));
        }
      });
      refreshStrategyHierarchy();
    }
    function setAllStrategyHierarchy(open){
      const panel=host.querySelector('[data-bv-strategy-panel]');
      if(!panel)return;
      panel.querySelectorAll('[data-bv-tree]').forEach(toggle=>toggle.setAttribute('aria-expanded',open?'true':'false'));
      panel.querySelectorAll('.bv-hierarchy-row').forEach(row=>{
        if(row.dataset.level==='strategy')return;
        if(open)row.removeAttribute('data-collapsed-hidden');
        else row.setAttribute('data-collapsed-hidden','1');
      });
      refreshStrategyHierarchy();
    }
    document.addEventListener('click',e=>{
      if(!rowActionMenu)return;
      const submenuToggle=e.target.closest('[data-bv-submenu-toggle]');
      if(submenuToggle&&rowActionMenu.contains(submenuToggle)){
        e.preventDefault();e.stopPropagation();const item=submenuToggle.closest('[data-bv-submenu]');const open=item.classList.toggle('is-open');submenuToggle.setAttribute('aria-expanded',open?'true':'false');return;
      }
      const actionBtn=e.target.closest('[data-bv-row-action]');
      if(actionBtn&&rowActionMenu.contains(actionBtn)){e.preventDefault();e.stopPropagation();handleRowAction(actionBtn.dataset.bvRowAction,+(rowActionMenu.dataset.index||0),actionBtn);return}
      if(!rowActionMenu.contains(e.target)&&!e.target.closest('[data-bv-row-menu]'))closeRowActionMenu();
    });
    window.addEventListener('resize',closeRowActionMenu,{passive:true});
    window.addEventListener('scroll',()=>{
      /* Desktop keeps the original close-on-scroll behavior. On mobile, touch
         activation/focus/visual-viewport changes can generate scroll events
         even when the user did not intentionally scroll, which was closing the
         Cluster menu immediately after it opened. */
      const mobile=window.matchMedia&&window.matchMedia('(max-width:820px)').matches;
      if(!mobile)closeRowActionMenu();
    },true);
