  // Communication Detail v5: header search icon opens a compact search input.
  (function installHeaderSearchPopover(){
    if(window.__uluHeaderSearchPopoverInstalled)return;
    window.__uluHeaderSearchPopoverInstalled=true;
    function findHeaderSearchTrigger(target){
      if(!target||!target.closest)return null;
      const direct=target.closest('[data-ulu-header-search],[aria-label="Search"],[title="Search"],.header-search,.top-search,.fa-search,.bi-search,.icon-search');
      if(!direct)return null;
      return direct.matches('button,a,[role="button"]')?direct:direct.closest('button,a,[role="button"]');
    }
    function popover(){
      let pop=document.getElementById('uluHeaderSearchPopover');
      if(pop)return pop;
      pop=document.createElement('div');
      pop.id='uluHeaderSearchPopover';pop.hidden=true;
      pop.innerHTML='<div class="ulu-header-search-row"><span class="ulu-header-search-icon" aria-hidden="true">⌕</span><input type="search" data-ulu-header-search-input placeholder="Search name or keyword..." autocomplete="off" aria-label="Search name or keyword"></div>';
      document.body.appendChild(pop);
      pop.querySelector('input').addEventListener('input',function(){
        let canonical=document.getElementById('gfKeywordSearch');
        if(canonical){canonical.value=this.value;canonical.dispatchEvent(new Event('input',{bubbles:true}));}
      });
      return pop;
    }
    function position(pop,trigger){
      const r=trigger.getBoundingClientRect();
      pop.style.top=Math.min(window.innerHeight-64,r.bottom+8)+'px';
      const w=Math.min(360,window.innerWidth-24);
      pop.style.left=Math.max(12,Math.min(window.innerWidth-w-12,r.right-w))+'px';
    }
    document.addEventListener('click',function(e){
      const trigger=findHeaderSearchTrigger(e.target);
      const pop=document.getElementById('uluHeaderSearchPopover');
      if(trigger){e.preventDefault();e.stopPropagation();const p=popover();const opening=p.hidden;position(p,trigger);p.hidden=!opening;if(opening){const input=p.querySelector('input');requestAnimationFrame(()=>input&&input.focus())}return;}
      if(pop&&!pop.hidden&&!pop.contains(e.target))pop.hidden=true;
    },true);
    document.addEventListener('keydown',function(e){if(e.key==='Escape'){const p=document.getElementById('uluHeaderSearchPopover');if(p&&!p.hidden)p.hidden=true}});
  })();

  // Brand Voice v2: keep the table-first Brand Library layout as the Brand dashboard.
  // The chart row is available in the Communication Intelligence Brief modal and is intentionally not mounted on the default dashboard.
  PANEL_CONTENT["brand/Dashboard"] = Object.assign({}, PANEL_CONTENT["brand/Library"]);

  function renderSubtabs() {
    elSubtabs.innerHTML = "";

    // The revised Signals area is now a single dashboard panel. Keep the
    // shared global filters visible, but hide the sub-tab row for Signals.
    if (state.main === "signals" || state.main === "brand" || state.main === "media") {
      elSubtabs.hidden = true;
      elSubtabs.style.display = "none";
      return;
    }

    elSubtabs.hidden = false;
    elSubtabs.style.display = "flex";
    const subs = DATA[state.main].subtabs;

    subs.forEach(name => {
      const btn = document.createElement("button");
      btn.className = "subtab";
      btn.type = "button";
      btn.textContent = name;
      btn.dataset.sub = name;
      btn.setAttribute("aria-selected", String(name === state.sub));
      btn.addEventListener("click", () => {
        state.sub = name;
        state.lastSubByMain[state.main] = name;
        renderSubtabs();
        renderContent();
        announce(`${DATA[state.main].label} / ${state.sub}`);
      });
      elSubtabs.appendChild(btn);
    });
  }

  
  function renderContent() {
    // Backwards-compatible wrapper; actual caching logic is in activatePanel()
    activatePanel(state.main, state.sub);
  }

function setMainTab(mainKey) {
    // Remember last visited sub-tab per main tab (so revisits keep your place)
    if (state.main) state.lastSubByMain[state.main] = state.sub;

    state.main = mainKey;
    // Use last visited sub-tab if it still exists, otherwise fall back to the first available sub-tab
const preferredSub = state.lastSubByMain[mainKey];
const availableSubs = DATA[mainKey].subtabs;
state.sub = (preferredSub && availableSubs.includes(preferredSub)) ? preferredSub : availableSubs[0];



    setSignalsInfoVisible(mainKey === "signals" || mainKey === "brand" || mainKey === "media");

    document.querySelectorAll(".main-tab").forEach(btn => {
      const on = btn.dataset.main === mainKey;
      btn.setAttribute("aria-selected", String(on));
    });

    renderSubtabs();
    renderContent();
    try { ensureDivisionAndBrandFiltersVisible(); } catch (err) { console.warn("[ULUsignals] Required filters could not be added", err); }
    announce(`${DATA[state.main].label} / ${state.sub}`);
  }

  function announce(text){
    elStatus.textContent = text;
  }

  document.querySelectorAll(".main-tab").forEach(btn => {
    btn.addEventListener("click", () => setMainTab(btn.dataset.main));
  });

  setSignalsInfoVisible(state.main === "signals" || state.main === "brand" || state.main === "media");

  // IMPORTANT: mount the initial dashboard before running optional shell
  // enhancements. A failure in filter/search setup must never prevent the
  // Signals panel from appearing.
  try {
    renderSubtabs();
    renderContent();
    ensureDivisionAndBrandFiltersVisible();
    announce(`${DATA[state.main].label} / ${state.sub}`);
  } catch (err) {
    console.error("[ULUsignals] Initial dashboard mount failed", err);
  }

  // Build optional Global Filters UI after the panel is already mounted.
  // Keep this isolated so a shell-control error cannot blank the dashboard.
  window.setTimeout(() => {
    try {
      buildGlobalFilterMenus();
    } catch (err) {
      console.warn("[ULUsignals] Global filter enhancement skipped", err);
    }
  }, 0);

