/* === Global Filters Repair: reliable controls for all three main tabs === */
(function repairSharedGlobalFilters(){
  return; // Disabled: superseded by the corrected original global-filter builder.
  function onReady(fn){
    if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fn, {once:true});
    else fn();
  }

  onReady(function(){
    // Required display order:
    // Global Filters | Division | Brand | Time Range | Product | Campaign |
    // Region | Apply Filters | Reset
    const FILTERS = [
      ['division','Division','All',['All','Consumer Products','Enterprise','Creator Solutions','Professional Services']],
      ['brand','Brand','All',['All','ULUsignals','ULU Technologies','GrowthCo','Zoey Cam']],
      ['timeRange','Time Range','Last 7 Days',['Last 24 Hours','Last 7 Days','Last 30 Days','Last 3 Months','Last 6 Months','Last 12 Months','Custom Date Range']],
      ['product','Product','All',['All','Excell 2000 Charger','Solux Solar Charger','Roomba Turbo Kit','X300 Webcam','AccuCal Laser Measuring']],
      ['campaign','Campaign','All',['All','Solux Intro Promo','Spring Clearance All Products','Webcam 20% Discount','Big Game Blowout for X300']],
      ['region','Region','United States',['International','United States','AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VT','VA','WA','WV','WI','WY']]
    ];

    function findRow(){
      const direct = document.getElementById('globalFilters');
      if(direct) return direct;
      const nodes = Array.from(document.querySelectorAll('div,section,nav,form'));
      return nodes.find(el => {
        const t=(el.textContent||'').replace(/\s+/g,' ').trim();
        return t.includes('Global Filters') && t.includes('Apply Filters') && t.includes('Reset');
      }) || null;
    }

    function installStyles(){
      if(document.getElementById('uluGlobalFilterRepairStyles')) return;
      const s=document.createElement('style');
      s.id='uluGlobalFilterRepairStyles';
      s.textContent=(window.APP_STYLE_SECTIONS && window.APP_STYLE_SECTIONS.uluGlobalFilterRepairStyles) || "";
      document.head.appendChild(s);
    }

    function closeAll(row, except){
      row.querySelectorAll('.ulu-gf-control').forEach(c=>{
        if(c===except) return;
        c.classList.remove('is-open');
        const b=c.querySelector('.ulu-gf-button');
        const m=c.querySelector('.ulu-gf-menu');
        if(b) b.setAttribute('aria-expanded','false');
        if(m) m.hidden=true;
      });
    }

    function buildControl(row, key, label, defaultValue, options){
      const wrap=document.createElement('div');
      wrap.className='ulu-gf-control';
      wrap.dataset.filter=key;
      wrap.dataset.value=defaultValue;
      const btn=document.createElement('button');
      btn.type='button';
      btn.className='ulu-gf-button';
      btn.setAttribute('aria-haspopup','listbox');
      btn.setAttribute('aria-expanded','false');
      btn.innerHTML=`<span>${label}: <b data-value-label>${defaultValue}</b></span><span class="ulu-gf-caret" aria-hidden="true"></span>`;
      const menu=document.createElement('div');
      menu.className='ulu-gf-menu';
      menu.setAttribute('role','listbox');
      menu.hidden=true;
      options.forEach(value=>{
        const opt=document.createElement('button');
        opt.type='button';
        opt.className='ulu-gf-option';
        opt.textContent=value;
        opt.dataset.value=value;
        opt.setAttribute('role','option');
        opt.setAttribute('aria-selected',String(value===defaultValue));
        opt.addEventListener('click',function(e){
          e.preventDefault(); e.stopPropagation();
          wrap.dataset.value=value;
          const valueLabel=btn.querySelector('[data-value-label]');
          if(valueLabel) valueLabel.textContent=value;
          menu.querySelectorAll('.ulu-gf-option').forEach(x=>x.setAttribute('aria-selected',String(x===opt)));
          closeAll(row);
        });
        menu.appendChild(opt);
      });
      btn.addEventListener('click',function(e){
        e.preventDefault(); e.stopPropagation();
        const opening=menu.hidden;
        closeAll(row,wrap);
        wrap.classList.toggle('is-open',opening);
        btn.setAttribute('aria-expanded',String(opening));
        menu.hidden=!opening;
      });
      wrap.append(btn,menu);
      return wrap;
    }

    function repair(){
      const row=findRow();
      if(!row) return;
      installStyles();
      row.dataset.uluFilterRepair='1';
      row.classList.add('ulu-gf-repair');

      // Remove every old implementation of the six dropdown controls. This
      // includes both the original .gf-dd controls and controls created by a
      // previous repair pass. Search, the info icon, and the Global Filters
      // label are intentionally preserved.
      row.querySelectorAll('.gf-dd, .ulu-gf-control').forEach(node=>node.remove());
      Array.from(row.children).forEach(child=>{
        const t=(child.textContent||'').replace(/\s+/g,' ').trim();
        if(/^(Time Range|Product|Campaign|Division|Brand|Region)\s*:/.test(t)) child.remove();
      });

      const buttons=Array.from(row.querySelectorAll('button'));
      const apply=buttons.find(b=>/^\s*Apply Filters\s*$/i.test(b.textContent||''));
      const reset=buttons.find(b=>/^\s*Reset\s*$/i.test(b.textContent||''));

      // Place the six controls immediately before Apply Filters. Because the
      // array above is already in the requested order, the visual sequence is
      // deterministic on Signals, Brand Voice, and Media.
      const anchor=(apply && apply.parentNode===row) ? apply : ((reset && reset.parentNode===row) ? reset : null);
      FILTERS.forEach(def=>{
        const control=buildControl(row,...def);
        if(anchor) row.insertBefore(control,anchor);
        else row.appendChild(control);
      });

      // Force Apply Filters and Reset to follow Region, even if the shell had
      // previously placed those buttons earlier in the row.
      if(apply && apply.parentNode===row) row.appendChild(apply);
      if(reset && reset.parentNode===row) row.appendChild(reset);

      // Do not recreate the persistent Search field. The top header search icon is
      // the single search entry point; remove any legacy copies left by older builds.
      row.querySelectorAll('.gf-keyword-search-wrap,.ulu-gf-search-wrap,.ulu-clean-gf-search-wrap').forEach(node=>node.remove());

      // Reset now resets all six filters.
      if(reset && reset.dataset.uluFilterResetBound!=='1'){
        reset.dataset.uluFilterResetBound='1';
        reset.addEventListener('click',function(){
          FILTERS.forEach(([key,,value])=>{
            const c=row.querySelector(`.ulu-gf-control[data-filter="${key}"]`);
            if(!c) return;
            c.dataset.value=value;
            const label=c.querySelector('[data-value-label]'); if(label) label.textContent=value;
            c.querySelectorAll('.ulu-gf-option').forEach(o=>o.setAttribute('aria-selected',String(o.dataset.value===value)));
          });
          closeAll(row);
        });
      }

      document.addEventListener('click',e=>{ if(!row.contains(e.target)) closeAll(row); });
      document.addEventListener('keydown',e=>{ if(e.key==='Escape') closeAll(row); });
    }

    // Run after the app shell has completed its own initial render, then retry
    // briefly in case the shared filter row is injected asynchronously.
    setTimeout(repair,0);
    setTimeout(repair,150);
    setTimeout(repair,600);
    setTimeout(repair,1200);

    // Older initialization code may inject Division/Brand after the first
    // paint. Watch briefly and normalize the row again whenever that happens.
    const row=findRow();
    if(row && !row.__uluFilterOrderObserver){
      let timer=0;
      const observer=new MutationObserver(()=>{
        clearTimeout(timer);
        timer=setTimeout(repair,25);
      });
      observer.observe(row,{childList:true});
      row.__uluFilterOrderObserver=observer;
      setTimeout(()=>{ try{ observer.disconnect(); }catch(e){} },2500);
    }
  });
})();

/* === Mobile full-bleed layout repair === */
(function installMobileFullBleedLayout(){
  function apply(){
    if(!document.getElementById('uluMobileFullBleedStyles')){
      const style=document.createElement('style');
      style.id='uluMobileFullBleedStyles';
      style.textContent=window.APP_STYLE_SECTIONS.uluMobileFullBleedStyles;
      document.head.appendChild(style);
    }

    document.body.classList.add('ulu-mobile-full-bleed');

    // Mark the shell containers that wrap the shared filters and live panel.
    // This removes inherited desktop max-widths/margins without changing the
    // desktop layout or the internal card padding used for readability.
    const content=document.getElementById('content');
    const filters=document.getElementById('globalFilters');
    [content,filters].forEach(node=>{
      let current=node;
      let depth=0;
      while(current && current!==document.body && depth<4){
        current.classList.add('ulu-mobile-full-bleed-node');
        current=current.parentElement;
        depth++;
      }
    });
  }

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',apply,{once:true});
  else apply();
})();

