/* === Mobile tooltip hard-fix: dedicated tap dialog === */
(function installMobileTooltipTapDialog(){
  if (window.__uluMobileTooltipTapDialogInstalled) return;
  window.__uluMobileTooltipTapDialogInstalled = true;

  const isMobileMode = () => {
    try {
      return window.innerWidth <= 820 ||
        (window.matchMedia && window.matchMedia('(hover: none), (pointer: coarse)').matches);
    } catch (e) {
      return window.innerWidth <= 820;
    }
  };

  const overlay = document.createElement('div');
  overlay.id = 'uluMobileTooltipOverlay';
  overlay.hidden = true;
  overlay.setAttribute('role', 'presentation');
  overlay.innerHTML = `
    <section class="ulu-mobile-tooltip-dialog" role="dialog" aria-modal="true" aria-labelledby="uluMobileTooltipTitle">
      <header class="ulu-mobile-tooltip-head">
        <h2 id="uluMobileTooltipTitle"></h2>
        <button type="button" class="ulu-mobile-tooltip-close" aria-label="Close tooltip">&times;</button>
      </header>
      <div class="ulu-mobile-tooltip-divider"></div>
      <div class="ulu-mobile-tooltip-body"></div>
    </section>
  `;

  const style = document.createElement('style');
  style.id = 'uluMobileTooltipTapDialogStyles';
  style.textContent = window.APP_STYLE_SECTIONS.uluMobileTooltipTapDialogStyles;

  document.head.appendChild(style);
  document.body.appendChild(overlay);

  const titleEl = overlay.querySelector('#uluMobileTooltipTitle');
  const bodyEl = overlay.querySelector('.ulu-mobile-tooltip-body');
  const closeBtn = overlay.querySelector('.ulu-mobile-tooltip-close');
  let lastOpenedAt = 0;
  let activeTrigger = null;

  function safeTooltipHTML(value){
    const template = document.createElement('template');
    template.innerHTML = String(value || '');
    const allowed = new Set(['B','STRONG','I','EM','U','BR','P','DIV','SPAN','UL','OL','LI','TABLE','THEAD','TBODY','TR','TH','TD','HR']);
    template.content.querySelectorAll('script,style,iframe,object,embed,link,meta').forEach(node => node.remove());
    Array.from(template.content.querySelectorAll('*')).forEach(node => {
      if (!allowed.has(node.tagName)) {
        node.replaceWith(...Array.from(node.childNodes));
        return;
      }
      Array.from(node.attributes).forEach(attr => node.removeAttribute(attr.name));
    });
    return template.innerHTML;
  }

  function openMobileTooltip(trigger){
    if (!trigger || !isMobileMode()) return;
    activeTrigger = trigger;
    titleEl.textContent = trigger.getAttribute('data-tooltip-title') || trigger.getAttribute('aria-label') || 'Information';
    bodyEl.innerHTML = safeTooltipHTML(trigger.getAttribute('data-tooltip-body') || '');
    overlay.hidden = false;
    document.documentElement.classList.add('ulu-mobile-tooltip-open');
    lastOpenedAt = Date.now();
    requestAnimationFrame(() => closeBtn.focus({preventScroll:true}));
  }

  function closeMobileTooltip(){
    overlay.hidden = true;
    document.documentElement.classList.remove('ulu-mobile-tooltip-open');
    if (activeTrigger && document.contains(activeTrigger)) {
      try { activeTrigger.focus({preventScroll:true}); } catch (e) {}
    }
    activeTrigger = null;
  }

  function findTrigger(event){
    const path = typeof event.composedPath === 'function' ? event.composedPath() : [];
    for (const node of path) {
      if (node && node.nodeType === 1 && node.matches && node.matches('[data-tooltip-title]')) return node;
    }
    const target = event.target && event.target.nodeType === 1 ? event.target : event.target?.parentElement;
    return target?.closest?.('[data-tooltip-title]') || null;
  }

  function activate(event){
    if (!isMobileMode()) return;
    const trigger = findTrigger(event);
    if (!trigger || overlay.contains(trigger)) return;
    if (event.cancelable) event.preventDefault();
    event.stopPropagation();
    if (typeof event.stopImmediatePropagation === 'function') event.stopImmediatePropagation();
    openMobileTooltip(trigger);
  }

  // pointerup/touchend occur after the legacy pointerdown handler and are not
  // used by the desktop tooltip system. This gives mobile taps an independent,
  // deterministic activation path.
  document.addEventListener('pointerup', activate, {capture:true, passive:false});
  document.addEventListener('touchend', activate, {capture:true, passive:false});

  // Keyboard and mobile emulation fallback. Ignore the synthetic click that
  // follows a pointer/touch activation so the dialog cannot immediately close.
  document.addEventListener('click', function(event){
    if (!isMobileMode() || Date.now() - lastOpenedAt < 700) return;
    activate(event);
  }, true);

  closeBtn.addEventListener('click', function(event){
    event.preventDefault();
    event.stopPropagation();
    closeMobileTooltip();
  });
  overlay.addEventListener('click', function(event){
    if (event.target === overlay) closeMobileTooltip();
  });
  document.addEventListener('keydown', function(event){
    if (event.key === 'Escape' && !overlay.hidden) closeMobileTooltip();
  });
})();

/* === Global Filters tooltip: use the canonical button on desktop and mobile === */
(function installGlobalFiltersCanonicalInfoButton(){
  if (window.__uluGlobalFiltersCanonicalInfoInstalled) return;
  window.__uluGlobalFiltersCanonicalInfoInstalled = true;

  function installStyles(){
    if (document.getElementById('uluGlobalFiltersCanonicalInfoStyles')) return;
    const style = document.createElement('style');
    style.id = 'uluGlobalFiltersCanonicalInfoStyles';
    style.textContent = (window.APP_STYLE_SECTIONS && window.APP_STYLE_SECTIONS.uluGlobalFiltersCanonicalInfoStyles) || "";
    document.head.appendChild(style);
  }

  function normalizeButton(){
    const row = document.getElementById('globalFilters');
    const button = document.getElementById('signalsInfoBtn');
    if (!row || !button) return;

    // Remove the old duplicate/proxy implementation if an earlier cached
    // script created one. The original button remains the only control.
    const proxy = document.getElementById('uluGlobalFiltersInfoMobileProxy');
    if (proxy) proxy.remove();

    const actionGroup = document.getElementById('uluGlobalActions');
    if (actionGroup && actionGroup.parentElement === row) {
      if (button.parentElement !== actionGroup) actionGroup.appendChild(button);
    } else if (button.parentElement !== row) {
      row.appendChild(button);
    }
    button.type = 'button';
    button.hidden = false;
    button.removeAttribute('aria-hidden');
    button.tabIndex = 0;

    // Keep a valid tooltip payload even during the brief interval before the
    // active-tab copy is populated.
    if (!button.getAttribute('data-tooltip-title')) {
      button.setAttribute('data-tooltip-title', button.getAttribute('aria-label') || 'Global Filters');
    }
    if (!button.hasAttribute('data-tooltip-body')) {
      button.setAttribute('data-tooltip-body', 'Use these filters to refine the audience intelligence displayed on the current tab.');
    }
  }

  function start(){
    installStyles();
    normalizeButton();
    // The shared filter row can be rebuilt during initial rendering and tab
    // changes. Re-normalize a few times without observing button attributes or
    // intercepting page-wide click events.
    setTimeout(normalizeButton, 100);
    setTimeout(normalizeButton, 500);
    setTimeout(normalizeButton, 1200);
    window.addEventListener('resize', normalizeButton, {passive:true});
    window.addEventListener('orientationchange', normalizeButton, {passive:true});
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, {once:true});
  else start();
})();


/* === Common Global Filter shortcuts: Calendar + Asset Vault === */
(function installGlobalFilterShortcuts(){
  if(window.__uluGlobalFilterShortcutsInstalled)return;
  window.__uluGlobalFilterShortcutsInstalled=true;

  function installStyles(){
    if(document.getElementById('uluGlobalFilterShortcutStyles'))return;
    const style=document.createElement('style');
    style.id='uluGlobalFilterShortcutStyles';
    style.textContent=(window.APP_STYLE_SECTIONS&&window.APP_STYLE_SECTIONS.uluGlobalFilterShortcutStyles)||'';
    document.head.appendChild(style);
  }
  function modal(){
    let el=document.getElementById('uluGlobalShortcutModal');
    if(el)return el;
    el=document.createElement('div');
    el.id='uluGlobalShortcutModal';
    el.hidden=true;
    el.setAttribute('role','dialog');
    el.setAttribute('aria-modal','true');
    try{el.style.fontFamily=window.getComputedStyle(document.body).fontFamily;}catch(_e){}
    el.innerHTML='<section class="ulu-global-shortcut-modal-card"><header class="ulu-global-shortcut-modal-head"><strong data-ulu-global-shortcut-modal-title>Coming Soon</strong><button class="ulu-global-shortcut-modal-close" type="button" data-ulu-global-shortcut-close aria-label="Close">×</button></header><div class="ulu-global-shortcut-modal-body"><img data-ulu-global-shortcut-modal-icon src="https://ulutechnologies.ai/ulusignals/logos/calendar-link.svg" alt=""><h3>Coming Soon</h3><p data-ulu-global-shortcut-modal-copy>This feature will be available in a future ULUsignals update.</p></div></section>';
    document.documentElement.appendChild(el);
    return el;
  }
  function openModal(kind){
    const el=modal();
    if(el.parentElement!==document.documentElement)document.documentElement.appendChild(el);
    const isCalendar=kind==='calendar';
    el.querySelector('[data-ulu-global-shortcut-modal-title]').textContent=isCalendar?'Publishing Schedule':'Vault';
    el.querySelector('[data-ulu-global-shortcut-modal-icon]').src=isCalendar?'https://ulutechnologies.ai/ulusignals/logos/calendar-link.svg':'https://ulutechnologies.ai/ulusignals/logos/asset-vault.svg';
    el.querySelector('[data-ulu-global-shortcut-modal-copy]').textContent=isCalendar?'Publishing Schedule is coming soon.':'ULU Communication Vault and Audience Intelligence Warehouse';
    el.hidden=false;
    document.body.style.overflow='hidden';
    const close=el.querySelector('[data-ulu-global-shortcut-close]');
    if(close)requestAnimationFrame(()=>close.focus());
  }
  function closeModal(){
    const el=document.getElementById('uluGlobalShortcutModal');
    if(!el)return;
    el.hidden=true;
    document.body.style.removeProperty('overflow');
  }
  function makeButton(id,label,src,kind){
    const b=document.createElement('button');
    b.id=id;b.type='button';b.className='ulu-global-shortcut';
    b.setAttribute('aria-label',label);b.setAttribute('title',label);
    b.setAttribute('data-ulu-global-shortcut',kind);
    b.innerHTML='<img src="'+src+'" alt="" aria-hidden="true">';
    return b;
  }
  function normalize(){
    const row=document.getElementById('globalFilters');
    if(!row)return;
    let group=document.getElementById('uluGlobalActions');
    if(!group){
      group=document.createElement('div');
      group.id='uluGlobalActions';
      group.className='ulu-global-actions';
      group.setAttribute('aria-label','Global shortcuts');
    }
    if(group.parentElement!==row)row.appendChild(group);
    let calendar=document.getElementById('uluGlobalCalendarLink');
    let vault=document.getElementById('uluGlobalAssetVaultLink');
    if(!calendar)calendar=makeButton('uluGlobalCalendarLink','Calendar','https://ulutechnologies.ai/ulusignals/logos/calendar-link.svg','calendar');
    if(!vault)vault=makeButton('uluGlobalAssetVaultLink','Asset Vault','https://ulutechnologies.ai/ulusignals/logos/asset-vault.svg','asset-vault');
    const info=document.getElementById('signalsInfoBtn');
    if(calendar.parentElement!==group)group.appendChild(calendar);
    if(vault.parentElement!==group)group.appendChild(vault);
    if(info&&info.parentElement!==group)group.appendChild(info);
    if(info){group.appendChild(calendar);group.appendChild(vault);group.appendChild(info);}
  }
  document.addEventListener('click',function(e){
    const trigger=e.target&&e.target.closest&&e.target.closest('[data-ulu-global-shortcut]');
    if(trigger){e.preventDefault();e.stopPropagation();openModal(trigger.getAttribute('data-ulu-global-shortcut'));return;}
    const el=document.getElementById('uluGlobalShortcutModal');
    if(!el||el.hidden)return;
    if(e.target===el||e.target.closest('[data-ulu-global-shortcut-close]')){e.preventDefault();closeModal();}
  },true);
  document.addEventListener('keydown',function(e){if(e.key==='Escape'){const el=document.getElementById('uluGlobalShortcutModal');if(el&&!el.hidden)closeModal();}});
  function start(){installStyles();normalize();setTimeout(normalize,100);setTimeout(normalize,500);setTimeout(normalize,1200);window.addEventListener('resize',normalize,{passive:true});window.addEventListener('orientationchange',normalize,{passive:true});}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();


