      '<section class="ulu-profile-section ulu-vault-controls"><div class="ulu-vault-scope-row"><div class="ulu-vault-scope"><span>Scope:</span><strong>Johnston Industrial / Corporate Communications</strong></div><button class="ulu-card-link" type="button">Change</button></div><div class="ulu-vault-search-row"><span class="ulu-vault-search-icon">⌕</span><input type="search" class="ulu-profile-input" data-library-search-input placeholder="Search by title, campaign, strategy angle, tag or creator..."><button class="ulu-profile-btn primary" type="button" data-library-search>Search</button><button class="ulu-profile-btn ulu-library-upload-btn" type="button" data-library-upload>Upload</button><input class="ulu-library-upload-input" type="file" data-library-upload-input accept="image/*,video/*,audio/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt"></div><div class="ulu-vault-filter-row"><select class="ulu-profile-select" data-library-filter="type"><option>All asset types</option><option>Script</option><option>Image</option><option>Video</option><option>Document</option></select><select class="ulu-profile-select" data-library-filter="status"><option>All statuses</option><option>Approved</option></select><select class="ulu-profile-select" data-library-filter="platform"><option>All platforms</option><option>YouTube</option><option>Website</option><option>LinkedIn</option><option>Instagram</option></select><select class="ulu-profile-select"><option>All campaigns</option><option>Fall Launch</option><option>Always On</option><option>Enterprise</option><option>Q4 Creator</option><option>Product Launch</option></select><select class="ulu-profile-select"><option>Date added</option><option>Newest first</option><option>Oldest first</option></select></div><div class="ulu-vault-results-toolbar"><span>'+uluProfileState.library.length+' total assets</span><div><label>Sort by: <select class="ulu-profile-select"><option>Date added</option><option>Title</option><option>Type</option></select></label><button type="button" class="ulu-vault-view-btn is-active" aria-label="Grid view">▦</button><button type="button" class="ulu-vault-view-btn" aria-label="List view">☷</button></div></div></section><section class="ulu-profile-section ulu-vault-results-section"><div class="ulu-library-list" data-library-results>'+cards+'</div><div class="ulu-vault-pagination"><button type="button">‹</button><button type="button" class="is-active">1</button><button type="button">2</button><button type="button">3</button><button type="button">4</button><button type="button">5</button><span>…</span><button type="button">10</button><button type="button">›</button></div><div class="ulu-vault-showing">Showing 1-8 of 234</div></section></div>';
