  /* v74: Dedicated mobile Asset Vault detail destination. This is deliberately
     rendered inside #uluMobileProfileFrame rather than as a modal/drawer so the
     selected asset replaces the Asset Vault list view and uses the frame's Back
     button for navigation. */
  function assetVaultDetailHTML(id){
    var a=uluProfileState.library.find(function(x){return String(x.id)===String(id);});
    if(!a) return '<div class="ulu-profile-detail ulu-vault-mobile-detail" data-profile-panel="asset-detail">'+profilePanelHead('Asset Detail','The selected asset is no longer available.','ASSET')+'</div>';
    var versionLabel=String(a.history||'').match(/\d+/);
    versionLabel=versionLabel?('V'+versionLabel[0]):'APPROVED';
    var media=a.thumbnail?'<img src="'+esc(a.thumbnail)+'" alt="'+esc((a.title||'Selected asset')+' preview')+'">':'<div class="ulu-vault-mobile-detail-placeholder">'+(a.type==='Video'?'▶':a.type==='Image'?'▧':'≡')+'</div>';
    return '<div class="ulu-profile-detail ulu-vault-mobile-detail" data-profile-panel="asset-detail" data-asset-detail-id="'+esc(String(a.id||''))+'">'+
      profilePanelHead(a.title||'Selected Asset','Approved asset details and available actions.',versionLabel)+
      '<section class="ulu-profile-section ulu-vault-mobile-detail-card"><div class="ulu-vault-mobile-detail-media">'+media+'</div><div class="ulu-vault-mobile-detail-copy"><h4>Description</h4><p>'+esc(a.description||'Approved asset available for use across the active brand and authorized communications.')+'</p></div><div class="ulu-vault-mobile-detail-meta"><span><b>Type</b>'+esc(a.type||'Asset')+(a.assetMetric?' · '+esc(a.assetMetric):'')+'</span><span><b>Platform</b>'+esc(a.platform||'—')+'</span><span><b>Campaign</b>'+esc(a.campaign||'—')+'</span><span><b>Status</b>'+esc(a.approval||a.status||'Approved')+'</span><span><b>Version</b>'+esc(a.history||'Version history available')+'</span><span><b>Workspace</b>'+esc(a.usage||'Available in workspace')+'</span></div><div class="ulu-vault-mobile-detail-actions"><button class="ulu-profile-btn primary" type="button" data-library-preview="'+esc(String(a.id||''))+'">▶ Preview</button><button class="ulu-profile-btn primary" type="button" data-library-history="'+esc(String(a.id||''))+'">◷ Version History</button><button class="ulu-profile-btn primary" type="button" data-library-use="'+esc(String(a.id||''))+'">↗ Use in Workspace</button></div></section></div>';
  }

  function teamPermissionsHTML(){
    if(!isPrimaryProfileUser()) return '<div class="ulu-profile-detail">'+profilePanelHead('Team & Permissions','This area is available to the primary account user.','OWNER ONLY')+'<div class="ulu-profile-lock"><span>🔒</span><span>Your account does not include permission to manage team access.</span></div></div>';
    var team=uluProfileState.team.map(function(u,i){var avatar=u.photo?'<span class="ulu-team-avatar"><img src="'+esc(u.photo)+'" alt="'+esc(u.name)+' profile photo" loading="lazy"></span>':'<span class="ulu-team-avatar ulu-team-avatar-fallback">'+esc((u.name||'?').charAt(0).toUpperCase())+'</span>';return '<article class="ulu-team-card" data-team-index="'+i+'"><div class="ulu-team-card-head"><div class="ulu-team-person"><span class="ulu-mini-pill '+(u.status==='Active'?'green':'gold')+'">'+esc(u.status)+'</span><div><strong>'+esc(u.name)+'</strong><p>'+esc(u.email)+'</p></div></div>'+avatar+'</div><div class="ulu-team-meta"><span class="ulu-mini-pill">'+esc(u.role)+'</span><span class="ulu-mini-pill">'+esc(u.access)+'</span></div><div class="ulu-card-actions">'+(u.role==='Account Owner'?'':'<button class="ulu-card-link" type="button" data-team-role="'+i+'">Change role</button><button class="ulu-card-link" type="button" data-team-access="'+i+'">Brand access</button><button class="ulu-card-link" type="button" data-team-remove="'+i+'">Remove</button>')+'</div></article>';}).join('');
    var roles=[['Account Owner','Billing, organization, all brands, users, approvals'],['Blueprint Manager','Edit and approve assigned Brand Blueprints'],['Publisher','Create, approve, schedule and publish where authorized'],['Contributor','Create and edit drafts/assets, no final approval'],['Reviewer','Review and comment only'],['Viewer','Read-only access to assigned areas']];
    return '<div class="ulu-profile-detail" data-profile-panel="team">'+profilePanelHead('Team & Permissions','Invite users and control role and brand/division access.','OWNER')+'<section class="ulu-profile-section"><div class="ulu-profile-section-title">Invite Team Member</div><div class="ulu-team-invite"><input type="email" class="ulu-profile-input" data-team-invite-email placeholder="name@company.com"><button class="ulu-profile-btn primary" type="button" data-team-invite>Invite</button></div></section><section class="ulu-profile-section"><div class="ulu-profile-section-title">Users</div><div class="ulu-team-list">'+team+'</div></section><section class="ulu-profile-section"><div class="ulu-profile-section-title">Roles & Core Access</div><div class="ulu-role-table">'+roles.map(function(r){return '<div class="ulu-role-row"><strong>'+r[0]+'</strong><span>'+r[1]+'</span></div>';}).join('')+'</div></section><div class="ulu-profile-inline-note">Each brand/division has its own confidential Blueprint, assets, history, and intelligence. Only authorized users can access assigned areas.</div></div>';
  }

  function accountSettingsHTML(){
    if(!isPrimaryProfileUser()) return '<div class="ulu-profile-detail">'+profilePanelHead('Account Settings','This area is available to the primary account user.','OWNER ONLY')+'<div class="ulu-profile-lock"><span>🔒</span><span>Your account does not include permission to manage billing or subscription settings.</span></div></div>';
    var p=uluProfileState.plan,total=(p.seats*p.seatPrice).toFixed(2);
    return '<div class="ulu-profile-detail" data-profile-panel="account">'+profilePanelHead('Account Settings','Plan, seats, billing, security, and organization settings.','PRIMARY')+'<section class="ulu-profile-section"><div class="ulu-profile-section-title">Subscription</div><div class="ulu-plan-hero"><div><h4>'+esc(p.name)+'</h4><div class="ulu-team-meta"><span class="ulu-mini-pill">'+p.seats+' seats</span><span class="ulu-mini-pill green">Ask AL included</span></div></div><div class="ulu-plan-price">$'+total+'<small>per month</small></div></div><div class="ulu-plan-progress"><span></span></div><div class="ulu-plan-metrics"><div class="ulu-plan-metric"><small>Current seats</small><strong>'+p.seats+'</strong></div><div class="ulu-plan-metric"><small>Seat minimum</small><strong>'+p.minSeats+'</strong></div><div class="ulu-plan-metric"><small>Renews</small><strong>'+esc(p.renewal)+'</strong></div></div><button class="ulu-profile-btn primary" style="width:100%;margin-top:9px" type="button" data-account-manage-plan>Manage Plan</button></section><section class="ulu-profile-section"><div class="ulu-profile-section-title">Organization</div><div class="ulu-subdetail-row"><span>Company</span><strong>ULU Technologies</strong></div><div class="ulu-subdetail-row"><span>Primary contact</span><strong>'+esc(uluProfileState.profile.name)+'</strong></div></section><section class="ulu-profile-section"><div class="ulu-profile-section-title">Security</div><div class="ulu-subdetail-row"><span>Password</span><button class="ulu-card-link" type="button" data-account-security>Change password</button></div><div class="ulu-subdetail-row"><span>Two-factor authentication</span><strong>Enabled</strong></div></section></div>';
  }

  function managePlanHTML(){
    var p=uluProfileState.plan,total=(p.seats*p.seatPrice).toFixed(2);
    return '<div class="ulu-profile-detail" data-profile-panel="plan">'+profilePanelHead('Manage Plan',isMobile()?'Full-screen mobile billing sheet for subscription changes.':'Subscription changes, seats, payment methods, and billing history.','BILLING')+'<section class="ulu-profile-section"><div class="ulu-plan-hero"><div><h4>'+esc(p.name)+'</h4><p style="margin:4px 0 0;color:#8eafd6;font-size:9px">10-seat minimum · $24.99 per seat/month · Ask AL included</p></div><div class="ulu-plan-price">$'+total+'<small>current monthly total</small></div></div></section><section class="ulu-profile-section"><div class="ulu-profile-section-title">Add Seats</div><div class="ulu-profile-grid-2"><div class="ulu-profile-field"><label>Seat quantity</label><input type="number" min="1" max="100" value="1" class="ulu-profile-number" data-plan-add-qty></div><div class="ulu-profile-field"><label>Revised monthly total</label><div class="ulu-profile-input" style="display:flex;align-items:center" data-plan-add-total>$'+((p.seats+1)*p.seatPrice).toFixed(2)+'</div></div></div><button class="ulu-profile-btn primary" style="width:100%;margin-top:8px" type="button" data-plan-confirm-seats>Confirm Added Seats</button></section><section class="ulu-profile-section"><div class="ulu-profile-section-title">Change Plan</div><select class="ulu-profile-select" data-plan-change><option selected>Enterprise - $24.99/seat, 10-seat minimum</option><option>ULUsignals + Ask AL - individual / parent account</option><option>ULUsignals Base - individual / parent account</option></select><button class="ulu-profile-btn" style="width:100%;margin-top:8px" type="button" data-plan-change-confirm>Review Plan Change</button></section><section class="ulu-profile-section"><div class="ulu-profile-section-title">Subscription Detail</div><div class="ulu-subdetail-row"><span>Plan</span><strong>'+esc(p.name)+'</strong></div><div class="ulu-subdetail-row"><span>Seats</span><strong>'+p.seats+'</strong></div><div class="ulu-subdetail-row"><span>Price</span><strong>$'+p.seatPrice.toFixed(2)+' / seat</strong></div><div class="ulu-subdetail-row"><span>Billing cycle</span><strong>'+esc(p.billingCycle)+'</strong></div><div class="ulu-subdetail-row"><span>Renewal date</span><strong>'+esc(p.renewal)+'</strong></div><div class="ulu-subdetail-row"><span>Billing contact</span><strong>'+esc(p.billingContact)+'</strong></div><div class="ulu-subdetail-row"><span>Payment method</span><strong>'+esc(p.payment)+'</strong></div></section><section class="ulu-profile-section"><div class="ulu-profile-section-title">Payment & Invoices</div><button class="ulu-profile-btn" style="width:100%" type="button" data-payment-update>Update Payment Method</button><div class="ulu-invoice-list" style="margin-top:8px"><div class="ulu-invoice-row"><div class="ulu-subdetail-row"><span>Sep 25, 2026</span><strong>$'+total+'</strong></div><button class="ulu-card-link" type="button">View invoice</button></div><div class="ulu-invoice-row"><div class="ulu-subdetail-row"><span>Aug 25, 2026</span><strong>$'+total+'</strong></div><button class="ulu-card-link" type="button">View invoice</button></div></div></section><div class="ulu-profile-inline-note">Billing actions shown here are front-end controls. Production billing changes should be confirmed on the server against the authenticated user, organization, active brand/division, role, and explicit permission.</div></div>';
  }

  function profileDestinationHTML(title){
    if(title==='Profile Manager') return profileManagerHTML();
    if(title==='Brand Blueprint') return brandBlueprintHTML();
    if(title==='Thought Log') return thoughtLogHTML();
    if(title==='Asset Vault' || title==='Approved Library') return approvedLibraryHTML();
    if(title==='Team & Permissions') return teamPermissionsHTML();
    if(title==='Account Settings') return accountSettingsHTML();
    return '<div class="ulu-mobile-hub"><div class="ulu-mobile-hub-intro"><h2>'+esc(title || 'Profile & Blueprint')+'</h2><p>This mobile destination is not yet configured.</p></div></div>';
  }


