  function updateDesktopAssetVaultRail(frame,id){
    if(!frame || frame.id!=='uluDesktopProfileShell') return;
    var a=uluProfileState.library.find(function(x){return String(x.id)===String(id);});
    if(!a) return;
    var current=frame.querySelector('[data-vault-selected-rail]');
    if(!current) return;
    var wrap=document.createElement('div');
    wrap.innerHTML=assetVaultSelectedRailHTML(a);
    var next=wrap.firstElementChild;
    if(next){ current.replaceWith(next); scaleDesktopProfileText(next); scaleDesktopAssetVaultText(next); }
  }

  /* v61: Increase desktop Profile workspace text by 30% while deliberately
     preserving the current font size inside form entry controls. The rail step
     numbers use the PDF-specific +20% size set in CSS above. */
  function scaleDesktopProfileText(root){
    if(!root) return;
    var nodes=[root].concat(Array.prototype.slice.call(root.querySelectorAll('*')));
    nodes.forEach(function(el){
      if(!el || el.nodeType!==1 || el.dataset.uluDesktopProfileFontScaled==='1') return;
      if(el.matches('input, textarea, select, option')) return;
      if(el.closest && el.closest('input, textarea, select')) return;
      if(el.matches('.ulu-desktop-profile-rail-num,.nav-ico,.ulu-desktop-profile-home-icon,.ulu-desktop-profile-home-chevron,.ulu-profile-menu-glyph,.ulu-profile-photo,.ulu-library-media,.ulu-profile-mic')) return;
      var hasDirectText=Array.prototype.some.call(el.childNodes,function(n){
        return n.nodeType===3 && String(n.nodeValue||'').trim().length>0;
      });
      if(!hasDirectText) return;
      var px=parseFloat(window.getComputedStyle(el).fontSize);
      if(!isFinite(px) || px<=0) return;
      el.style.fontSize=(px*1.30).toFixed(2)+'px';
      el.dataset.uluDesktopProfileFontScaled='1';
    });
  }

  /* v72: Increase the CURRENT rendered Asset Vault desktop typography by 25%.
     This runs after the existing Profile text scaler so the change is relative
     to the screen the user was reviewing, including controls that the generic
     scaler intentionally skips. Inline !important is used because several
     Asset Vault v70 rules also use !important. */
  function scaleDesktopAssetVaultText(root){
    if(!root) return;
    var scopes=[];
    if(root.matches && (root.matches('[data-profile-panel="library"]') || root.matches('.ulu-vault-selected-rail'))) scopes.push(root);
    if(root.querySelectorAll){
      Array.prototype.forEach.call(root.querySelectorAll('[data-profile-panel="library"],.ulu-vault-selected-rail'),function(n){scopes.push(n);});
    }
    scopes.forEach(function(scope){
      var nodes=[scope].concat(Array.prototype.slice.call(scope.querySelectorAll('*')));
      nodes.forEach(function(el){
        if(!el || el.nodeType!==1 || el.dataset.uluAssetVaultV72Scaled==='1') return;
        if(el.matches('.ulu-vault-search-icon,.ulu-vault-view-btn,.ulu-vault-thumb,.ulu-vault-thumb *')) return;
        var isControl=el.matches('input,textarea,select,button');
        var hasDirectText=Array.prototype.some.call(el.childNodes,function(n){
          return n.nodeType===3 && String(n.nodeValue||'').trim().length>0;
        });
        if(!isControl && !hasDirectText) return;
        var px=parseFloat(window.getComputedStyle(el).fontSize);
        if(!isFinite(px) || px<=0) return;
        el.style.setProperty('font-size',(px*1.25).toFixed(2)+'px','important');
        el.dataset.uluAssetVaultV72Scaled='1';
      });
    });
  }

  function ensureDesktopProfileShell(){
    var shell=document.getElementById('uluDesktopProfileShell');
    if(shell) return shell;
    shell=document.createElement('section');shell.id='uluDesktopProfileShell';shell.hidden=true;shell.setAttribute('role','region');shell.setAttribute('aria-label','Profile & Blueprints desktop workspace');
    shell.innerHTML='<aside class="ulu-desktop-profile-sidebar"></aside><main class="ulu-desktop-profile-main"></main>';
    document.documentElement.appendChild(shell);
    if(window.MutationObserver){
      var profileFontObserver=new MutationObserver(function(records){
        records.forEach(function(record){
          Array.prototype.forEach.call(record.addedNodes||[],function(node){
            if(node && node.nodeType===1 && !shell.hidden) scaleDesktopProfileText(node);
          });
        });
      });
      profileFontObserver.observe(shell,{childList:true,subtree:true});
    }
    return shell;
  }

  function sizeDesktopProfileShell(shell){
    var topbar=q('.topbar');var top=topbar?Math.max(0,Math.round(topbar.getBoundingClientRect().bottom)):58;shell.style.top=top+'px';
  }

  /* v73: Align the Asset Vault selected-asset rail to the actual top edge of
     the filter/control section instead of relying on a guessed padding value.
     This keeps the two top borders horizontally aligned even when text scaling
     or responsive sizing changes the height of the Asset Vault heading. */
  function syncDesktopAssetVaultRailAlignment(shell){
    shell=shell||document.getElementById('uluDesktopProfileShell');
    if(!shell||shell.hidden||isMobile()) return;
    var rail=shell.querySelector('.ulu-vault-selected-rail');
    var controls=shell.querySelector('.ulu-desktop-profile-content [data-profile-panel="library"] .ulu-vault-controls');
    var grid=shell.querySelector('.ulu-desktop-profile-stage-grid');
    if(!rail||!controls||!grid) return;
    if(window.innerWidth<=1120){rail.style.removeProperty('padding-top');return;}
    rail.style.paddingTop='0px';
    var gridTop=grid.getBoundingClientRect().top;
    var controlsTop=controls.getBoundingClientRect().top;
    var offset=Math.max(0,Math.round(controlsTop-gridTop));
    rail.style.setProperty('padding-top',offset+'px','important');
  }

  function showDesktopProfileRoot(){
    if(isMobile()) return;
    var shell=ensureDesktopProfileShell();sizeDesktopProfileShell(shell);shell.querySelector('.ulu-desktop-profile-sidebar').innerHTML=desktopProfileSidebarHTML('');shell.querySelector('.ulu-desktop-profile-main').innerHTML=desktopProfileHomeHTML();shell.hidden=false;document.body.classList.add('ulu-desktop-profile-open');
  }

  function openDesktopProfileDestination(title){
    if(isMobile()) return;
    var shell=ensureDesktopProfileShell();sizeDesktopProfileShell(shell);shell.querySelector('.ulu-desktop-profile-sidebar').innerHTML=desktopProfileSidebarHTML(title);var main=shell.querySelector('.ulu-desktop-profile-main');main.innerHTML='<div class="ulu-desktop-profile-stage-inner"><div class="ulu-desktop-profile-stage-grid"><div class="ulu-desktop-profile-content">'+profileDestinationHTML(title)+'</div>'+desktopProfileRailHTML(title)+'</div></div>';shell.hidden=false;document.body.classList.add('ulu-desktop-profile-open');main.scrollTop=0;
    scaleDesktopProfileText(shell);
    if(title==='Asset Vault' || title==='Approved Library'){
      scaleDesktopAssetVaultText(shell);
      requestAnimationFrame(function(){syncDesktopAssetVaultRailAlignment(shell);});
    }
    var body=shell.querySelector('.ulu-desktop-profile-content');
    if(title==='Thought Log'){try{var draft=localStorage.getItem('uluThoughtDraft');var ti=body.querySelector('[data-thought-input]');if(ti&&draft)ti.value=draft;}catch(_e){}}
    var roleSel=body.querySelector('[data-profile-field="role"]');if(roleSel)roleSel.value=uluProfileState.profile.role;
  }

  function renderDesktopProfileRaw(title,html,active){
    var shell=ensureDesktopProfileShell();sizeDesktopProfileShell(shell);shell.querySelector('.ulu-desktop-profile-sidebar').innerHTML=desktopProfileSidebarHTML(active||title);var main=shell.querySelector('.ulu-desktop-profile-main');main.innerHTML='<div class="ulu-desktop-profile-stage-inner"><div class="ulu-desktop-profile-stage-grid"><div class="ulu-desktop-profile-content">'+html+'</div>'+desktopProfileRailHTML(title)+'</div></div>';shell.hidden=false;document.body.classList.add('ulu-desktop-profile-open');main.scrollTop=0;
    scaleDesktopProfileText(shell);
    if(title==='Asset Vault' || title==='Approved Library'){
      scaleDesktopAssetVaultText(shell);
      requestAnimationFrame(function(){syncDesktopAssetVaultRailAlignment(shell);});
    }
  }

  function closeDesktopProfileShell(){
    var shell=document.getElementById('uluDesktopProfileShell');if(shell)shell.hidden=true;document.body.classList.remove('ulu-desktop-profile-open');
  }

  function profileWorkspaceBody(root){return q('.ulu-mobile-profile-frame-body',root)||q('.ulu-desktop-profile-content',root)||root;}
  function profileWorkspaceTitle(root,title){var node=q('.ulu-mobile-profile-frame-title',root);if(node)node.textContent=title||'Profile & Blueprint';}

  document.addEventListener('click',function(e){
    if(isMobile()) return;
    var profile=e.target.closest('[data-ulu-mobile-profile], [data-ulu-profile-link], .topbar-right .icon-btn[aria-label="Account"], .topbar-right a[href*="profile"], .topbar-right button[aria-label="Profile"]');
    if(profile){e.preventDefault();e.stopImmediatePropagation();showDesktopProfileRoot();return;}
    if(e.target.closest('[data-ulu-desktop-profile-home]')){e.preventDefault();e.stopPropagation();showDesktopProfileRoot();return;}
    var shell=e.target.closest('#uluDesktopProfileShell');
    if(shell && e.target.closest('[data-ulu-profile-destination]')){e.preventDefault();e.stopPropagation();openDesktopProfileDestination(e.target.closest('[data-ulu-profile-destination]').getAttribute('data-ulu-profile-destination'));return;}
    if(document.body.classList.contains('ulu-desktop-profile-open') && e.target.closest('.main-tab[data-main], [data-main="signals"], [data-main="brand"], [data-main="media"]')) closeDesktopProfileShell();
  },true);

  window.addEventListener('resize',function(){var shell=document.getElementById('uluDesktopProfileShell');if(shell&&!shell.hidden&&!isMobile()){sizeDesktopProfileShell(shell);syncDesktopAssetVaultRailAlignment(shell);}},{passive:true});

  /* v52: Dedicated Profile & Blueprint mobile frame. This intentionally does
     not use #uluMobileDrawer, role=dialog, aria-modal, a backdrop, or slide-in
     animation. It behaves like a mobile route/destination and preserves the
     persistent Signals / Brand Voice / Media navigation below it. */
  var profileFramePage = 'root';

  function ensureProfileFrame(){
    var frame = document.getElementById('uluMobileProfileFrame');
    if (frame){
      if (frame.parentElement !== document.documentElement) document.documentElement.appendChild(frame);
      return frame;
    }
    frame = document.createElement('section');
    frame.id = 'uluMobileProfileFrame';
    frame.className = 'ulu-mobile-profile-frame';
    frame.hidden = true;
    frame.setAttribute('role','region');
    frame.setAttribute('aria-label','Profile & Blueprint');
    frame.innerHTML = '<header class="ulu-mobile-profile-frame-head"><button class="ulu-mobile-profile-frame-back" type="button" aria-label="Back">‹</button><h2 class="ulu-mobile-profile-frame-title">Profile &amp; Blueprint</h2><span></span></header><div class="ulu-mobile-profile-frame-body"></div>';
    document.documentElement.appendChild(frame);
    frame.querySelector('.ulu-mobile-profile-frame-back').addEventListener('click', function(){
      if (profileFramePage === 'plan'){ openProfileDestination('Account Settings'); return; }
      if (String(profileFramePage).indexOf('asset-detail:') === 0){ openProfileDestination('Asset Vault'); return; }
      if (profileFramePage === 'asset-vault'){ openProfileDestination('Asset Vault'); return; }
      if (profileFramePage === 'thought-all'){ openProfileDestination('Thought Log'); return; }
      if (String(profileFramePage).indexOf('thought-detail:') === 0){ openProfileDestination('Thought Log'); return; }
      if (profileFramePage !== 'root'){ showProfileFrameRoot(); }
      else { closeProfileFrame(); }
    });
    return frame;
  }

  function showProfileFrameRoot(){
    if (!isMobile()) return;
    var frame = ensureProfileFrame();
    profileFramePage = 'root';
    q('.ulu-mobile-profile-frame-title',frame).textContent = 'Profile & Blueprint';
    var body = q('.ulu-mobile-profile-frame-body',frame);
    body.innerHTML = profileHTML();
    body.scrollTop = 0;
    frame.hidden = false;
    document.body.classList.add('ulu-mobile-profile-open');
  }

  function openProfileFrame(){
    if (!isMobile()) return;
    /* Make Profile a mutually exclusive major workspace. Any legacy drawer is
       closed first so two mobile panels can never occupy the screen together. */
    closeDrawer(true);
    showProfileFrameRoot();
  }

  function openProfileDestination(title){
    if (!isMobile()){ openDesktopProfileDestination(title); return; }
    var frame = ensureProfileFrame();
    profileFramePage = title || 'destination';
    q('.ulu-mobile-profile-frame-title',frame).textContent = title || 'Profile & Blueprint';
    var body = q('.ulu-mobile-profile-frame-body',frame);
    body.innerHTML = profileDestinationHTML(title);
    if(title==='Thought Log'){ try{ var draft=localStorage.getItem('uluThoughtDraft'); var ti=body.querySelector('[data-thought-input]'); if(ti && draft) ti.value=draft; }catch(_e){} }
    var roleSel=body.querySelector('[data-profile-field="role"]'); if(roleSel) roleSel.value=uluProfileState.profile.role;
    var goalSel=body.querySelector('[data-profile-field="goal"]'); if(goalSel) goalSel.value=uluProfileState.profile.goal;
    body.scrollTop = 0;
    frame.hidden = false;
    document.body.classList.add('ulu-mobile-profile-open');
  }

  function closeProfileFrame(immediate){
    var frame = document.getElementById('uluMobileProfileFrame');
    if (!frame) return;
    frame.hidden = true;
    profileFramePage = 'root';
    var body = q('.ulu-mobile-profile-frame-body',frame);
    if (body) body.innerHTML = '';
    document.body.classList.remove('ulu-mobile-profile-open');
  }

  function ensureMobileMainTabs(){
    if (!isMobile()) return;
    var nav = q('.mobile-main-tabs');
    if (!nav){
      nav = document.createElement('nav');
      nav.className = 'mobile-main-tabs ulu-mobile-created-main-tabs';
      nav.setAttribute('aria-label','Primary navigation');
      nav.innerHTML = '<button class="main-tab" type="button" data-main="signals" aria-selected="false"><span aria-hidden="true">◔</span><span>Signals</span></button><button class="main-tab" type="button" data-main="brand" aria-selected="false"><span aria-hidden="true">◇</span><span>Brand Voice</span></button><button class="main-tab" type="button" data-main="media" aria-selected="false"><span aria-hidden="true">▣</span><span>Media</span></button>' ;
      document.documentElement.appendChild(nav);
      nav.addEventListener('click', function(e){
        var btn=e.target.closest('.main-tab[data-main]');
        if(!btn) return;
        var key=btn.getAttribute('data-main');
        var desktop=qa('.main-tab[data-main="'+key+'"]',document).find(function(x){return x!==btn && !x.closest('.mobile-main-tabs');});
        if(desktop) desktop.click();
        setTimeout(syncMobileMainTabs,0);
      });
    }
    nav.style.removeProperty('display');
    syncMobileMainTabs();
  }

  function syncMobileMainTabs(){
    var nav=q('.mobile-main-tabs');
    if(!nav) return;
    var selected='signals';
    var desktopSelected=qa('.main-tab[aria-selected="true"]',document).find(function(x){return !x.closest('.mobile-main-tabs');});
    if(desktopSelected && desktopSelected.dataset.main) selected=desktopSelected.dataset.main;
    nav.querySelectorAll('.main-tab[data-main]').forEach(function(btn){btn.setAttribute('aria-selected',String(btn.dataset.main===selected));});
  }

  function currentMainLabel(){
    var active = q('.mobile-main-tabs .main-tab[aria-selected="true"]');
    if (!active) return '';
    var key = active.getAttribute('data-main');
    return key === 'brand' ? 'Brand Voice' : key === 'media' ? 'Media' : 'Signals';
  }

  function enhanceBrand(){
    var ws = q('#brandVoiceWorkspace');
    if (!ws) return;
    var isDetail = !!q('.bv-inline-detail', ws);
    ws.classList.toggle('ulu-mobile-detail-active', isDetail);
    if (!isDetail){
      if (!q('.ulu-mobile-brand-head', ws)){
        var content = q('[data-bv-content]', ws) || ws;
        var head = document.createElement('div');
        head.className = 'ulu-mobile-brand-head';
        head.innerHTML = pageHeader('Brand Voice','');
        content.insertBefore(head, content.firstChild);
      }
      return;
    }
    var editor = q('.bv-inline-editor', ws);
    if (editor && !q('.bv-mobile-panel-launchers', editor)){
      var launchers = document.createElement('div');
      launchers.className = 'bv-mobile-panel-launchers';
      launchers.innerHTML = '<button type="button" data-bv-side-tab="angles">Angles</button><button type="button" data-bv-side-tab="history">History</button><button type="button" data-bv-side-tab="performance">Performance</button><button type="button" data-bv-side-tab="comments">Comments</button>';
      editor.insertBefore(launchers, editor.firstChild);
    }
    var side = q('.bv-inline-side', ws);
    if (side){
      var isGuidanceView = !!q('.bv-guidance-execution', side);
      var isAskView = side.classList.contains('is-ask-al-view') || !!q('.bv-ask-al-panel-head', side);
      side.classList.toggle('ulu-mobile-guidance-view', isGuidanceView);
      side.classList.toggle('ulu-mobile-ask-view', isAskView);
      side.setAttribute('data-ulu-mobile-title', 'Communication Detail');
      /* Angles / History / Performance / Comments now render their own Back
         control inside the Viewing header. Do not inject the legacy floating
         close button into those subpanels, or two arrows can overlap. */
      var hasIntegratedMobileBack = !!q('.bv-mobile-subpanel-head-v15 .bv-inline-side-header-back-v15', side);
      if (hasIntegratedMobileBack){
        qa('.bv-inline-side-close', side).forEach(function(btn){ btn.remove(); });
      } else if (!q('.bv-inline-side-close', side)){
        var close = document.createElement('button');
        close.type = 'button'; close.className = 'bv-inline-side-close'; close.setAttribute('aria-label','Close panel'); close.textContent = '‹';
        side.insertBefore(close, side.firstChild);
        close.addEventListener('click', function(){ side.classList.remove('ulu-mobile-side-open'); document.body.classList.remove('ulu-mobile-drawer-open'); });
      }
      if (lastSideIntent){
        side.classList.add('ulu-mobile-side-open');
        document.body.classList.add('ulu-mobile-drawer-open');
        lastSideIntent = '';
      }
    }
  }

  function cleanupMobileExperience(){
    /*
       Mobile enhancement markup is injected into the live desktop DOM.
       When the viewport crosses back above 820px, remove every mobile-only
       artifact and state flag so the original desktop markup is restored.
       Removing the enhancement flags is important: it also allows the mobile
       shells to be rebuilt cleanly if the viewport is narrowed again later.
    */
    closeDrawer(true);
    closeProfileFrame(true);
    syncMobileLogo(false);
    document.body.classList.remove('ulu-mobile-drawer-open');

    qa('.ulu-mobile-signals-shell,.ulu-mobile-media-shell,.ulu-mobile-brand-head,.bv-mobile-panel-launchers').forEach(function(el){
      el.remove();
    });
    qa('.ulu-mobile-created-main-tabs').forEach(function(el){ el.remove(); });

    qa('.signals-dashboard.ulu-mobile-hubbed,.media-dashboard.ulu-mobile-hubbed').forEach(function(dash){
      dash.classList.remove('ulu-mobile-hubbed');
      delete dash.dataset.uluMobileEnhanced;
    });

    var brandWs = q('#brandVoiceWorkspace');
    if (brandWs) brandWs.classList.remove('ulu-mobile-detail-active');

    qa('#brandVoiceWorkspace .bv-inline-side').forEach(function(side){
      side.classList.remove('ulu-mobile-side-open');
      side.removeAttribute('data-ulu-mobile-title');
    });
    qa('#brandVoiceWorkspace .bv-inline-side-close').forEach(function(btn){
      btn.remove();
    });

    lastSideIntent = '';

    /* A mobile filter drawer can temporarily place #globalFilters inline and
       assign display:block. closeDrawer() restores its DOM position, but clear
       the inline display so desktop CSS regains full control. */
    var gf = q('#globalFilters');
    if (gf) gf.style.removeProperty('display');

    /* Reflow charts after restoring the desktop hierarchy. */
    var content = q('#content');
    if (content) resizeCharts(content);
    setTimeout(function(){ if (content) resizeCharts(content); }, 80);
  }

  function enhance(){
    if (!isMobile()){
      cleanupMobileExperience();
      return;
    }
    closeDesktopProfileShell();
    syncMobileLogo(true);
    ensureMobileMainTabs();
    enhanceSignals();
    enhanceMedia();
    enhanceBrand();
  }

  document.addEventListener('click', function(e){
    if (!isMobile()) return;
    var profile = e.target.closest('[data-ulu-mobile-profile], .topbar-right .icon-btn[aria-label="Account"]');
    if (profile){ e.preventDefault(); e.stopPropagation(); openProfileFrame(); return; }
    /* Selecting a primary tab exits the dedicated Profile destination first. */
    if (e.target.closest('.mobile-main-tabs .main-tab[data-main]')) closeProfileFrame(true);
    if (e.target.closest('[data-ulu-mobile-filters]')){ e.preventDefault(); openFilters(); return; }
    if (e.target.closest('[data-ulu-mobile-asset-vault]')){
      e.preventDefault();
      e.stopPropagation();
      closeDrawer(true);
      openProfileDestination('Asset Vault');
      return;
    }
    var sideBtn = e.target.closest('#brandVoiceWorkspace [data-bv-side-tab]');
    if (sideBtn){
      var names = {angles:'Strategy Angles',history:'History',performance:'Performance',comments:'Comments',guidance:'ULU Guidance'};
      lastSideIntent = names[sideBtn.getAttribute('data-bv-side-tab')] || 'Details';
    }
    if (e.target.closest('#brandVoiceWorkspace [data-bv-toggle-ask]')) lastSideIntent = 'Ask AL';
  }, true);

  var ULU_ASSET_PREVIEW_DEMO_VIDEO='https://www.instagram.com/reels/DdhhjiiP0x9/';

  function assetPreviewKind(asset){
    var type=String(asset&&asset.type||'').toLowerCase();
    var url=String(asset&&asset.previewUrl||'').toLowerCase();
    if(type.indexOf('video')>-1 || /\.(mp4|webm|mov|m4v)(?:[?#]|$)/.test(url) || url.indexOf('instagram.com/reel')>-1) return 'video';
    if(type.indexOf('image')>-1 || /\.(png|jpe?g|gif|webp|avif|svg)(?:[?#]|$)/.test(url)) return 'image';
    return 'text';
  }

  function instagramEmbedUrl(url){
    var value=String(url||'').trim();
    var match=value.match(/instagram\.com\/(?:reels?|p)\/([^/?#]+)/i);
    return match ? 'https://www.instagram.com/reel/'+match[1]+'/embed/' : value;
  }

