  function decorateVersionActions(){
    var actions = q('#brandVoiceWorkspace .bv-version-header-actions');
    if (!actions) return;
    /* Dedicated mobile-only presentation class. This isolates the compact
       action strip from the legacy desktop/narrow-container button rules. */
    actions.classList.add('ulu-mobile-version-actions');
    var header = actions.closest('.bv-version-header-frame');
    if (header) header.classList.add('ulu-mobile-version-header');
    var defs = [
      ['.bv-ulu-guidance-action','ULU Guidance','logos/aa_guidance_icon.svg'],
      ['.bv-ask-al-inline','Ask AL','logos/Ask-AL-100.png'],
      ['.bv-copy-deploy-inline','Copy & Deploy','logos/aa_deploy_icon.svg'],
      ['.bv-save-inline','Save','logos/aa_save_icon.svg'],
      ['.bv-delete-version-inline','Delete','logos/aa_delete_icon.svg'],
      ['.bv-hierarchy-primary-create','Add Angle','logos/aa_addnew_icon.svg']
    ];
    defs.forEach(function(def){
      var btn = q(def[0], actions);
      if (!btn) return;
      btn.setAttribute('data-ulu-mobile-tip',def[1]);
      btn.setAttribute('title',def[1]);
      btn.setAttribute('aria-label',def[1]);
      var icon = q('.ulu-mobile-action-icon',btn);
      if (!icon){
        icon=document.createElement('img');
        icon.className='ulu-mobile-action-icon';
        icon.alt='';
        icon.setAttribute('aria-hidden','true');
        btn.appendChild(icon);
      }
      icon.src=def[2];
    });
  }


