/* Mobile keyboard dismissal cleanup v43. Safari may deliver its final
   VisualViewport resize/scroll callbacks out of order after the keyboard closes.
   Re-run the canonical hardening path after blur and force the residual inset to
   zero once no text-entry control owns focus. This is intentionally global so
   Guidance, Ask AL and any other mobile textarea recover the full workspace. */
(function(){
  'use strict';
  function isMobile(){
    return window.innerWidth<=820 || (window.matchMedia&&window.matchMedia('(max-width:820px)').matches);
  }
  function hasTextFocus(){
    var ae=document.activeElement;
    return !!(ae && ((ae.matches&&ae.matches('textarea,input:not([type]),input[type="text"],input[type="search"],input[type="email"],input[type="url"],input[type="tel"],input[type="number"],input[type="password"]')) || ae.isContentEditable));
  }
  function clearResidualKeyboardInset(){
    if(!isMobile() || hasTextFocus()) return;
    document.documentElement.style.setProperty('--ulu-mobile-visual-bottom','0px');
    var nav=document.querySelector('.mobile-main-tabs');
    if(nav){
      nav.style.setProperty('bottom','0px','important');
    }
  }
  function settle(){
    [0,80,180,360,650].forEach(function(ms){setTimeout(clearResidualKeyboardInset,ms);});
  }
  document.addEventListener('focusout',function(e){
    if(!isMobile()) return;
    var t=e.target;
    if(!t || !(t.matches&&t.matches('textarea,input,[contenteditable="true"]'))) return;
    settle();
  },true);
  document.addEventListener('visibilitychange',function(){if(!document.hidden)settle();});
  window.addEventListener('resize',function(){if(!hasTextFocus())settle();},{passive:true});
  if(window.visualViewport){
    window.visualViewport.addEventListener('resize',function(){if(!hasTextFocus())settle();},{passive:true});
  }
})();


