/* === Mobile viewport containment v29 =====================================
   Keep the application layout anchored to the phone viewport without
   disabling legitimate horizontal scrolling inside purpose-built scrollers.
   This is intentionally mobile-only and runs after the older responsive
   patches so it wins the cascade. */
(function installUluMobileViewportContainmentV29(){
  if(window.__uluMobileViewportContainmentV29Installed)return;
  window.__uluMobileViewportContainmentV29Installed=true;

  const css=`
    @media (max-width:820px){
      html,body{
        width:100%!important;
        max-width:100%!important;
        overflow-x:hidden!important;
        overscroll-behavior-x:none!important;
      }
      body.ulu-mobile-full-bleed{
        width:100%!important;
        max-width:100%!important;
        min-width:0!important;
        overflow-x:hidden!important;
        position:relative!important;
      }

      /* Main app shells and the three primary navigation workspaces must never
         become a page-level horizontal scroller. */
      body.ulu-mobile-full-bleed #app,
      body.ulu-mobile-full-bleed .app,
      body.ulu-mobile-full-bleed .app-shell,
      body.ulu-mobile-full-bleed .page-shell,
      body.ulu-mobile-full-bleed .site-shell,
      body.ulu-mobile-full-bleed main,
      body.ulu-mobile-full-bleed #content,
      body.ulu-mobile-full-bleed #content > .card,
      body.ulu-mobile-full-bleed .signals-dashboard,
      body.ulu-mobile-full-bleed #brandVoiceWorkspace,
      body.ulu-mobile-full-bleed .media-dashboard{
        width:100%!important;
        max-width:100%!important;
        min-width:0!important;
        margin-left:0!important;
        margin-right:0!important;
        box-sizing:border-box!important;
      }
      body.ulu-mobile-full-bleed #content,
      body.ulu-mobile-full-bleed #brandVoiceWorkspace,
      body.ulu-mobile-full-bleed .signals-dashboard,
      body.ulu-mobile-full-bleed .media-dashboard{
        overflow-x:clip!important;
      }

      /* Communication Detail and its normal mobile panels should stay within
         the viewport. Purpose-built inner scrollers keep their own overflow. */
      #brandVoiceWorkspace .bv-detail-shell,
      #brandVoiceWorkspace .bv-detail-layout,
      #brandVoiceWorkspace .bv-detail-main,
      #brandVoiceWorkspace .bv-version-workspace,
      #brandVoiceWorkspace .bv-version-editor,
      #brandVoiceWorkspace .bv-version-editor-shell,
      #brandVoiceWorkspace .bv-document-canvas,
      #brandVoiceWorkspace .bv-mobile-detail-subpanel,
      #brandVoiceWorkspace .ulu-mobile-detail-subpanel{
        width:100%!important;
        max-width:100%!important;
        min-width:0!important;
        box-sizing:border-box!important;
      }

      /* Body-level dialogs/popups are also capped to the visual width. */
      body.ulu-mobile-full-bleed > dialog,
      body.ulu-mobile-full-bleed > [role="dialog"],
      body.ulu-mobile-full-bleed > .tooltip-float,
      body.ulu-mobile-full-bleed > .bv-delete-unavailable-tooltip{
        max-width:calc(100dvw - 24px)!important;
        box-sizing:border-box!important;
      }

      img,video,canvas,svg{max-width:100%;}
    }
  `;
  const style=document.createElement('style');
  style.id='uluMobileViewportContainmentV29Styles';
  style.textContent=css;
  document.head.appendChild(style);

  function isMobile(){
    return window.innerWidth<=820 || (window.matchMedia&&window.matchMedia('(max-width:820px)').matches);
  }
  let raf=0;
  function snapPageBack(){
    if(!isMobile())return;
    const vv=window.visualViewport;
    /* Do not fight intentional pinch-zoom panning. */
    if(vv&&vv.scale&&vv.scale>1.01)return;
    cancelAnimationFrame(raf);
    raf=requestAnimationFrame(()=>{
      const root=document.scrollingElement||document.documentElement;
      const y=root?root.scrollTop:(window.scrollY||0);
      if(root&&root.scrollLeft!==0)root.scrollLeft=0;
      if(document.documentElement.scrollLeft!==0)document.documentElement.scrollLeft=0;
      if(document.body.scrollLeft!==0)document.body.scrollLeft=0;
      if((window.scrollX||window.pageXOffset||0)!==0){
        try{window.scrollTo(0,y)}catch(e){}
      }
    });
  }

  window.addEventListener('scroll',snapPageBack,{passive:true});
  window.addEventListener('resize',snapPageBack,{passive:true});
  window.addEventListener('orientationchange',()=>setTimeout(snapPageBack,60),{passive:true});
  document.addEventListener('touchend',snapPageBack,{passive:true});
  if(window.visualViewport){
    window.visualViewport.addEventListener('resize',snapPageBack,{passive:true});
    window.visualViewport.addEventListener('scroll',snapPageBack,{passive:true});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',snapPageBack,{once:true});
  else snapPageBack();
})();

