/* v41: legacy v37 Guidance/Ask controller removed. */

/* Mobile layout revisions v36: iOS Safari form-control anti-zoom safeguard.
   On iPhone Safari, text-entry controls rendered below 16px can trigger browser
   auto-zoom when focused. This mobile-only layer raises text-entry inputs and
   textareas across the app to a minimum effective size of 16px without changing
   desktop styling. It explicitly covers ULU Guidance and Ask AL as well as
   dynamically rendered text-entry controls elsewhere in the SPA. */
(function(){
  var STYLE_ID='uluMobileTextEntryMin16V36';
  var MOBILE_BP=820;
  var old=document.getElementById(STYLE_ID);
  if(old) old.remove();
  var style=document.createElement('style');
  style.id=STYLE_ID;
  style.textContent=`
    @media (max-width:820px){
      /* ULU Guidance + Ask AL conversation composers. */
      #brandVoiceWorkspace .ulu-mobile-guidance-view .bv-context-compose textarea,
      #brandVoiceWorkspace .bv-guidance-execution .bv-context-compose textarea,
      #brandVoiceWorkspace .ulu-mobile-ask-view .bv-context-compose textarea,
      #brandVoiceWorkspace .bv-context-compose textarea,

      /* App-wide text-entry inputs that can summon the iOS keyboard. */
      input:not([type]),
      input[type="text"],
      input[type="search"],
      input[type="email"],
      input[type="url"],
      input[type="tel"],
      input[type="password"],
      input[type="number"],
      input[type="date"],
      input[type="datetime-local"],
      input[type="month"],
      input[type="time"],
      input[type="week"],
      textarea{
        font-size:16px!important;
      }
    }
  `;
  document.head.appendChild(style);

  /* Runtime safety net for controls added later by SPA rendering. This only
     raises controls whose computed size is still below 16px. */
  function isMobile(){
    return window.innerWidth<=MOBILE_BP || (window.matchMedia&&window.matchMedia('(max-width:820px)').matches);
  }
  function isTextEntry(el){
    if(!el||el.nodeType!==1) return false;
    if(el.tagName==='TEXTAREA') return true;
    if(el.tagName!=='INPUT') return false;
    var t=(el.getAttribute('type')||'text').toLowerCase();
    return ['text','search','email','url','tel','password','number','date','datetime-local','month','time','week'].indexOf(t)!==-1;
  }
  function ensureMin16(el){
    if(!isMobile()||!isTextEntry(el)) return;
    var n=parseFloat(window.getComputedStyle(el).fontSize||'0');
    if(!isFinite(n)||n<16) el.style.setProperty('font-size','16px','important');
  }
  document.addEventListener('focusin',function(e){ensureMin16(e.target);},true);
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){
      document.querySelectorAll('textarea,input').forEach(ensureMin16);
    },{once:true});
  }else{
    document.querySelectorAll('textarea,input').forEach(ensureMin16);
  }
})();



