(function installULUMobileCreationFrameV51(){
  'use strict';
  if(window.__uluMobileCreationFrameV51Installed)return;
  window.__uluMobileCreationFrameV51Installed=true;
  var MOBILE_BP=820;
  var STYLE_ID='uluMobileCreationFrameV51Styles';

  function isMobile(){
    return window.innerWidth<=MOBILE_BP || (window.matchMedia&&window.matchMedia('(max-width:820px)').matches);
  }
  function decorate(){
    if(!isMobile())return;
    ['bvCommunicationCreateModal','bvVersionCreateModal'].forEach(function(id){
      var dlg=document.getElementById(id);
      if(!dlg)return;
      dlg.classList.add('ulu-mobile-hierarchy-create-v51');
      var card=dlg.querySelector('.bv-creation-card');
      var head=dlg.querySelector('.bv-creation-head');
      var body=dlg.querySelector('.bv-creation-body');
      var footer=dlg.querySelector('.bv-creation-footer');
      if(card)card.classList.add('ulu-mobile-hierarchy-card-v51');
      if(head)head.classList.add('ulu-mobile-hierarchy-head-v51');
      if(body)body.classList.add('ulu-mobile-hierarchy-body-v51');
      if(footer)footer.classList.add('ulu-mobile-hierarchy-footer-v51');
      if(dlg.open){
        try{dlg.scrollTop=0;}catch(_e){}
        try{if(body)body.scrollTop=0;}catch(_e){}
      }
    });
  }

  if(!document.getElementById(STYLE_ID)){
    var style=document.createElement('style');
    style.id=STYLE_ID;
    style.textContent=`
      @media(max-width:820px){
        /* Communication and Version creation are mobile destinations, not a
           vertically-centered desktop dialog. The header always occupies the
           first row, the form is the only scrolling region, and the action row
           stays visible at the bottom. */
        #bvCommunicationCreateModal.ulu-mobile-hierarchy-create-v51[open],
        #bvVersionCreateModal.ulu-mobile-hierarchy-create-v51[open]{
          display:block!important;
          position:fixed!important;
          left:0!important;right:0!important;top:0!important;
          bottom:calc(var(--ulu-mobile-nav-box-h,64px) + env(safe-area-inset-bottom))!important;
          inset:0 0 calc(var(--ulu-mobile-nav-box-h,64px) + env(safe-area-inset-bottom)) 0!important;
          width:auto!important;max-width:none!important;
          height:auto!important;max-height:none!important;
          margin:0!important;padding:0!important;
          overflow:hidden!important;border:0!important;border-radius:0!important;
          background:#041a38!important;box-sizing:border-box!important;
          transform:none!important;z-index:2147483450!important;
        }
        #bvCommunicationCreateModal.ulu-mobile-hierarchy-create-v51 > .ulu-mobile-hierarchy-card-v51,
        #bvVersionCreateModal.ulu-mobile-hierarchy-create-v51 > .ulu-mobile-hierarchy-card-v51{
          display:grid!important;grid-template-rows:auto minmax(0,1fr) auto!important;
          width:100%!important;height:100%!important;min-width:0!important;min-height:0!important;
          max-width:100%!important;max-height:100%!important;
          margin:0!important;padding:0!important;overflow:hidden!important;
          border-radius:0!important;box-sizing:border-box!important;
        }
        #bvCommunicationCreateModal .ulu-mobile-hierarchy-head-v51,
        #bvVersionCreateModal .ulu-mobile-hierarchy-head-v51{
          display:flex!important;visibility:visible!important;opacity:1!important;
          position:relative!important;top:auto!important;left:auto!important;right:auto!important;
          flex:0 0 auto!important;z-index:4!important;
          margin:0!important;padding:14px 16px 12px!important;
          background:linear-gradient(180deg,#092b55,#071f43)!important;
          border-bottom:1px solid rgba(117,214,255,.26)!important;
          box-sizing:border-box!important;
        }
        #bvCommunicationCreateModal .ulu-mobile-hierarchy-head-v51 .bv-creation-kicker,
        #bvVersionCreateModal .ulu-mobile-hierarchy-head-v51 .bv-creation-kicker{
          display:block!important;font-size:12px!important;line-height:1.2!important;
          color:#75d6ff!important;
        }
        #bvCommunicationCreateModal .ulu-mobile-hierarchy-head-v51 h3,
        #bvVersionCreateModal .ulu-mobile-hierarchy-head-v51 h3{
          display:block!important;margin:4px 36px 0 0!important;
          font-size:21px!important;line-height:1.15!important;color:#fff!important;
        }
        #bvCommunicationCreateModal .ulu-mobile-hierarchy-head-v51 p,
        #bvVersionCreateModal .ulu-mobile-hierarchy-head-v51 p{
          margin:6px 36px 0 0!important;font-size:13px!important;line-height:1.38!important;
        }
        #bvCommunicationCreateModal .ulu-mobile-hierarchy-body-v51,
        #bvVersionCreateModal .ulu-mobile-hierarchy-body-v51{
          min-height:0!important;height:auto!important;max-height:none!important;
          overflow-y:auto!important;overflow-x:hidden!important;
          -webkit-overflow-scrolling:touch!important;overscroll-behavior:contain!important;
          padding:14px 16px 18px!important;box-sizing:border-box!important;
        }
        #bvCommunicationCreateModal .ulu-mobile-hierarchy-footer-v51,
        #bvVersionCreateModal .ulu-mobile-hierarchy-footer-v51{
          flex:0 0 auto!important;margin:0!important;padding:10px 14px calc(12px + env(safe-area-inset-bottom))!important;
          background:#071f43!important;border-top:1px solid rgba(117,214,255,.22)!important;
          position:relative!important;z-index:4!important;box-sizing:border-box!important;
        }

        /* Create Strategy Angle already has the v24 mobile frame; reinforce its
           title row so all three hierarchy-create destinations present a clear
           headline at the top of the mobile workspace. */
        #bvAngleModal.ulu-mobile-add-angles[open] .bv-strategy-modal-head{
          display:flex!important;visibility:visible!important;opacity:1!important;
          position:relative!important;top:auto!important;z-index:5!important;
          background:linear-gradient(180deg,#092b55,#071f43)!important;
        }
        #bvAngleModal.ulu-mobile-add-angles[open] .bv-strategy-modal-title{
          display:block!important;color:#fff!important;font-size:21px!important;line-height:1.15!important;
        }
      }
    `;
    document.head.appendChild(style);
  }

  if(window.MutationObserver){
    new MutationObserver(function(muts){
      for(var i=0;i<muts.length;i++){
        if(muts[i].type==='childList' || (muts[i].type==='attributes'&&muts[i].attributeName==='open')){
          decorate();
          break;
        }
      }
    }).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['open']});
  }
  document.addEventListener('click',function(e){
    if(!isMobile())return;
    if(e.target&&e.target.closest&&e.target.closest('[data-bv-create-communication],[data-bv-create-version],[data-bv-create-strategy-angle]')){
      [0,40,120].forEach(function(ms){setTimeout(decorate,ms);});
    }
  },true);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',decorate,{once:true});else decorate();
  window.addEventListener('resize',decorate,{passive:true});
  window.addEventListener('orientationchange',decorate,{passive:true});
})();

