/* ========================================================================== */
/* ULUsignals Profile Mobile Minimum Typography v85                           */
/* - Thought Log draft note: +20% (11.31px -> 14px)                       */
/* - Enforce 14px as the minimum rendered text size throughout the six    */
/*   Profile & Blueprint mobile destination panels without shrinking any text */
/*   that is already larger.                                                   */
/* ========================================================================== */
(function installULUProfileMobileMinimumTypographyV85(){
  'use strict';
  if(window.__uluProfileMobileMinimumTypographyV85Installed)return;
  window.__uluProfileMobileMinimumTypographyV85Installed=true;

  var MIN_PX=14;
  var FRAME_ID='uluMobileProfileFrame';
  var BODY_SELECTOR='.ulu-mobile-profile-frame-body';
  var STYLE_ID='uluProfileMobileMinimumTypographyV85Styles';
  var SKIP_CLASS_RE=/(?:^|[-_])(icon|ico|glyph|avatar|mic)(?:$|[-_])/i;
  var TEXT_SELECTOR='h1,h2,h3,h4,h5,h6,p,span,small,label,a,button,strong,b,em,i,li,dt,dd,th,td,input,select,option,textarea,div';

  var old=document.getElementById(STYLE_ID);if(old)old.remove();
  var style=document.createElement('style');
  style.id=STYLE_ID;
  style.textContent=`
    @media(max-width:820px){
      /* The requested 20% increase is explicit so it is deterministic even
         before the runtime minimum-size audit runs. */
      #${FRAME_ID} ${BODY_SELECTOR} [data-thought-draft-note]{
        font-size:${MIN_PX}px!important;
        line-height:1.38!important;
      }
    }
  `;
  document.head.appendChild(style);

  function isMobile(){return window.matchMedia&&window.matchMedia('(max-width:820px)').matches;}

  function hasOwnReadableText(el){
    if(!el)return false;
    var tag=el.tagName;
    if(tag==='INPUT'||tag==='SELECT'||tag==='OPTION'||tag==='TEXTAREA')return true;
    if(SKIP_CLASS_RE.test(String(el.className||'')))return false;
    for(var n=el.firstChild;n;n=n.nextSibling){
      if(n.nodeType===3&&String(n.nodeValue||'').trim())return true;
    }
    return false;
  }

  function enforceMinimum(root){
    if(!isMobile())return;
    var frame=document.getElementById(FRAME_ID);
    if(!frame||frame.hidden)return;
    var body=frame.querySelector(BODY_SELECTOR);
    if(!body)return;
    var scope=root&&root.nodeType===1&&body.contains(root)?root:body;
    var nodes=[];
    if(scope.matches&&scope.matches(TEXT_SELECTOR))nodes.push(scope);
    nodes=nodes.concat(Array.prototype.slice.call(scope.querySelectorAll(TEXT_SELECTOR)));
    nodes.forEach(function(el){
      if(!hasOwnReadableText(el))return;
      var cs=window.getComputedStyle(el);
      if(!cs||cs.display==='none'||cs.visibility==='hidden')return;
      var size=parseFloat(cs.fontSize)||0;
      if(size>0&&size<MIN_PX-0.01){
        el.style.setProperty('font-size',MIN_PX+'px','important');
      }
    });
  }

  var raf=0;
  function schedule(root){
    if(raf)cancelAnimationFrame(raf);
    raf=requestAnimationFrame(function(){raf=0;enforceMinimum(root);});
  }

  function attach(){
    var frame=document.getElementById(FRAME_ID);
    if(!frame){setTimeout(attach,120);return;}
    var body=frame.querySelector(BODY_SELECTOR);
    if(!body){setTimeout(attach,120);return;}
    enforceMinimum(body);
    if(window.MutationObserver){
      new MutationObserver(function(mutations){
        var root=body;
        for(var i=0;i<mutations.length;i++){
          var m=mutations[i];
          if(m.addedNodes&&m.addedNodes.length){
            for(var j=0;j<m.addedNodes.length;j++){
              if(m.addedNodes[j].nodeType===1){root=m.addedNodes[j];break;}
            }
          }
        }
        schedule(root);
      }).observe(body,{subtree:true,childList:true,characterData:true});
    }
  }

  document.addEventListener('click',function(e){
    if(!isMobile())return;
    if(e.target&&e.target.closest&&e.target.closest('#'+FRAME_ID+', [data-ulu-mobile-profile], [data-ulu-profile-link]'))setTimeout(function(){enforceMinimum();},0);
  },true);
  window.addEventListener('resize',function(){enforceMinimum();},{passive:true});
  window.addEventListener('orientationchange',function(){setTimeout(function(){enforceMinimum();},80);},{passive:true});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',attach,{once:true});else attach();
  window.addEventListener('load',function(){enforceMinimum();});
})();

